import React, { useMemo, useState, useEffect } from 'react';
import { Poseur, NextcloudConfig, ConstructionOrderData } from '../types';

interface CalendarManagerProps {
  poseurs: Poseur[];
  selectedPoseurId: string;
  data: ConstructionOrderData;
}

interface CalendarEvent {
  title: string;
  start: string;
  end: string;
  location?: string;
  isTentative?: boolean; // Pour le chantier en cours d'analyse
}

const CalendarManager: React.FC<CalendarManagerProps> = ({ poseurs, selectedPoseurId, data }) => {
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  const nextcloudConfigString = localStorage.getItem('buildscan_nextcloud');
  const nextcloudConfig: NextcloudConfig | null = nextcloudConfigString ? JSON.parse(nextcloudConfigString) : null;

  const selectedPoseur = useMemo(() => 
    poseurs.find(p => p.id === selectedPoseurId), 
  [poseurs, selectedPoseurId]);

  const webInterfaceUrl = useMemo(() => {
     if (!nextcloudConfig?.url) return null;
     return `${nextcloudConfig.url.replace(/\/$/, '')}/index.php/apps/calendar/`;
  }, [nextcloudConfig]);

  // Déterminer la date du chantier pour l'affichage
  const jobDate = useMemo(() => {
    // Essaie de parser la date d'intervention ou delai
    const dateStr = data.delai_intervention || data.date_intervention;
    if (!dateStr) return new Date();

    // Tentative de parsing simple FR (JJ/MM/AAAA)
    const parts = dateStr.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})/);
    if (parts) {
      return new Date(parseInt(parts[3]), parseInt(parts[2]) - 1, parseInt(parts[1]), 8, 0, 0); // 8h00 par défaut
    }
    return new Date(); // Fallback aujourd'hui
  }, [data.delai_intervention, data.date_intervention]);

  // Récupération des événements via le Proxy Server
  const fetchEvents = async () => {
    if (!selectedPoseurId || !selectedPoseur?.nextcloud_user) return;

    setIsLoading(true);
    setFetchError(null);
    try {
      const res = await fetch('/api/calendar/events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poseur_id: selectedPoseurId })
      });

      if (!res.ok) throw new Error("Erreur Serveur");

      const result = await res.json();
      if (result.success) {
        setEvents(result.events);
      } else {
        throw new Error(result.error);
      }
    } catch (e: any) {
      console.error("Erreur Fetch Calendar:", e);
      setFetchError("Impossible de récupérer l'agenda.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (selectedPoseurId) {
      setEvents([]); // Reset à chaque changement
      fetchEvents();
    }
  }, [selectedPoseurId]);

  // Fusionner les événements réels et le chantier proposé pour l'affichage
  const displayEvents = useMemo(() => {
    const list: CalendarEvent[] = [...events];

    // Ajouter le chantier actuel comme événement "Fantôme"
    if (data.nom_client) {
      const start = jobDate;
      const end = new Date(start);
      end.setHours(start.getHours() + 4); // Durée arbitraire de 4h

      list.push({
        title: `[NOUVEAU] ${data.nom_client}`,
        start: start.toISOString(),
        end: end.toISOString(),
        location: `${data.adresse_1} ${data.adresse_3}`,
        isTentative: true
      });
    }

    // Trier par date
    return list.sort((a, b) => new Date(a.start).getTime() - new Date(b.start).getTime());
  }, [events, data, jobDate]);

  // Générer les jours de la semaine autour de la date du chantier
  const weekDays = useMemo(() => {
    const days = [];
    const startOfWeek = new Date(jobDate);
    const day = startOfWeek.getDay();
    const diff = startOfWeek.getDate() - day + (day === 0 ? -6 : 1); // ajuster pour lundi
    startOfWeek.setDate(diff);

    for (let i = 0; i < 5; i++) { // Lundi à Vendredi
      const d = new Date(startOfWeek);
      d.setDate(startOfWeek.getDate() + i);
      days.push(d);
    }
    return days;
  }, [jobDate]);

  if (!nextcloudConfig) {
    return (
      <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800 p-6 flex flex-col items-center justify-center text-center h-full">
         <div className="w-12 h-12 bg-slate-800 text-slate-500 rounded-full flex items-center justify-center mb-3">
            <i className="fas fa-calendar-times"></i>
         </div>
         <p className="text-white font-bold text-sm">Calendrier non configuré</p>
         <p className="text-slate-500 text-[10px] mt-1">Rendez-vous dans Administration pour configurer Nextcloud.</p>
      </div>
    );
  }

  return (
    <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800 h-full flex flex-col">
       <div className="px-6 py-4 border-b border-slate-800 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-sky-600/20 text-sky-400 rounded flex items-center justify-center">
              <i className="fas fa-calendar-alt text-sm"></i>
            </div>
            <div>
              <h3 className="text-white font-bold uppercase tracking-wider text-xs">Agenda <span className="text-sky-400">Nextcloud</span></h3>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-tighter">
                {selectedPoseur ? `Disponibilités : ${selectedPoseur.nom}` : 'Sélectionnez un poseur'}
              </p>
            </div>
          </div>

          <div className="flex gap-2">
             <button 
                onClick={fetchEvents}
                disabled={isLoading || !selectedPoseur}
                className="text-slate-400 hover:text-white transition-colors disabled:opacity-50"
                title="Actualiser"
             >
                <i className={`fas fa-sync-alt ${isLoading ? 'fa-spin' : ''}`}></i>
             </button>
             {webInterfaceUrl && (
                <a 
                href={webInterfaceUrl} 
                target="_blank" 
                rel="noreferrer"
                className="text-slate-400 hover:text-white transition-colors"
                title="Ouvrir Nextcloud Web"
                >
                <i className="fas fa-external-link-alt"></i>
                </a>
             )}
          </div>
       </div>

       <div className="flex-grow flex flex-col overflow-hidden bg-slate-950">
         {!selectedPoseur ? (
            <div className="flex-grow flex flex-col items-center justify-center text-center p-4">
               <p className="text-slate-500 text-xs italic">Sélectionnez un poseur pour voir son agenda.</p>
            </div>
         ) : fetchError ? (
             <div className="flex-grow flex flex-col items-center justify-center text-center p-4">
               <i className="fas fa-exclamation-triangle text-red-500 mb-2"></i>
               <p className="text-red-400 text-xs font-bold">{fetchError}</p>
               <p className="text-slate-600 text-[10px]">Vérifiez la connexion Nextcloud dans Admin.</p>
            </div>
         ) : (
           <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
              {/* Vue Semaine Simplifiée */}
              <div className="space-y-4">
                 {weekDays.map(day => {
                    const dayEvents = displayEvents.filter(e => {
                        const evtDate = new Date(e.start);
                        return evtDate.getDate() === day.getDate() && 
                               evtDate.getMonth() === day.getMonth() &&
                               evtDate.getFullYear() === day.getFullYear();
                    });

                    const isJobDay = day.getDate() === jobDate.getDate() && day.getMonth() === jobDate.getMonth();

                    return (
                        <div key={day.toISOString()} className={`rounded-lg border ${isJobDay ? 'border-sky-800 bg-sky-900/10' : 'border-slate-800 bg-slate-900/50'} overflow-hidden`}>
                            <div className={`px-3 py-2 text-xs font-bold uppercase flex justify-between ${isJobDay ? 'text-sky-400' : 'text-slate-500'}`}>
                                <span>{day.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'short' })}</span>
                                {dayEvents.length > 0 && <span className="text-[10px] bg-slate-800 px-2 rounded-full text-slate-300">{dayEvents.length} évts</span>}
                            </div>

                            <div className="p-2 space-y-2">
                                {dayEvents.length === 0 ? (
                                    <div className="text-[10px] text-slate-700 italic pl-2 py-1">Aucun événement</div>
                                ) : (
                                    dayEvents.map((evt, idx) => (
                                        <div 
                                            key={idx} 
                                            className={`p-2 rounded text-[11px] border-l-2 flex flex-col gap-0.5 ${
                                                evt.isTentative 
                                                ? 'bg-orange-500/10 border-orange-500 text-orange-200 animate-pulse' 
                                                : 'bg-slate-800 border-sky-600 text-slate-300'
                                            }`}
                                        >
                                            <div className="flex justify-between items-start font-bold">
                                                <span>{new Date(evt.start).toLocaleTimeString('fr-FR', {hour: '2-digit', minute:'2-digit'})} - {new Date(evt.end).toLocaleTimeString('fr-FR', {hour: '2-digit', minute:'2-digit'})}</span>
                                                {evt.isTentative && <span className="text-[8px] bg-orange-500 text-black px-1 rounded font-black uppercase">Prévu</span>}
                                            </div>
                                            <div className="truncate font-medium" title={evt.title}>{evt.title}</div>
                                            {evt.location && <div className="text-[9px] text-slate-500 truncate"><i className="fas fa-map-marker-alt mr-1"></i>{evt.location}</div>}
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    );
                 })}
              </div>
           </div>
         )}
       </div>

       {/* Légende */}
       <div className="bg-slate-900 border-t border-slate-800 p-3 flex gap-4 justify-center text-[10px]">
          <div className="flex items-center gap-1.5">
             <div className="w-2 h-2 bg-sky-600 rounded-sm"></div>
             <span className="text-slate-400">Occupé (Nextcloud)</span>
          </div>
          <div className="flex items-center gap-1.5">
             <div className="w-2 h-2 bg-orange-500 rounded-sm animate-pulse"></div>
             <span className="text-slate-400">Ce Chantier</span>
          </div>
       </div>
    </div>
  );
};

export default CalendarManager;

import React, { useState, useCallback, useEffect } from 'react';
import { AppStatus, ConstructionOrderData, AppView, Client, Poseur, LogEntry } from './types';
import { analyzeConstructionDocument } from './services/geminiService';
import { fetchStorageConfig } from './services/configService';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ResultCard from './components/ResultCard';
import SqlExporter from './components/SqlExporter';
import CalendarManager from './components/CalendarManager';
import AdminDashboard from './components/AdminDashboard';
import AdminAuth from './components/AdminAuth';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('analyzer');
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreviewUrl, setFilePreviewUrl] = useState<string | null>(null);
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Terminal Logs State (Shared)
  const [logs, setLogs] = useState<LogEntry[]>([]);

  // Data enrichment states
  const [mappedClient, setMappedClient] = useState<Client | null>(null);
  const [autoChantierNumber, setAutoChantierNumber] = useState<string | null>(null);
  const [isFetchingChantier, setIsFetchingChantier] = useState(false);

  // Calendar & Poseur sync state
  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");
  const [allPoseurs, setAllPoseurs] = useState<Poseur[]>([]);

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      console.log('🚀 Initialisation BuildScan AI...');
      await fetchStorageConfig(); // Pré-chargement du cache
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => {
      if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    };
  }, [filePreviewUrl]);

  // --- SHARED LOGGING FUNCTION ---
  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  // --- AUTOMATISATION LOGIQUE METIER ---

  // 1. Détection automatique du Client dès que les données sont extraites
  useEffect(() => {
    if (!extractedData?.nom_client) {
      setMappedClient(null);
      return;
    }

    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;

    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = extractedData.nom_client.toLowerCase().trim();

      const found = clients.find(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || 
               searchName.includes(clientRefNom) || 
               clientRefNom.includes(searchName);
      });

      setMappedClient(found || null);
    } catch (e) {
      console.error("Erreur parsing clients", e);
    }
  }, [extractedData?.nom_client]);

  // 2. Récupération automatique du numéro d'affaire via Webhook
  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) {
        setAutoChantierNumber(null);
        return;
      }

      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;

      setIsFetchingChantier(true);
      try {
        console.log(`📡 Appel Webhook Auto pour ${mappedClient.nom} (${mappedClient.typeAffaire})...`);
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.nom
          })
        });

        if (response.ok) {
          const result = await response.json();
          let newNumber = "";

          if (result.numero_affaire) newNumber = result.numero_affaire;
          else if (result.next_id) newNumber = result.next_id;
          else if (result.value) newNumber = result.value;
          else if (typeof result === 'string') newNumber = result;
          else if (typeof result === 'number') newNumber = String(result);

          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            console.log("✅ Numéro récupéré :", formattedNumber);
          }
        }
      } catch (e) {
        console.error("Erreur Webhook Auto:", e);
      } finally {
        setIsFetchingChantier(false);
      }
    };

    fetchChantier();
  }, [mappedClient]);


  const handleViewChange = (view: AppView) => {
    if (view === 'analyzer') {
      setCurrentView('analyzer');
      return;
    }

    if (view === 'admin') {
      if (isAuthenticated) {
        setCurrentView('admin');
      } else {
        setShowAuthModal(true);
      }
    }
  };

  const handleAuthSuccess = () => {
    setIsAuthenticated(true);
    setShowAuthModal(false);
    setCurrentView('admin');
  };

  const handleAuthCancel = () => {
    setShowAuthModal(false);
    if (currentView !== 'analyzer') setCurrentView('analyzer');
  };

  const handleDataUpdate = (updates: Partial<ConstructionOrderData>) => {
    if (extractedData) {
      setExtractedData({ ...extractedData, ...updates });
    }
  };

  const handlePoseurSelect = (id: string, poseurs: Poseur[]) => {
      setSelectedPoseurId(id);
      setAllPoseurs(poseurs);
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') {
      setError("Format invalide. Veuillez uploader un PDF.");
      setStatus(AppStatus.ERROR);
      return;
    }

    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setMappedClient(null);
    setAutoChantierNumber(null);
    setOriginalFile(file);
    // Reset logs on new file
    clearLogs();
    addLog('info', 'Analyse du document démarrée...');

    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);

      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      addLog('success', 'Extraction IA terminée avec succès.', { client: data.nom_client });
    } catch (err: any) {
      console.error("Analyse échouée:", err);
      let msg = err.message || "Une erreur inconnue est survenue.";
      if (msg.includes("429") || msg.toLowerCase().includes("quota")) {
        msg = "Quota dépassé (Erreur 429). Veuillez patienter 60 secondes.";
      }
      setError(msg);
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${msg}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setAutoChantierNumber(null);
    setError(null);
    setOriginalFile(null);
    setSelectedPoseurId("");
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
  };

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-slate-600 font-bold">Connexion à la Base de Données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
      <Header currentView={currentView} onViewChange={handleViewChange} />

      {showAuthModal && (
        <AdminAuth onAuthenticated={handleAuthSuccess} onCancel={handleAuthCancel} />
      )}

      <main className="flex-grow container mx-auto px-4 py-8 max-w-[95%]">
        <div className="mx-auto">
          {currentView === 'admin' && <AdminDashboard />}

          {currentView === 'analyzer' && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

              {/* COLONNE GAUCHE : UPLOAD */}
              <div className="lg:col-span-3 space-y-6">
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
                  <h2 className="text-xl font-black mb-4 flex items-center gap-2 uppercase tracking-tight">
                    <i className="fas fa-file-pdf text-blue-600"></i>
                    Scan PDF
                  </h2>
                  <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />

                  {filePreviewUrl && (
                    <div className="mt-6 animate-in fade-in zoom-in-95 duration-300">
                      <p className="text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest text-center">Aperçu</p>
                      <div className="relative border border-slate-200 rounded-xl overflow-hidden bg-slate-100 min-h-[500px] flex items-center justify-center shadow-inner">
                        <iframe src={`${filePreviewUrl}#toolbar=0`} title="PDF Preview" className="w-full h-[500px] border-none" />
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* COLONNE DROITE : RESULTATS */}
              <div className="lg:col-span-9 space-y-6">
                {status === AppStatus.IDLE && (
                  <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl shadow-blue-900/20">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto mb-6 backdrop-blur-sm">
                      <i className="fas fa-robot text-4xl"></i>
                    </div>
                    <h3 className="text-2xl font-black mb-2 uppercase tracking-tight">Analyseur BuildScan</h3>
                    <p className="text-blue-100 font-medium">Glissez un PDF pour extraire les données chantiers vers l'ERP et l'Agenda.</p>
                  </div>
                )}

                {status === AppStatus.ANALYZING && (
                  <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center shadow-sm">
                    <div className="relative animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4 shadow-lg"></div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Extraction en cours...</h3>
                  </div>
                )}

                {status === AppStatus.ERROR && (
                  <div className="bg-red-50 border-2 border-red-100 rounded-2xl p-8 animate-in shake duration-500">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0">
                        <i className="fas fa-exclamation-triangle text-xl"></i>
                      </div>
                      <div className="flex-grow">
                        <h3 className="text-lg font-black text-red-800 uppercase tracking-tight">Échec de l'IA</h3>
                        <p className="text-red-700 mt-1 font-medium italic">{error}</p>
                        <button onClick={reset} className="mt-4 bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg shadow-red-200">
                          Réessayer
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {extractedData && (
                  <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-6">
                    {/* RESULTAT PRINCIPAL */}
                    <ResultCard 
                      data={extractedData} 
                      onReset={reset} 
                      mappedClient={mappedClient}
                      chantierNumber={autoChantierNumber}
                      isFetchingChantier={isFetchingChantier}
                      onUpdate={handleDataUpdate}
                    />

                    {/* EXPORT ET CALENDRIER CÔTE À CÔTE */}
                    <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 items-stretch">
                        <div className="h-full">
                             <SqlExporter 
                              data={extractedData} 
                              originalFile={originalFile || undefined} 
                              mappedClient={mappedClient}
                              prefilledChantierNumber={autoChantierNumber}
                              onPoseurSelect={handlePoseurSelect}
                              // Props de logging partagées
                              logs={logs}
                              onAddLog={addLog}
                              onClearLogs={clearLogs}
                            />
                        </div>
                        <div className="h-full">
                            <CalendarManager 
                                poseurs={allPoseurs}
                                selectedPoseurId={selectedPoseurId}
                                data={extractedData}
                                // Props de logging pour Nextcloud
                                onAddLog={addLog}
                            />
                        </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center">
          <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.6 • Nextcloud Ed.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { ConstructionOrderData, Client, LogEntry, Poseur } from '../types';
import Terminal from './Terminal';

interface SqlExporterProps {
  data: ConstructionOrderData;
  originalFile?: File;
  mappedClient: Client | null;
  prefilledChantierNumber: string | null;
  // Callback pour remonter la sélection au parent (pour le calendrier)
  onPoseurSelect?: (poseurId: string, poseurs: Poseur[]) => void;
  // Shared Logs Props
  logs: LogEntry[];
  onAddLog: (type: LogEntry['type'], message: string, data?: any) => void;
  onClearLogs: () => void;
}

const SqlExporter: React.FC<SqlExporterProps> = ({ 
  data, 
  originalFile, 
  mappedClient, 
  prefilledChantierNumber, 
  onPoseurSelect,
  logs,
  onAddLog,
  onClearLogs
}) => {
  const [copied, setCopied] = useState(false);
  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  // Poseurs State
  const [poseurs, setPoseurs] = useState<Poseur[]>([]);
  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");

  const escapeSql = (str: string | null) => str ? str.replace(/'/g, "''").trim() : "";

  // Le chantierInput est initialisé avec prefilledChantierNumber s'il existe, sinon on prend le numéro du bon, sinon 000000
  const [chantierInput, setChantierInput] = useState<string>("000000");

  const DEFAULT_WEBHOOK_URL = "http://194.116.0.110:5678/webhook-test/857f9b11-6d28-4377-a63b-c431ff3fc324";

  // Mise à jour de l'input quand le Webhook (géré par le parent) renvoie un numéro
  useEffect(() => {
    if (prefilledChantierNumber) {
      setChantierInput(prefilledChantierNumber);
      onAddLog('info', `Numéro d'affaire Webhook appliqué : ${prefilledChantierNumber}`);
    } else {
      // Fallback si pas de webhook: numéro du bon
      const fromBon = escapeSql(data.num_bon_travaux).replace(/\D/g, '').substring(0, 6);
      if (fromBon) setChantierInput(fromBon);
    }
  }, [prefilledChantierNumber, data.num_bon_travaux, onAddLog]);

  useEffect(() => {
    // Charger les poseurs
    const savedPoseurs = localStorage.getItem('buildscan_poseurs');
    if (savedPoseurs) {
      setPoseurs(JSON.parse(savedPoseurs));
    }
  }, []);

  // Présélection intelligente et AUTOMATIQUE du poseur
  useEffect(() => {
    if (mappedClient?.typeAffaire && poseurs.length > 0) {
      const match = poseurs.find(p => p.type === mappedClient.typeAffaire);

      if (match) {
        setSelectedPoseurId(match.id);
        onAddLog('info', `Poseur assigné automatiquement : ${match.nom}`, {
          type_match: match.type,
          client_type: mappedClient.typeAffaire
        });
      }
    }
  }, [mappedClient?.typeAffaire, poseurs, onAddLog]);

  // Propagation au parent quand la sélection change ou que les poseurs sont chargés
  useEffect(() => {
    if (onPoseurSelect) {
      onPoseurSelect(selectedPoseurId, poseurs);
    }
  }, [selectedPoseurId, poseurs, onPoseurSelect]);

  const selectedPoseur = useMemo(() => 
    poseurs.find(p => p.id === selectedPoseurId), 
  [poseurs, selectedPoseurId]);

  const fullAddress = [data.adresse_1, data.adresse_2, data.adresse_3]
    .filter(Boolean)
    .join(' ');
  const safeAddress = escapeSql(fullAddress);

  const soc = "SAM";
  const ets = "001";
  const secteur = "80";
  const phase = "0";

  // Use state variable for chantier
  const chantier = chantierInput;
  const imputation = `${secteur}${chantier}${phase}`;

  const cpSource = data.adresse_3 || fullAddress;
  const cpMatch = cpSource.match(/\d{5}/);
  const codePostal = cpMatch ? cpMatch[0] : "";

  const codeCliFour = mappedClient ? mappedClient.codeClient : "";
  const codeTrv = mappedClient?.typeAffaire || "O3-0";
  const descTravaux = escapeSql(data.descriptif_travaux);

  const poseurComment = selectedPoseur ? ` | Poseur: ${selectedPoseur.nom}` : "";

  // Reconstitution d'une chaîne contact pour le SQL (rétro-compatibilité)
  const contactFull = [data.gardien_nom, data.gardien_tel].filter(Boolean).join(' - ');

  const sqlInsert = `INSERT INTO \`a_cht\` 
(\`soc\`, \`ets\`, \`secteur\`, \`chantier\`, \`phase\`, \`imputation\`, \`libelle1\`, \`descriptif_tvx\`, \`descriptif_trvx2\`, \`code_postal\`, \`inter_cli\`, \`tel_cli\`, \`code_ouvert\`, \`code_raz_fin_exo\`, \`code_clifour\`, \`code_trv\`) 
VALUES ('${soc}', '${ets}', '${secteur}', '${chantier}', '${phase}', '${imputation}', '${escapeSql(data.nom_client).substring(0, 40)}', '<p>Import BuildScan AI : ${descTravaux.substring(0, 500)}${poseurComment}</p>', '${safeAddress.substring(0, 120)}', '${codePostal}', '${escapeSql(data.nom_client).substring(0, 40)}', '${escapeSql(contactFull).substring(0, 30)}', '4', 'N', '${codeCliFour}', '${codeTrv}');`;

  const copyToClipboard = () => {
    navigator.clipboard.writeText(sqlInsert);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const transmitToWebhook = async () => {
    setTransmitting(true);
    setTransmitStatus('idle');
    const webhookUrl = localStorage.getItem('buildscan_webhook_url') || DEFAULT_WEBHOOK_URL;

    const formData = new FormData();

    if (originalFile) {
      formData.append('file', originalFile, 'document.pdf');
    }

    formData.append('codeClient', codeCliFour);
    formData.append('code_trv', codeTrv);

    // Ajout BPU Client
    formData.append('client_bpu', mappedClient?.bpu || '');
    // Ajout Nom Client Fiche (Référentiel)
    formData.append('client_nom', mappedClient?.nom || '');

    formData.append('num_chantier', chantier);
    formData.append('imputation', imputation);
    formData.append('source', "BuildScan AI");
    formData.append('timestamp', new Date().toISOString());

    formData.append('num_bon_travaux', data.num_bon_travaux || '');
    formData.append('nom_client', data.nom_client || ''); // Nom extrait du PDF

    formData.append('adresse_1', data.adresse_1 || '');
    formData.append('adresse_2', data.adresse_2 || '');
    formData.append('adresse_3', data.adresse_3 || '');
    formData.append('adresse_intervention', fullAddress);

    // Envoi des champs gardien séparés
    formData.append('gardien_nom', data.gardien_nom || '');
    formData.append('gardien_tel', data.gardien_tel || '');
    formData.append('gardien_email', data.gardien_email || '');

    // Champ legacy pour compatibilité
    formData.append('coord_gardien', contactFull);

    formData.append('delai_intervention', data.delai_intervention || '');
    formData.append('date_intervention', data.date_intervention || '');
    formData.append('descriptif_travaux', data.descriptif_travaux || '');

    formData.append('libelle', data.nom_client || '');

    // Ajout des données Poseur
    if (selectedPoseur) {
      formData.append('poseur_id', selectedPoseur.id);
      formData.append('poseur_nom', selectedPoseur.nom);
      formData.append('poseur_code', selectedPoseur.codeSalarie || '');
      formData.append('poseur_type', selectedPoseur.type || '');
    }

    onAddLog('request', `Envoi Multipart/FormData vers n8n...`, {
      codeClient: codeCliFour,
      client_nom: mappedClient?.nom,
      bpu: mappedClient?.bpu,
      contact_nom: data.gardien_nom,
      contact_tel: data.gardien_tel,
      contact_email: data.gardien_email,
      imputation: imputation,
      num_chantier: chantier,
      poseur: selectedPoseur?.nom || 'Non assigné'
    });

    try {
      const response = await fetch(webhookUrl, {
        method: 'POST',
        body: formData
      });

      if (response.ok) {
        setTransmitStatus('success');
        onAddLog('response', `Réponse n8n : Succès (HTTP ${response.status})`);
      } else {
        throw new Error(`Erreur n8n : ${response.status}`);
      }
    } catch (err: any) {
      console.error("Erreur Webhook:", err);
      setTransmitStatus('error');
      onAddLog('error', `Échec transmission: ${err.message}`);
    } finally {
      setTransmitting(false);
      setTimeout(() => setTransmitStatus('idle'), 3000);
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800 flex-shrink-0">
        <div className="px-6 py-4 border-b border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-500/20 text-blue-400 rounded flex items-center justify-center">
              <i className="fas fa-network-wired text-sm"></i>
            </div>
            <div>
              <h3 className="text-white font-bold uppercase tracking-wider text-xs">Intégration <span className="text-blue-400">n8n / ERP</span></h3>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-tighter">Transmission Binaire</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <button 
              onClick={copyToClipboard}
              className={`px-3 py-1.5 rounded-lg font-bold text-[10px] transition-all flex items-center gap-2 ${copied ? 'bg-emerald-600 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700 border border-slate-700'}`}
            >
              {copied ? 'SQL Copié' : 'Copier SQL'}
            </button>

            <button 
              disabled={transmitting || !mappedClient}
              onClick={transmitToWebhook}
              className={`px-4 py-1.5 rounded-lg font-bold text-[10px] transition-all flex items-center gap-2 shadow-lg ${
                transmitStatus === 'success' ? 'bg-green-600 text-white' : 
                transmitStatus === 'error' ? 'bg-red-600 text-white' :
                !mappedClient ? 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700' :
                'bg-blue-600 text-white hover:bg-blue-500 shadow-blue-900/40'
              }`}
            >
              {transmitting ? 'Envoi...' : transmitStatus === 'success' ? 'Transmis !' : 'Transmettre à n8n'}
            </button>
          </div>
        </div>

        <div className="p-6">
          {/* Sélection du Poseur */}
          <div className="mb-6">
            <label className="text-[10px] text-slate-400 font-bold uppercase mb-2 flex items-center justify-between">
              <span><i className="fas fa-user-hard-hat mr-2"></i>Assignation Poseur</span>
              {selectedPoseur && mappedClient?.typeAffaire && selectedPoseur.type === mappedClient.typeAffaire && (
                <span className="text-emerald-500"><i className="fas fa-magic mr-1"></i>Auto-sélectionné</span>
              )}
            </label>
            <div className="relative">
              <select
                value={selectedPoseurId}
                onChange={(e) => setSelectedPoseurId(e.target.value)}
                className={`w-full bg-slate-800 border text-white text-sm rounded-lg p-3 appearance-none focus:ring-2 focus:ring-blue-500 outline-none transition-colors ${
                    selectedPoseur && mappedClient?.typeAffaire && selectedPoseur.type === mappedClient.typeAffaire 
                    ? 'border-emerald-600/50 ring-1 ring-emerald-900' 
                    : 'border-slate-700'
                }`}
              >
                <option value="">-- Sélectionner un poseur --</option>
                {poseurs.map(p => (
                  <option key={p.id} value={p.id}>
                    {p.nom} {p.type ? `[Type: ${p.type}]` : ''} - {p.entreprise}
                  </option>
                ))}
              </select>
              <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-400">
                <i className="fas fa-chevron-down text-xs"></i>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
            <div className={`p-3 rounded-lg border flex items-center justify-between transition-all ${mappedClient ? 'bg-emerald-900/20 border-emerald-800' : 'bg-amber-900/20 border-amber-800'}`}>
              <div>
                <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Code Client</p>
                <p className={`text-sm font-mono font-bold ${mappedClient ? 'text-emerald-400' : 'text-amber-400'}`}>
                  {codeCliFour || 'MANQUANT'}
                </p>
              </div>
              {mappedClient ? <i className="fas fa-link text-emerald-500"></i> : <i className="fas fa-unlink text-amber-500"></i>}
            </div>

            <div className="p-3 bg-blue-900/20 border border-blue-800 rounded-lg flex items-center justify-between">
              <div>
                <p className="text-[10px] text-slate-400 font-bold uppercase mb-1">Type Affaire</p>
                <p className="text-sm font-mono font-bold text-blue-400">{codeTrv}</p>
              </div>
              <i className="fas fa-folder-open text-blue-500"></i>
            </div>

            <div className="p-3 bg-slate-800/50 border border-slate-700 rounded-lg flex flex-col justify-center">
              <p className="text-[10px] text-slate-400 font-bold uppercase mb-1.5 flex items-center gap-2">
                Numéro Affaire / Chantier
                {chantierInput && <span className="text-[8px] bg-slate-700 px-1 rounded text-slate-300">{chantierInput.length} chars</span>}
              </p>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={chantierInput}
                  onChange={(e) => setChantierInput(e.target.value)}
                  className="bg-slate-900 border border-slate-600 text-white text-sm font-mono font-bold rounded px-2 py-1 w-full focus:outline-none focus:border-blue-500"
                />
              </div>
            </div>
          </div>

          <div className="relative group">
            <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2">Script SQL de secours</p>
            <div className="max-h-32 overflow-y-auto rounded-lg border border-slate-800 bg-black/40 p-3">
              <pre className="text-emerald-300 text-[10px] font-mono leading-relaxed whitespace-pre-wrap opacity-70 group-hover:opacity-100 transition-opacity">
                {sqlInsert}
              </pre>
