  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Layout State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const [isCalendarVisible, setIsCalendarVisible] = useState(true); // Nouvel état pour l'agenda
  const [isPdfModalOpen, setIsPdfModalOpen] = useState(false); // Nouvel état pour le modal PDF

  // Terminal Logs State (Shared)
  const [logs, setLogs] = useState<LogEntry[]>([]);

  // Data enrichment states
  const [mappedClient, setMappedClient] = useState<Client | null>(null);
  const [autoChantierNumber, setAutoChantierNumber] = useState<string | null>(null);
  const [isFetchingChantier, setIsFetchingChantier] = useState(false);

  // Calendar & Poseur sync state
  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");
  const [allPoseurs, setAllPoseurs] = useState<Poseur[]>([]);
  const [tentativeEvent, setTentativeEvent] = useState<CalendarEvent | null>(null);
  const [isRdvSaved, setIsRdvSaved] = useState(false);
  const [calendarRefreshTrigger, setCalendarRefreshTrigger] = useState(0);

  // Transmission State (Moved from SqlExporter)
  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      console.log('🚀 Initialisation BuildScan AI...');
      const config = await fetchStorageConfig(); // Pré-chargement du cache
      if (config) {
        setAllPoseurs(config.poseurs);
      }
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => {
      if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    };
  }, [filePreviewUrl]);

  // --- SHARED LOGGING FUNCTION ---
  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  // --- AUTOMATISATION LOGIQUE METIER ---

  // 1. Détection automatique du Client et Poseur
  useEffect(() => {
    if (!extractedData?.nom_client) {
      setMappedClient(null);
      return;
    }

    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;

    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = extractedData.nom_client.toLowerCase().trim();

      const found = clients.find(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || 
               searchName.includes(clientRefNom) || 
               clientRefNom.includes(searchName);
      });

      setMappedClient(found || null);

      // Auto-assignation Poseur (Nouvelle Logique)
      if (found) {
        let assignedPoseur: Poseur | undefined;
        let method = '';

        // Priorité 1 : Poseur directement lié au client (nouveau champ)
        if (found.default_poseur && allPoseurs.length > 0) {
            assignedPoseur = allPoseurs.find(p => p.id === found.default_poseur);
            method = 'Lien Client';
        } 

        // Priorité 2 (Fallback) : Matching par type d'affaire
        if (!assignedPoseur && found.typeAffaire && allPoseurs.length > 0) {
            assignedPoseur = allPoseurs.find(p => p.type === found.typeAffaire);
            method = 'Type Affaire';
        }

        if (assignedPoseur) {
            setSelectedPoseurId(assignedPoseur.id);
            addLog('info', `Poseur assigné (${method}) : ${assignedPoseur.nom}`);
        }
      }

    } catch (e) {
      console.error("Erreur parsing clients", e);
    }
  }, [extractedData?.nom_client, allPoseurs, addLog]);

  // 2. Récupération automatique du numéro d'affaire via Webhook
  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) {
        setAutoChantierNumber(null);
        return;
      }

      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;

      setIsFetchingChantier(true);
      try {
        console.log(`📡 Appel Webhook Auto pour ${mappedClient.nom} (${mappedClient.typeAffaire})...`);
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.nom
          })
        });

        if (response.ok) {
          const result = await response.json();
          let newNumber = "";

          if (result.numero_affaire) newNumber = result.numero_affaire;
          else if (result.next_id) newNumber = result.next_id;
          else if (result.value) newNumber = result.value;
          else if (typeof result === 'string') newNumber = result;
          else if (typeof result === 'number') newNumber = String(result);

          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            console.log("✅ Numéro récupéré :", formattedNumber);
          }
        }
      } catch (e) {
        console.error("Erreur Webhook Auto:", e);
      } finally {
        setIsFetchingChantier(false);
      }
    };

    fetchChantier();
  }, [mappedClient]);

  // --- SAVE RDV ---
  const handleSaveRdv = async () => {
      if (!tentativeEvent || !selectedPoseurId) return;

      addLog('request', `Validation RDV le ${new Date(tentativeEvent.start).toLocaleString()}...`);

      try {
          let fileData = null;
          let fileName = null;

          if (originalFile) {
              fileName = originalFile.name;
              fileData = await new Promise<string>((resolve, reject) => {
                  const reader = new FileReader();
                  reader.onload = () => resolve((reader.result as string).split(',')[1]); 
                  reader.onerror = reject;
                  reader.readAsDataURL(originalFile);
              });
          }

          const res = await fetch('/api/calendar/event/save', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  poseur_id: selectedPoseurId,
                  event: tentativeEvent,
                  file: fileData ? { name: fileName, data: fileData } : undefined
              })
          });

          const result = await res.json();

          if (res.ok && result.success) {
              addLog('success', `RDV validé et enregistré dans Nextcloud.`);
              setIsRdvSaved(true);
              setTentativeEvent(null); // Plus de tentative, c'est enregistré
              setCalendarRefreshTrigger(prev => prev + 1); // Force refresh calendar
          } else {
              throw new Error(result.error || "Erreur enregistrement");
          }

      } catch (e: any) {
          addLog('error', `Echec validation RDV: ${e.message}`);
          alert("Erreur lors de la validation du RDV: " + e.message);
      }
  };


  // --- TRANSMISSION WEBHOOK ---
  const handleTransmit = async () => {
      if (!extractedData) return;

      setTransmitting(true);
      setTransmitStatus('idle');
      const webhookUrl = localStorage.getItem('buildscan_webhook_url') || "http://194.116.0.110:5678/webhook-test/857f9b11-6d28-4377-a63b-c431ff3fc324";

      // Calcul des données dérivées pour l'envoi
      const chantier = autoChantierNumber || (extractedData.num_bon_travaux ? extractedData.num_bon_travaux.replace(/\D/g, '').substring(0, 6) : "000000");
      const imputation = `80${chantier}0`;
      const fullAddress = [extractedData.adresse_1, extractedData.adresse_2, extractedData.adresse_3].filter(Boolean).join(' ');
      const contactFull = [extractedData.gardien_nom, extractedData.gardien_tel].filter(Boolean).join(' - ');
      const selectedPoseur = allPoseurs.find(p => p.id === selectedPoseurId);

      const formData = new FormData();

      if (originalFile) {
        formData.append('file', originalFile, 'document.pdf');
      }

      formData.append('codeClient', mappedClient?.codeClient || '');
      formData.append('code_trv', mappedClient?.typeAffaire || 'O3-0');
      formData.append('client_bpu', mappedClient?.bpu || '');
      formData.append('client_nom', mappedClient?.nom || '');
      formData.append('num_chantier', chantier);
      formData.append('imputation', imputation);
      formData.append('source', "BuildScan AI");
      formData.append('timestamp', new Date().toISOString());

      formData.append('num_bon_travaux', extractedData.num_bon_travaux || '');
      formData.append('nom_client', extractedData.nom_client || '');

      formData.append('adresse_1', extractedData.adresse_1 || '');
      formData.append('adresse_2', extractedData.adresse_2 || '');
      formData.append('adresse_3', extractedData.adresse_3 || '');
      formData.append('adresse_intervention', fullAddress);

      formData.append('gardien_nom', extractedData.gardien_nom || '');
      formData.append('gardien_tel', extractedData.gardien_tel || '');
      formData.append('gardien_email', extractedData.gardien_email || '');
      formData.append('coord_gardien', contactFull);

      formData.append('delai_intervention', extractedData.delai_intervention || '');
      formData.append('date_intervention', extractedData.date_intervention || '');
      formData.append('descriptif_travaux', extractedData.descriptif_travaux || '');
      formData.append('libelle', extractedData.nom_client || '');

      if (selectedPoseur) {
        formData.append('poseur_id', selectedPoseur.id);
        formData.append('poseur_nom', selectedPoseur.nom);
        formData.append('poseur_code', selectedPoseur.codeSalarie || '');
        formData.append('poseur_type', selectedPoseur.type || '');
      }

      addLog('request', `Envoi vers n8n...`, { 
          imputation, 
          poseur: selectedPoseur?.nom 
      });

      try {
        const response = await fetch(webhookUrl, {
          method: 'POST',
          body: formData
        });

        // Lecture de la réponse JSON de n8n
        const result = await response.json().catch(() => ({}));

        // On considère un succès si HTTP OK et (pas de json OU json.success=true)
        if (response.ok && (result.success !== false)) {
          setTransmitStatus('success');
          addLog('response', `Réponse n8n : ${result.message || 'Succès'}`);
        } else {
          throw new Error(result.message || `Erreur n8n : ${response.status}`);
        }
      } catch (err: any) {
        console.error("Erreur Webhook:", err);
        setTransmitStatus('error');
        addLog('error', `Échec transmission: ${err.message}`);
      } finally {
        setTransmitting(false);
      }
  };

  const handlePdfDoubleClick = () => {
    // Affiche le PDF en grand
    setIsPdfModalOpen(true);
    // Masque l'agenda pour donner plus de place aux résultats (mode saisie/lecture)
    setIsCalendarVisible(false);
  };

  const handleViewChange = (view: AppView) => {
    if (view === 'analyzer') {
      setCurrentView('analyzer');
      return;
    }

    if (view === 'admin') {
      if (isAuthenticated) {
        setCurrentView('admin');
      } else {
        setShowAuthModal(true);
      }
    }
  };

  const handleAuthSuccess = () => {
    setIsAuthenticated(true);
    setShowAuthModal(false);
    setCurrentView('admin');
  };

  const handleAuthCancel = () => {
    setShowAuthModal(false);
    if (currentView !== 'analyzer') setCurrentView('analyzer');
  };

  const handleDataUpdate = (updates: Partial<ConstructionOrderData>) => {
    if (extractedData) {
      setExtractedData(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handlePoseurSelect = (id: string, poseurs: Poseur[]) => {
      setSelectedPoseurId(id);
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') {
      setError("Format invalide. Veuillez uploader un PDF.");
      setStatus(AppStatus.ERROR);
      return;
    }

    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setMappedClient(null);
    setAutoChantierNumber(null);
    setOriginalFile(file);
    // Reset states
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    // Réinitialisation layout
    setIsCalendarVisible(true);

    addLog('info', 'Analyse du document démarrée...');

    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);

      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      // AUTO HIDE UI ELEMENTS ON SUCCESS
      setIsSidebarOpen(false); 
      setIsHeaderVisible(false);

      addLog('success', 'Extraction IA terminée avec succès.', { client: data.nom_client });
    } catch (err: any) {
      console.error("Analyse échouée:", err);
      let msg = err.message || "Une erreur inconnue est survenue.";
      if (msg.includes("429") || msg.toLowerCase().includes("quota")) {
        msg = "Quota dépassé (Erreur 429). Veuillez patienter 60 secondes.";
      }
      setError(msg);
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${msg}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setAutoChantierNumber(null);
    setError(null);
    setOriginalFile(null);
    setSelectedPoseurId("");
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    // Re-ouvrir la sidebar et le header si on reset
    setIsSidebarOpen(true);
    setIsHeaderVisible(true);
    setIsCalendarVisible(true);
  };

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-slate-600 font-bold">Connexion à la Base de Données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans overflow-x-hidden relative">

      {/* MODAL PDF GRAND FORMAT */}
      {isPdfModalOpen && filePreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white w-full h-full max-w-6xl rounded-2xl shadow-2xl overflow-hidden flex flex-col relative">
              <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between shrink-0">
                  <span className="font-bold text-sm uppercase tracking-wider"><i className="fas fa-file-pdf mr-2"></i> Aperçu Document (Mode Copie)</span>
                  <button 
                    onClick={() => setIsPdfModalOpen(false)}
                    className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-700 transition-colors"
                  >
                    <i className="fas fa-times"></i>
                  </button>
              </div>
              <div className="flex-grow bg-slate-200">
                  <iframe src={`${filePreviewUrl}#toolbar=0&navpanes=0`} className="w-full h-full" title="PDF Fullscreen"></iframe>
              </div>
           </div>
        </div>
      )}

      {/* HEADER TOGGLE BUTTON (Visible only when header is hidden) */}
      {!isHeaderVisible && (
         <button 
           onClick={() => setIsHeaderVisible(true)}
           className="absolute top-2 right-4 z-50 bg-slate-800 text-slate-400 hover:text-white p-2 rounded-b-lg shadow-md text-xs font-bold transition-all opacity-50 hover:opacity-100"
           title="Afficher le menu"
         >
           <i className="fas fa-chevron-down"></i> Menu
         </button>
      )}

      {/* HEADER (Conditionally rendered) */}
      {isHeaderVisible && <Header currentView={currentView} onViewChange={handleViewChange} />}

      {showAuthModal && (
        <AdminAuth onAuthenticated={handleAuthSuccess} onCancel={handleAuthCancel} />
      )}

      <main className={`flex-grow container mx-auto px-4 py-8 max-w-[98%] transition-all ${!isHeaderVisible ? 'pt-4' : ''}`}>
        <div className="mx-auto">
          {currentView === 'admin' && <AdminDashboard />}

          {currentView === 'analyzer' && (
            <div className="flex flex-col lg:flex-row gap-6 transition-all duration-300">

              {/* COLONNE GAUCHE : UPLOAD (Masquable) */}
              <div className={`${isSidebarOpen ? 'lg:w-[350px] shrink-0' : 'w-0 overflow-hidden'} transition-all duration-300`}>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-24">
                   <div className="flex justify-between items-center mb-4">
                      <h2 className="text-xl font-black flex items-center gap-2 uppercase tracking-tight">
                        <i className="fas fa-file-pdf text-blue-600"></i>
                        Scan PDF
                      </h2>
                      <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fas fa-times"></i></button>
                   </div>
                  <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />

                  {filePreviewUrl && (
                    <div className="mt-6 animate-in fade-in zoom-in-95 duration-300 group">
                      <div className="flex justify-between items-center mb-2">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Aperçu</p>
                          <span className="text-[9px] bg-blue-100 text-blue-700 px-2 rounded-full font-bold opacity-0 group-hover:opacity-100 transition-opacity">Double-clic pour agrandir</span>
                      </div>
                      <div 
                        onDoubleClick={handlePdfDoubleClick}
                        className="relative border border-slate-200 rounded-xl overflow-hidden bg-slate-100 min-h-[500px] flex items-center justify-center shadow-inner cursor-zoom-in hover:ring-2 hover:ring-blue-400 transition-all"
                        title="Double-cliquez pour agrandir et sélectionner du texte"
                      >
                        <iframe src={`${filePreviewUrl}#toolbar=0`} title="PDF Preview" className="w-full h-[500px] border-none pointer-events-none" />
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* BOUTON TOGGLE Sidebar (Si sidebar fermée) */}
              {!isSidebarOpen && (
                 <div className="absolute left-4 top-24 z-40">
                    <button 
                        onClick={() => setIsSidebarOpen(true)}
                        className="bg-blue-600 text-white p-3 rounded-full shadow-lg hover:bg-blue-700 transition-colors"
                        title="Afficher Scan"
                    >
                        <i className="fas fa-file-pdf"></i>
                    </button>
                 </div>
              )}

              {/* COLONNE DROITE : RESULTATS */}
              <div className="flex-grow flex flex-col gap-6 min-w-0">
                {/* BOUTON TOGGLE Sidebar Desktop */}
                {isSidebarOpen && status === AppStatus.SUCCESS && (
                     <div className="hidden lg:flex justify-start">
                        <button 
                            onClick={() => setIsSidebarOpen(false)}
                            className="text-xs font-bold text-slate-400 hover:text-blue-600 flex items-center gap-2"
                        >
                            <i className="fas fa-chevron-left"></i> Masquer le Scan (Plein écran)
                        </button>
                     </div>
                )}

                {status === AppStatus.IDLE && (
                  <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl shadow-blue-900/20 mx-auto max-w-2xl mt-10">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto mb-6 backdrop-blur-sm">
                      <i className="fas fa-robot text-4xl"></i>
                    </div>
                    <h3 className="text-2xl font-black mb-2 uppercase tracking-tight">Analyseur BuildScan</h3>
                    <p className="text-blue-100 font-medium">Glissez un PDF pour extraire les données chantiers vers l'ERP et l'Agenda.</p>
                  </div>
                )}

                {status === AppStatus.ANALYZING && (
                  <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center shadow-sm mx-auto max-w-2xl mt-10">
                    <div className="relative animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4 shadow-lg"></div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Extraction en cours...</h3>
                  </div>
                )}

                {status === AppStatus.ERROR && (
                  <div className="bg-red-50 border-2 border-red-100 rounded-2xl p-8 animate-in shake duration-500 mx-auto max-w-2xl mt-10">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0">
                        <i className="fas fa-exclamation-triangle text-xl"></i>
                      </div>
                      <div className="flex-grow">
                        <h3 className="text-lg font-black text-red-800 uppercase tracking-tight">Échec de l'IA</h3>
                        <p className="text-red-700 mt-1 font-medium italic">{error}</p>
                        <button onClick={reset} className="mt-4 bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg shadow-red-200">
                          Réessayer
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {extractedData && (
                  <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-6">
                    {/* LAYOUT GRID: RESULTATS (GAUCHE) + CALENDRIER (DROITE) */}
                    <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 items-start">
                        {/* 1. RESULTATS */}
                        <div className={`transition-all duration-300 ${isCalendarVisible ? '' : 'xl:col-span-2'}`}>
                          <ResultCard 
                              data={extractedData} 
                              onReset={reset} 
                              mappedClient={mappedClient}
                              chantierNumber={autoChantierNumber}
                              isFetchingChantier={isFetchingChantier}
                              onUpdate={handleDataUpdate}
                              // Props ajoutées pour transmission et poseur
                              poseurs={allPoseurs}
                              selectedPoseurId={selectedPoseurId}
                              onPoseurSelect={setSelectedPoseurId}
                              onTransmit={handleTransmit}
                              isTransmitting={transmitting}
                              transmitStatus={transmitStatus}
                              // Props validation RDV
                              tentativeEvent={tentativeEvent}
                              isRdvSaved={isRdvSaved}
                              onValidateRdv={handleSaveRdv}
                              // Props toggle calendar
                              isCalendarVisible={isCalendarVisible}
                              onToggleCalendar={() => setIsCalendarVisible(!isCalendarVisible)}
                          />
                        </div>

                        {/* 2. CALENDRIER (A DROITE) - MASQUABLE */}
                        {isCalendarVisible && (
                          <div className="h-full min-h-[600px] animate-in fade-in slide-in-from-right-4 duration-300">
                              <CalendarManager 
                                  poseurs={allPoseurs}
                                  selectedPoseurId={selectedPoseurId}
                                  data={extractedData}
                                  onAddLog={addLog}
                                  chantierNumber={autoChantierNumber}
                                  originalFile={originalFile}
                                  onUpdate={handleDataUpdate}
                                  onTentativeChange={setTentativeEvent}
                                  onRdvStatusChange={setIsRdvSaved}
                                  refreshTrigger={calendarRefreshTrigger}
                                  onClose={() => setIsCalendarVisible(false)}
                              />
                          </div>
                        )}
                    </div>

                    {/* 3. TERMINAL (EN BAS) */}
                    <SqlExporter 
                      data={extractedData} 
                      originalFile={originalFile || undefined} 
                      mappedClient={mappedClient}
                      prefilledChantierNumber={autoChantierNumber}
                      onPoseurSelect={(id) => setSelectedPoseurId(id)}
                      logs={logs}
                      onAddLog={addLog}
                      onClearLogs={clearLogs}
                    />
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center">
          <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.7 • Nextcloud Ed.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Client, Poseur } from '../types';
import { fetchStorageConfig, addClient, updateClient, deleteClient } from '../services/configService';

const AdminClients: React.FC = () => {
  const [clients, setClients] = useState<Client[]>([]);
  const [poseurs, setPoseurs] = useState<Poseur[]>([]); // État pour la liste des poseurs
  const [isAdding, setIsAdding] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const initialForm = { nom: '', codeClient: '', typeAffaire: '', bpu: '', default_poseur: '' };
  const [newClient, setNewClient] = useState<Omit<Client, 'id'>>(initialForm);
  const [editForm, setEditForm] = useState<Omit<Client, 'id'>>(initialForm);

  const reloadData = async () => {
    const config = await fetchStorageConfig();
    if (config) {
      setClients(config.clients);
      setPoseurs(config.poseurs);
    }
  };

  useEffect(() => { reloadData(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newClient.nom || !newClient.codeClient) return;
    setIsSaving(true);
    const result = await addClient(newClient);
    if (result) {
      setNewClient(initialForm);
      setIsAdding(false);
      await reloadData();
    } else {
      alert("Erreur serveur lors de l'ajout.");
    }
    setIsSaving(false);
  };

  const handleUpdate = async (id: string) => {
    setIsSaving(true);
    const success = await updateClient(id, editForm);
    if (success) {
      setEditingId(null);
      await reloadData();
    } else {
      alert("Erreur serveur lors de la mise à jour.");
    }
    setIsSaving(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Supprimer ce client du référentiel ?")) return;
    setIsSaving(true);
    const success = await deleteClient(id);
    if (success) await reloadData();
    setIsSaving(false);
  };

  const startEditing = (client: Client) => {
    setEditingId(client.id);
    setEditForm({ 
        nom: client.nom, 
        codeClient: client.codeClient, 
        typeAffaire: client.typeAffaire, 
        bpu: client.bpu || '',
        default_poseur: client.default_poseur || ''
    });
  };

  const getPoseurName = (id?: string) => {
      if (!id) return null;
      const p = poseurs.find(pos => pos.id === id);
      return p ? p.nom : id;
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Référentiel Clients</h2>
          <p className="text-slate-500">Base de données PocketBase.</p>
        </div>
        <div className="flex items-center gap-4">
          <button 
            onClick={() => { setIsAdding(!isAdding); setEditingId(null); }}
            className={`px-5 py-2.5 rounded-xl font-bold transition-all flex items-center gap-2 shadow-sm ${
              isAdding ? 'bg-slate-200 text-slate-700' : 'bg-blue-600 text-white hover:bg-blue-700 shadow-blue-200'
            }`}
          >
            {isAdding ? 'Annuler' : <><i className="fas fa-plus-circle"></i> Ajouter</>}
          </button>
        </div>
      </div>

      {isAdding && (
        <form onSubmit={handleAdd} className="bg-white border-2 border-blue-100 rounded-2xl p-6 shadow-xl grid grid-cols-1 md:grid-cols-4 gap-5 animate-in slide-in-from-top-4">
          <input type="text" required placeholder="Nom (PDF)" className="w-full p-2.5 border rounded-xl" value={newClient.nom} onChange={e => setNewClient({...newClient, nom: e.target.value})} />
          <input type="text" required placeholder="Code ERP" className="w-full p-2.5 border rounded-xl font-mono" value={newClient.codeClient} onChange={e => setNewClient({...newClient, codeClient: e.target.value})} />
          <input type="text" placeholder="Type Affaire" className="w-full p-2.5 border rounded-xl font-mono" value={newClient.typeAffaire} onChange={e => setNewClient({...newClient, typeAffaire: e.target.value})} />
          <input type="text" placeholder="Code BPU" className="w-full p-2.5 border rounded-xl font-mono" value={newClient.bpu} onChange={e => setNewClient({...newClient, bpu: e.target.value})} />

          <div className="md:col-span-4">
             <label className="text-xs font-bold text-slate-400 uppercase ml-1">Poseur par défaut</label>
             <select 
                className="w-full p-2.5 border rounded-xl bg-slate-50"
                value={newClient.default_poseur}
                onChange={e => setNewClient({...newClient, default_poseur: e.target.value})}
             >
                <option value="">-- Aucun poseur assigné --</option>
                {poseurs.map(p => (
                    <option key={p.id} value={p.id}>{p.nom} {p.type ? `(${p.type})` : ''}</option>
                ))}
             </select>
          </div>

          <button type="submit" disabled={isSaving} className="md:col-span-4 bg-emerald-600 text-white py-3 rounded-xl font-black uppercase tracking-widest hover:bg-emerald-700 shadow-lg transition-all">
            {isSaving ? 'Enregistrement...' : 'Créer dans PocketBase'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Nom PDF</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Code ERP</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Type / Poseur</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">BPU</th>
              <th className="px-6 py-4 text-right text-[10px] font-black text-slate-400 uppercase">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {clients.map(c => (
              <tr key={c.id} className="hover:bg-slate-50/80">
                <td className="px-6 py-4">
                  {editingId === c.id ? <input type="text" className="w-full p-2 border rounded" value={editForm.nom} onChange={e => setEditForm({...editForm, nom: e.target.value})} /> : <span className="font-bold">{c.nom}</span>}
                </td>
                <td className="px-6 py-4">
                  {editingId === c.id ? <input type="text" className="w-full p-2 border rounded font-mono" value={editForm.codeClient} onChange={e => setEditForm({...editForm, codeClient: e.target.value})} /> : <code className="bg-blue-50 text-blue-600 px-2 py-1 rounded font-bold">{c.codeClient}</code>}
                </td>
                <td className="px-6 py-4">
                  {editingId === c.id ? (
                      <div className="space-y-2">
                          <input type="text" placeholder="Type" className="w-full p-2 border rounded font-mono text-xs" value={editForm.typeAffaire} onChange={e => setEditForm({...editForm, typeAffaire: e.target.value})} />
                          <select 
                            className="w-full p-2 border rounded text-xs"
                            value={editForm.default_poseur}
                            onChange={e => setEditForm({...editForm, default_poseur: e.target.value})}
                          >
                             <option value="">-- Poseur --</option>
                             {poseurs.map(p => (
                                <option key={p.id} value={p.id}>{p.nom}</option>
                             ))}
                          </select>
                      </div>
                  ) : (
                      <div className="flex flex-col">
                          <span className="text-sm">{c.typeAffaire}</span>
                          {c.default_poseur && (
                              <span className="text-[10px] text-emerald-600 font-bold bg-emerald-50 px-1.5 py-0.5 rounded w-fit mt-1">
                                  <i className="fas fa-user-hard-hat mr-1"></i>
                                  {getPoseurName(c.default_poseur)}
                              </span>
                          )}
                      </div>
                  )}
                </td>
                <td className="px-6 py-4">
                  {editingId === c.id ? <input type="text" className="w-full p-2 border rounded font-mono" value={editForm.bpu} onChange={e => setEditForm({...editForm, bpu: e.target.value})} /> : <span className="font-mono text-slate-500">{c.bpu || '-'}</span>}
                </td>
                <td className="px-6 py-4 text-right flex justify-end gap-2">
                  {editingId === c.id ? (
                    <>
                      <button onClick={() => handleUpdate(c.id)} className="text-emerald-600 hover:text-emerald-800"><i className="fas fa-check"></i></button>
                      <button onClick={() => setEditingId(null)} className="text-slate-400 hover:text-slate-600"><i className="fas fa-times"></i></button>
                    </>
                  ) : (
                    <>
                      <button onClick={() => startEditing(c)} className="text-blue-500 hover:text-blue-700"><i className="fas fa-edit"></i></button>
                      <button onClick={() => handleDelete(c.id)} className="text-red-400 hover:text-red-600"><i className="fas fa-trash"></i></button>
                    </>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default AdminClients;

import React, { useState, useCallback, useEffect } from 'react';
import { AppStatus, ConstructionOrderData, AppView, Client, Poseur, LogEntry, CalendarEvent } from './types';
import { analyzeConstructionDocument } from './services/geminiService';
import { fetchStorageConfig } from './services/configService';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ResultCard from './components/ResultCard';
import SqlExporter from './components/SqlExporter';
import CalendarManager from './components/CalendarManager';
import AdminDashboard from './components/AdminDashboard';
import AdminAuth from './components/AdminAuth';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('analyzer');
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreviewUrl, setFilePreviewUrl] = useState<string | null>(null);
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Layout State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const [isCalendarVisible, setIsCalendarVisible] = useState(true);
  const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);

  // Terminal Logs State (Shared)
  const [logs, setLogs] = useState<LogEntry[]>([]);

  // Data enrichment states
  const [mappedClient, setMappedClient] = useState<Client | null>(null);
  const [autoChantierNumber, setAutoChantierNumber] = useState<string | null>(null);
  const [isFetchingChantier, setIsFetchingChantier] = useState(false);

  // Trigger pour forcer le re-calcul du mapping (Client/Poseur) au changement de vue
  const [refreshDataTrigger, setRefreshDataTrigger] = useState(0);

  // Calendar & Poseur sync state
  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");
  const [allPoseurs, setAllPoseurs] = useState<Poseur[]>([]);
  const [tentativeEvent, setTentativeEvent] = useState<CalendarEvent | null>(null);
  const [isRdvSaved, setIsRdvSaved] = useState(false);
  const [calendarRefreshTrigger, setCalendarRefreshTrigger] = useState(0);

  // Transmission State
  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      console.log('🚀 Initialisation BuildScan AI...');
      const config = await fetchStorageConfig(); // Pré-chargement du cache
      if (config) {
        setAllPoseurs(config.poseurs);
      }
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => {
      if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    };
  }, [filePreviewUrl]);

  // --- SHARED LOGGING FUNCTION ---
  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  // --- AUTOMATISATION LOGIQUE METIER ---

  // 1. Détection automatique du Client et Poseur
  // Ajout de refreshDataTrigger dans les dépendances pour relancer la logique au retour de l'admin
  useEffect(() => {
    if (!extractedData?.nom_client) {
      setMappedClient(null);
      return;
    }

    // On recharge la liste des clients depuis le localStorage (qui a pu être mis à jour par fetchStorageConfig)
    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;

    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = extractedData.nom_client.toLowerCase().trim();

      const found = clients.find(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || 
               searchName.includes(clientRefNom) || 
               clientRefNom.includes(searchName);
      });

      setMappedClient(found || null);

      // Auto-assignation Poseur (Nouvelle Logique)
      if (found) {
        let assignedPoseur: Poseur | undefined;
        let method = '';

        // Priorité 1 : Poseur directement lié au client (nouveau champ)
        if (found.default_poseur && allPoseurs.length > 0) {
            assignedPoseur = allPoseurs.find(p => p.id === found.default_poseur);
            method = 'Lien Client';
        } 

        // Priorité 2 (Fallback) : Matching par type d'affaire
        if (!assignedPoseur && found.typeAffaire && allPoseurs.length > 0) {
            assignedPoseur = allPoseurs.find(p => p.type === found.typeAffaire);
            method = 'Type Affaire';
        }

        if (assignedPoseur) {
            setSelectedPoseurId(assignedPoseur.id);
            addLog('info', `Poseur assigné (${method}) : ${assignedPoseur.nom}`);
        }
      }

    } catch (e) {
      console.error("Erreur parsing clients", e);
    }
  }, [extractedData?.nom_client, allPoseurs, addLog, refreshDataTrigger]);

  // 2. Récupération automatique du numéro d'affaire via Webhook
  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) {
        setAutoChantierNumber(null);
        return;
      }

      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;

      setIsFetchingChantier(true);
      try {
        console.log(`📡 Appel Webhook Auto pour ${mappedClient.nom} (${mappedClient.typeAffaire})...`);
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.nom
          })
        });

        if (response.ok) {
          const result = await response.json();
          let newNumber = "";

          if (result.numero_affaire) newNumber = result.numero_affaire;
          else if (result.next_id) newNumber = result.next_id;
          else if (result.value) newNumber = result.value;
          else if (typeof result === 'string') newNumber = result;
          else if (typeof result === 'number') newNumber = String(result);

          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            console.log("✅ Numéro récupéré :", formattedNumber);
          }
        }
      } catch (e) {
        console.error("Erreur Webhook Auto:", e);
      } finally {
        setIsFetchingChantier(false);
      }
    };

    fetchChantier();
  }, [mappedClient]);

  // --- SAVE RDV ---
  const handleSaveRdv = async () => {
      if (!tentativeEvent || !selectedPoseurId) return;

      addLog('request', `Validation RDV le ${new Date(tentativeEvent.start).toLocaleString()}...`);

      try {
          let fileData = null;
          let fileName = null;

          if (originalFile) {
              fileName = originalFile.name;
              fileData = await new Promise<string>((resolve, reject) => {
                  const reader = new FileReader();
                  reader.onload = () => resolve((reader.result as string).split(',')[1]); 
                  reader.onerror = reject;
                  reader.readAsDataURL(originalFile);
              });
          }

          const res = await fetch('/api/calendar/event/save', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  poseur_id: selectedPoseurId,
                  event: tentativeEvent,
                  file: fileData ? { name: fileName, data: fileData } : undefined
              })
          });

          const result = await res.json();

          if (res.ok && result.success) {
              addLog('success', `RDV validé et enregistré dans Nextcloud.`);
              setIsRdvSaved(true);
              setTentativeEvent(null); // Plus de tentative, c'est enregistré
              setCalendarRefreshTrigger(prev => prev + 1); // Force refresh calendar
          } else {
              throw new Error(result.error || "Erreur enregistrement");
          }

      } catch (e: any) {
          addLog('error', `Echec validation RDV: ${e.message}`);
          alert("Erreur lors de la validation du RDV: " + e.message);
      }
  };


  // --- TRANSMISSION WEBHOOK ---
  const handleTransmit = async () => {
      if (!extractedData) return;

      setTransmitting(true);
      setTransmitStatus('idle');
      const webhookUrl = localStorage.getItem('buildscan_webhook_url') || "http://194.116.0.110:5678/webhook-test/857f9b11-6d28-4377-a63b-c431ff3fc324";

      // Calcul des données dérivées pour l'envoi
      const chantier = autoChantierNumber || (extractedData.num_bon_travaux ? extractedData.num_bon_travaux.replace(/\D/g, '').substring(0, 6) : "000000");
      const imputation = `80${chantier}0`;
      const fullAddress = [extractedData.adresse_1, extractedData.adresse_2, extractedData.adresse_3].filter(Boolean).join(' ');
      const contactFull = [extractedData.gardien_nom, extractedData.gardien_tel].filter(Boolean).join(' - ');
      const selectedPoseur = allPoseurs.find(p => p.id === selectedPoseurId);

      const formData = new FormData();

      if (originalFile) {
        formData.append('file', originalFile, 'document.pdf');
      }

      formData.append('codeClient', mappedClient?.codeClient || '');
      formData.append('code_trv', mappedClient?.typeAffaire || 'O3-0');
      formData.append('client_bpu', mappedClient?.bpu || '');
      formData.append('client_nom', mappedClient?.nom || '');
      formData.append('num_chantier', chantier);
      formData.append('imputation', imputation);
      formData.append('source', "BuildScan AI");
      formData.append('timestamp', new Date().toISOString());

      formData.append('num_bon_travaux', extractedData.num_bon_travaux || '');
      formData.append('nom_client', extractedData.nom_client || '');

      formData.append('adresse_1', extractedData.adresse_1 || '');
      formData.append('adresse_2', extractedData.adresse_2 || '');
      formData.append('adresse_3', extractedData.adresse_3 || '');
      formData.append('adresse_intervention', fullAddress);

      formData.append('gardien_nom', extractedData.gardien_nom || '');
      formData.append('gardien_tel', extractedData.gardien_tel || '');
      formData.append('gardien_email', extractedData.gardien_email || '');
      formData.append('coord_gardien', contactFull);

      formData.append('delai_intervention', extractedData.delai_intervention || '');
      formData.append('date_intervention', extractedData.date_intervention || '');
      formData.append('descriptif_travaux', extractedData.descriptif_travaux || '');
      formData.append('libelle', extractedData.nom_client || '');

      if (selectedPoseur) {
        formData.append('poseur_id', selectedPoseur.id);
        formData.append('poseur_nom', selectedPoseur.nom);
        formData.append('poseur_code', selectedPoseur.codeSalarie || '');
        formData.append('poseur_type', selectedPoseur.type || '');
      }

      addLog('request', `Envoi vers n8n...`, { 
          imputation, 
          poseur: selectedPoseur?.nom 
      });

      try {
        const response = await fetch(webhookUrl, {
          method: 'POST',
          body: formData
        });

        // Lecture de la réponse JSON de n8n
        const result = await response.json().catch(() => ({}));

        // On considère un succès si HTTP OK et (pas de json OU json.success=true)
        if (response.ok && (result.success !== false)) {
          setTransmitStatus('success');
          addLog('response', `Réponse n8n : ${result.message || 'Succès'}`);
        } else {
          throw new Error(result.message || `Erreur n8n : ${response.status}`);
        }
      } catch (err: any) {
        console.error("Erreur Webhook:", err);
        setTransmitStatus('error');
        addLog('error', `Échec transmission: ${err.message}`);
      } finally {
        setTransmitting(false);
      }
  };

  const handlePdfDoubleClick = () => {
    setIsPdfModalOpen(true);
    setIsCalendarVisible(false);
  };

  const handleViewChange = async (view: AppView) => {
    if (view === 'analyzer') {
      // Lors du retour à l'analyseur, on recharge les configs pour prendre en compte les modifs admin
      // et on incrémente le trigger pour relancer le matching client/poseur
      const config = await fetchStorageConfig();
      if (config) {
        setAllPoseurs(config.poseurs);
      }
      setRefreshDataTrigger(prev => prev + 1);
      setCurrentView('analyzer');
      return;
    }

    if (view === 'admin') {
      if (isAuthenticated) {
        setCurrentView('admin');
      } else {
        setShowAuthModal(true);
      }
    }
  };

  const handleAuthSuccess = () => {
    setIsAuthenticated(true);
    setShowAuthModal(false);
    setCurrentView('admin');
  };

  const handleAuthCancel = () => {
    setShowAuthModal(false);
    if (currentView !== 'analyzer') setCurrentView('analyzer');
  };

  const handleDataUpdate = (updates: Partial<ConstructionOrderData>) => {
    if (extractedData) {
      setExtractedData(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handlePoseurSelect = (id: string, poseurs: Poseur[]) => {
      setSelectedPoseurId(id);
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') {
      setError("Format invalide. Veuillez uploader un PDF.");
      setStatus(AppStatus.ERROR);
      return;
    }

    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setMappedClient(null);
    setAutoChantierNumber(null);
    setOriginalFile(file);
    // Reset states
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    // Réinitialisation layout
    setIsCalendarVisible(true);

    addLog('info', 'Analyse du document démarrée...');

    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);

      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      // AUTO HIDE UI ELEMENTS ON SUCCESS
      setIsSidebarOpen(false); 
      setIsHeaderVisible(false);

      addLog('success', 'Extraction IA terminée avec succès.', { client: data.nom_client });
    } catch (err: any) {
      console.error("Analyse échouée:", err);
      let msg = err.message || "Une erreur inconnue est survenue.";
      if (msg.includes("429") || msg.toLowerCase().includes("quota")) {
        msg = "Quota dépassé (Erreur 429). Veuillez patienter 60 secondes.";
      }
      setError(msg);
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${msg}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setAutoChantierNumber(null);
    setError(null);
    setOriginalFile(null);
    setSelectedPoseurId("");
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    // Re-ouvrir la sidebar et le header si on reset
    setIsSidebarOpen(true);
    setIsHeaderVisible(true);
    setIsCalendarVisible(true);
  };

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-slate-600 font-bold">Connexion à la Base de Données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans overflow-x-hidden relative">

      {/* MODAL PDF GRAND FORMAT */}
      {isPdfModalOpen && filePreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white w-full h-full max-w-6xl rounded-2xl shadow-2xl overflow-hidden flex flex-col relative">
              <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between shrink-0">
                  <span className="font-bold text-sm uppercase tracking-wider"><i className="fas fa-file-pdf mr-2"></i> Aperçu Document (Mode Copie)</span>
                  <button 
                    onClick={() => setIsPdfModalOpen(false)}
                    className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-700 transition-colors"
                  >
                    <i className="fas fa-times"></i>
                  </button>
              </div>
              <div className="flex-grow bg-slate-200">
                  <iframe src={`${filePreviewUrl}#toolbar=0&navpanes=0`} className="w-full h-full" title="PDF Fullscreen"></iframe>
              </div>
           </div>
        </div>
      )}

      {/* HEADER TOGGLE BUTTON (Visible only when header is hidden) */}
      {!isHeaderVisible && (
         <button 
           onClick={() => setIsHeaderVisible(true)}
           className="absolute top-2 right-4 z-50 bg-slate-800 text-slate-400 hover:text-white p-2 rounded-b-lg shadow-md text-xs font-bold transition-all opacity-50 hover:opacity-100"
           title="Afficher le menu"
         >
           <i className="fas fa-chevron-down"></i> Menu
         </button>
      )}

      {/* HEADER (Conditionally rendered) */}
      {isHeaderVisible && <Header currentView={currentView} onViewChange={handleViewChange} />}

      {showAuthModal && (
        <AdminAuth onAuthenticated={handleAuthSuccess} onCancel={handleAuthCancel} />
      )}

      <main className={`flex-grow container mx-auto px-4 py-8 max-w-[98%] transition-all ${!isHeaderVisible ? 'pt-4' : ''}`}>
        <div className="mx-auto">
          {currentView === 'admin' && <AdminDashboard />}

          {currentView === 'analyzer' && (
            <div className="flex flex-col lg:flex-row gap-6 transition-all duration-300">

              {/* COLONNE GAUCHE : UPLOAD (Masquable) */}
              <div className={`${isSidebarOpen ? 'lg:w-[350px] shrink-0' : 'w-0 overflow-hidden'} transition-all duration-300`}>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-24">
                   <div className="flex justify-between items-center mb-4">
                      <h2 className="text-xl font-black flex items-center gap-2 uppercase tracking-tight">
                        <i className="fas fa-file-pdf text-blue-600"></i>
                        Scan PDF
                      </h2>
                      <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fas fa-times"></i></button>
                   </div>
                  <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />

                  {filePreviewUrl && (
                    <div className="mt-6 animate-in fade-in zoom-in-95 duration-300 group">
                      <div className="flex justify-between items-center mb-2">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Aperçu</p>
                          <span className="text-[9px] bg-blue-100 text-blue-700 px-2 rounded-full font-bold opacity-0 group-hover:opacity-100 transition-opacity">Double-clic pour agrandir</span>
                      </div>
                      <div 
                        onDoubleClick={handlePdfDoubleClick}
                        className="relative border border-slate-200 rounded-xl overflow-hidden bg-slate-100 min-h-[500px] flex items-center justify-center shadow-inner cursor-zoom-in hover:ring-2 hover:ring-blue-400 transition-all"
                        title="Double-cliquez pour agrandir et sélectionner du texte"
                      >
                        <iframe src={`${filePreviewUrl}#toolbar=0`} title="PDF Preview" className="w-full h-[500px] border-none pointer-events-none" />
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* BOUTON TOGGLE Sidebar (Si sidebar fermée) */}
              {!isSidebarOpen && (
                 <div className="absolute left-4 top-24 z-40">
                    <button 
                        onClick={() => setIsSidebarOpen(true)}
                        className="bg-blue-600 text-white p-3 rounded-full shadow-lg hover:bg-blue-700 transition-colors"
                        title="Afficher Scan"
                    >
                        <i className="fas fa-file-pdf"></i>
                    </button>
                 </div>
              )}

              {/* COLONNE DROITE : RESULTATS */}
              <div className="flex-grow flex flex-col gap-6 min-w-0">
                {/* BOUTON TOGGLE Sidebar Desktop */}
                {isSidebarOpen && status === AppStatus.SUCCESS && (
                     <div className="hidden lg:flex justify-start">
                        <button 
                            onClick={() => setIsSidebarOpen(false)}
                            className="text-xs font-bold text-slate-400 hover:text-blue-600 flex items-center gap-2"
                        >
                            <i className="fas fa-chevron-left"></i> Masquer le Scan (Plein écran)
                        </button>
                     </div>
                )}

                {status === AppStatus.IDLE && (
                  <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl shadow-blue-900/20 mx-auto max-w-2xl mt-10">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto mb-6 backdrop-blur-sm">
                      <i className="fas fa-robot text-4xl"></i>
                    </div>
                    <h3 className="text-2xl font-black mb-2 uppercase tracking-tight">Analyseur BuildScan</h3>
                    <p className="text-blue-100 font-medium">Glissez un PDF pour extraire les données chantiers vers l'ERP et l'Agenda.</p>
                  </div>
                )}

                {status === AppStatus.ANALYZING && (
                  <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center shadow-sm mx-auto max-w-2xl mt-10">
                    <div className="relative animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4 shadow-lg"></div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Extraction en cours...</h3>
                  </div>
                )}

                {status === AppStatus.ERROR && (
                  <div className="bg-red-50 border-2 border-red-100 rounded-2xl p-8 animate-in shake duration-500 mx-auto max-w-2xl mt-10">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0">
                        <i className="fas fa-exclamation-triangle text-xl"></i>
                      </div>
                      <div className="flex-grow">
                        <h3 className="text-lg font-black text-red-800 uppercase tracking-tight">Échec de l'IA</h3>
                        <p className="text-red-700 mt-1 font-medium italic">{error}</p>
                        <button onClick={reset} className="mt-4 bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg shadow-red-200">
                          Réessayer
                        </button>
                      </div>
                    </div>
                  </div>
                )}

                {extractedData && (
                  <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-6">
                    {/* LAYOUT GRID: RESULTATS (GAUCHE) + CALENDRIER (DROITE) */}
                    <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 items-start">
                        {/* 1. RESULTATS */}
                        <div className={`transition-all duration-300 ${isCalendarVisible ? '' : 'xl:col-span-2'}`}>
                          <ResultCard 
                              data={extractedData} 
                              onReset={reset} 
                              mappedClient={mappedClient}
                              chantierNumber={autoChantierNumber}
                              isFetchingChantier={isFetchingChantier}
                              onUpdate={handleDataUpdate}
                              // Props ajoutées pour transmission et poseur
                              poseurs={allPoseurs}
                              selectedPoseurId={selectedPoseurId}
                              onPoseurSelect={setSelectedPoseurId}
                              onTransmit={handleTransmit}
                              isTransmitting={transmitting}
                              transmitStatus={transmitStatus}
                              // Props validation RDV
                              tentativeEvent={tentativeEvent}
                              isRdvSaved={isRdvSaved}
                              onValidateRdv={handleSaveRdv}
                              // Props toggle calendar
                              isCalendarVisible={isCalendarVisible}
                              onToggleCalendar={() => setIsCalendarVisible(!isCalendarVisible)}
                          />
                        </div>

                        {/* 2. CALENDRIER (A DROITE) - MASQUABLE */}
                        {isCalendarVisible && (
                          <div className="h-full min-h-[600px] animate-in fade-in slide-in-from-right-4 duration-300">
                              <CalendarManager 
                                  poseurs={allPoseurs}
                                  selectedPoseurId={selectedPoseurId}
                                  data={extractedData}
                                  onAddLog={addLog}
                                  chantierNumber={autoChantierNumber}
                                  originalFile={originalFile}
                                  onUpdate={handleDataUpdate}
                                  onTentativeChange={setTentativeEvent}
                                  onRdvStatusChange={setIsRdvSaved}
                                  refreshTrigger={calendarRefreshTrigger}
                                  onClose={() => setIsCalendarVisible(false)}
                              />
                          </div>
                        )}
                    </div>

                    {/* 3. TERMINAL (EN BAS) */}
                    <SqlExporter 
                      data={extractedData} 
                      originalFile={originalFile || undefined} 
                      mappedClient={mappedClient}
                      prefilledChantierNumber={autoChantierNumber}
                      onPoseurSelect={(id) => setSelectedPoseurId(id)}
                      logs={logs}
                      onAddLog={addLog}
                      onClearLogs={clearLogs}
                    />
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center">
          <span className="text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.7 • Nextcloud Ed.</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { Poseur, NextcloudConfig, ConstructionOrderData, LogEntry, CalendarEvent } from '../types';

interface CalendarManagerProps {
  poseurs: Poseur[];
  selectedPoseurId: string;
  data: ConstructionOrderData;
  onAddLog: (type: LogEntry['type'], message: string, data?: any) => void;
  chantierNumber: string | null;
  originalFile: File | null;
  onUpdate?: (updates: Partial<ConstructionOrderData>) => void;

  // New props for sync
  onTentativeChange?: (event: CalendarEvent | null) => void;
  onRdvStatusChange?: (isSaved: boolean) => void;
  refreshTrigger?: number; // Pour forcer le rafraichissement depuis le parent

  // UI Control
  onClose?: () => void;
}

const CalendarManager: React.FC<CalendarManagerProps> = ({ 
  poseurs, 
  selectedPoseurId, 
  data, 
  onAddLog, 
  chantierNumber, 
  originalFile,
  onUpdate,
  onTentativeChange,
  onRdvStatusChange,
  refreshTrigger = 0,
  onClose
}) => {
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [weekOffset, setWeekOffset] = useState(0);

  // States pour la modale d'édition
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEvent, setEditingEvent] = useState<CalendarEvent | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  const nextcloudConfigString = localStorage.getItem('buildscan_nextcloud');
  const nextcloudConfig: NextcloudConfig | null = nextcloudConfigString ? JSON.parse(nextcloudConfigString) : null;

  const selectedPoseur = useMemo(() => 
    poseurs.find(p => p.id === selectedPoseurId), 
  [poseurs, selectedPoseurId]);

  const webInterfaceUrl = useMemo(() => {
     if (!nextcloudConfig?.url) return null;
     return `${nextcloudConfig.url.replace(/\/$/, '')}/index.php/apps/calendar/`;
  }, [nextcloudConfig]);

  // Déterminer la date du chantier pour l'affichage initial
  const jobDate = useMemo(() => {
    // Si delai_intervention contient une heure (format HHhMM), on ignore pour trouver la date de base
    // Le regex cherche JJ/MM/AAAA
    const dateStr = data.delai_intervention || data.date_intervention;
    if (!dateStr) return new Date();
    const parts = dateStr.match(/(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})/);
    if (parts) {
      // On initialise à 8h30 par défaut
      return new Date(parseInt(parts[3]), parseInt(parts[2]) - 1, parseInt(parts[1]), 8, 30, 0);
    }
    const d = new Date();
    d.setHours(8, 30, 0, 0);
    return d;
  }, [data.delai_intervention, data.date_intervention]);

  // Récupération des événements via le Proxy Server
  const fetchEvents = async () => {
    if (!selectedPoseurId || !selectedPoseur?.nextcloud_user) return;

    setIsLoading(true);
    setFetchError(null);
    // onAddLog('request', `Sync Nextcloud: Récupération agenda...`);

    try {
      const res = await fetch('/api/calendar/events', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ poseur_id: selectedPoseurId })
      });

      let result;
      try {
        result = await res.json();
      } catch (e) {
        throw new Error(`Erreur critique: Réponse serveur invalide (${res.status})`);
      }

      if (!res.ok || !result.success) {
        throw new Error(result.error || "Erreur serveur inconnue");
      }

      setEvents(result.events);

    } catch (e: any) {
      console.error("Erreur Fetch Calendar:", e);
      setFetchError(e.message || "Impossible de récupérer l'agenda.");
      onAddLog('error', `Erreur Nextcloud CalDAV: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (selectedPoseurId) {
      setEvents([]);
      fetchEvents();
    }
  }, [selectedPoseurId, refreshTrigger]);

  // Logique pure pour trouver le prochain créneau (Tetris)
  const findNextAvailableSlot = (baseDate: Date, existingEvents: CalendarEvent[]) => {
      let tentativeStart = new Date(baseDate);
      tentativeStart.setHours(8, 30, 0, 0);

      const DURATION_MINUTES = 120; // 2 heures
      const MAX_START_HOUR = 15;
      const MAX_START_MINUTE = 30;

      const isWeekend = (d: Date) => d.getDay() === 0 || d.getDay() === 6;

      while(isWeekend(tentativeStart)) {
         tentativeStart.setDate(tentativeStart.getDate() + 1);
         tentativeStart.setHours(8, 30, 0, 0);
      }

      let isSlotFound = false;
      let safetyCounter = 0;

      while (!isSlotFound && safetyCounter < 100) {
         safetyCounter++;

         if (tentativeStart.getHours() > MAX_START_HOUR || 
            (tentativeStart.getHours() === MAX_START_HOUR && tentativeStart.getMinutes() > MAX_START_MINUTE)) {
            tentativeStart.setDate(tentativeStart.getDate() + 1);
            tentativeStart.setHours(8, 30, 0, 0);
            while(isWeekend(tentativeStart)) {
               tentativeStart.setDate(tentativeStart.getDate() + 1);
            }
            continue;
         }

         const tentativeEnd = new Date(tentativeStart.getTime() + DURATION_MINUTES * 60000);

         const dayEvents = existingEvents.filter(e => {
            const evtDate = new Date(e.start);
            return evtDate.toDateString() === tentativeStart.toDateString();
         });

         const collision = dayEvents.find(e => {
            const eStart = new Date(e.start).getTime();
            const eEnd = new Date(e.end).getTime();
            const tStart = tentativeStart.getTime();
            const tEnd = tentativeEnd.getTime();
            return (tStart < eEnd && tEnd > eStart);
         });

         if (collision) {
            tentativeStart = new Date(collision.end);
         } else {
            isSlotFound = true;
         }
      }

      return { start: tentativeStart, end: new Date(tentativeStart.getTime() + DURATION_MINUTES * 60000) };
  };

  // Gestion des événements (Affichage + Calcul Tentative)
  const displayEvents = useMemo(() => {
    const list: CalendarEvent[] = [...events];
    let tentative: CalendarEvent | null = null;
    let savedFound = false;

    // Vérifier si le bon de travail est DÉJÀ dans l'agenda
    if (data.num_bon_travaux && events.length > 0) {
        // Recherche un événement qui contient le numéro de bon dans le titre ou la description
        // On nettoie le num bon pour éviter les erreurs de format
        const cleanBon = data.num_bon_travaux.replace(/[^a-zA-Z0-9]/g, '');

        const existingEvent = events.find(e => {
            const t = (e.title || '').replace(/[^a-zA-Z0-9]/g, '');
            const d = (e.description || '').replace(/[^a-zA-Z0-9]/g, '');
            return (t.includes(cleanBon) || d.includes(cleanBon)) && cleanBon.length > 3;
        });

        if (existingEvent) {
            savedFound = true;
        }
    }

    // Notifier le parent si c'est sauvegardé ou non
    // On utilise un timeout pour éviter l'update pendant le render
    setTimeout(() => {
        if (onRdvStatusChange) onRdvStatusChange(savedFound);
    }, 0);

    // Si pas sauvegardé, on propose un créneau (Tetris)
    if (!savedFound && data.nom_client) {

      const slot = findNextAvailableSlot(jobDate, list);

      const titleParts = [
        chantierNumber ? `${chantierNumber}` : null,
        data.num_bon_travaux ? `${data.num_bon_travaux}` : null,
        data.nom_client
      ].filter(Boolean);

      const title = titleParts.join(' - ');

      tentative = {
        uid: 'tentative-preview',
        title: title,
        start: slot.start.toISOString(),
        end: slot.end.toISOString(),
        location: `${data.adresse_1} ${data.adresse_3}`,
        description: `Client: ${data.nom_client}\nTel: ${data.gardien_tel || 'N/A'}\n${data.descriptif_travaux}\nRef: ${data.num_bon_travaux}`,
        isTentative: true
      };

      list.push(tentative);
    }

    // Notifier le parent du changement de tentative (pour le bouton Validation)
    setTimeout(() => {
        if (onTentativeChange) onTentativeChange(tentative);
    }, 0);

    return list.sort((a, b) => new Date(a.start).getTime() - new Date(b.start).getTime());
  }, [events, data, jobDate, chantierNumber]); // Dependancies

  // Update du délai d'intervention (Synchro inverse Agenda -> Extraction)
  useEffect(() => {
      if (!onUpdate || !data.nom_client) return;

      let targetEvent: CalendarEvent | undefined;

      // 1. Priorité : Événement déjà enregistré (Confirmé)
      if (data.num_bon_travaux) {
          const cleanBon = data.num_bon_travaux.replace(/[^a-zA-Z0-9]/g, '');
          if (cleanBon.length > 3) {
             targetEvent = displayEvents.find(e => {
                if (e.isTentative) return false;
                const t = (e.title || '').replace(/[^a-zA-Z0-9]/g, '');
                const d = (e.description || '').replace(/[^a-zA-Z0-9]/g, '');
                return t.includes(cleanBon) || d.includes(cleanBon);
             });
          }
      }

      // 2. Fallback : Événement Tentative
      if (!targetEvent) {
          targetEvent = displayEvents.find(e => e.isTentative);
      }

      if (targetEvent) {
          const startDate = new Date(targetEvent.start);
          const day = String(startDate.getDate()).padStart(2, '0');
          const month = String(startDate.getMonth() + 1).padStart(2, '0');
          const year = startDate.getFullYear();
          const hour = String(startDate.getHours()).padStart(2, '0');
          const min = String(startDate.getMinutes()).padStart(2, '0');

          const formattedString = `${day}/${month}/${year} ${hour}h${min}`;

          if (data.delai_intervention !== formattedString) {
              onUpdate({ delai_intervention: formattedString });
          }
      }
  }, [displayEvents, data.num_bon_travaux, data.delai_intervention, data.nom_client, onUpdate]);

  // Gestion des jours semaine
  const weekDays = useMemo(() => {
    const days = [];
    const startOfWeek = new Date(jobDate);
    startOfWeek.setDate(startOfWeek.getDate() + (weekOffset * 7));

    const day = startOfWeek.getDay();
    const diff = startOfWeek.getDate() - day + (day === 0 ? -6 : 1);
    startOfWeek.setDate(diff);

    for (let i = 0; i < 5; i++) {
      const d = new Date(startOfWeek);
      d.setDate(startOfWeek.getDate() + i);
      days.push(d);
    }
    return days;
  }, [jobDate, weekOffset]);

  const toLocalISO = (dateStr: string) => {
    const d = new Date(dateStr);
    const pad = (n: number) => n < 10 ? '0' + n : n;
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  };

  const handleEventDoubleClick = (evt: CalendarEvent) => {
    setEditingEvent({ ...evt });
    setIsModalOpen(true);
  };

  const handleSaveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingEvent || !selectedPoseurId) return;

    setIsSaving(true);
    onAddLog('request', `Enregistrement manuel rendez-vous...`);

    try {
      let fileData = null;
      let fileName = null;

      if (editingEvent.isTentative && originalFile) {
        fileName = originalFile.name;
        fileData = await new Promise<string>((resolve, reject) => {
          const reader = new FileReader();
          reader.onload = () => resolve((reader.result as string).split(',')[1]); 
          reader.onerror = reject;
          reader.readAsDataURL(originalFile);
        });
      }

      const res = await fetch('/api/calendar/event/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          poseur_id: selectedPoseurId,
          event: editingEvent,
          file: fileData ? { name: fileName, data: fileData } : undefined
        })
      });

      const result = await res.json();

      if (res.ok && result.success) {
         onAddLog('success', `Rendez-vous enregistré (Manuel).`);
         setIsModalOpen(false);
         fetchEvents();
      } else {
         throw new Error(result.error);
      }
    } catch (err: any) {
      onAddLog('error', `Erreur sauvegarde: ${err.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  // Helper pour vérifier si un event est celui enregistré pour ce bon
  const isSavedEvent = (evt: CalendarEvent) => {
      if (evt.isTentative) return false;
      if (!data.num_bon_travaux) return false;
      const cleanBon = data.num_bon_travaux.replace(/[^a-zA-Z0-9]/g, '');
      const t = (evt.title || '').replace(/[^a-zA-Z0-9]/g, '');
      const d = (evt.description || '').replace(/[^a-zA-Z0-9]/g, '');
      return (t.includes(cleanBon) || d.includes(cleanBon)) && cleanBon.length > 3;
  };

  if (!nextcloudConfig) {
    return (
      <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800 p-6 flex flex-col items-center justify-center text-center h-full">
         <p className="text-white font-bold text-sm">Calendrier non configuré</p>
      </div>
    );
  }

  return (
    <div className="bg-slate-900 rounded-xl overflow-hidden shadow-lg border border-slate-800 h-full flex flex-col relative">

       {/* HEADER */}
       <div className="px-4 py-3 border-b border-slate-800 flex items-center justify-between bg-slate-900">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-sky-600/20 text-sky-400 rounded flex items-center justify-center">
              <i className="fas fa-calendar-alt text-sm"></i>
            </div>
            <div>
              <h3 className="text-white font-bold uppercase tracking-wider text-xs">Agenda <span className="text-sky-400">Nextcloud</span></h3>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-tighter">
                {selectedPoseur ? selectedPoseur.nom : 'Non assigné'}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-2 bg-slate-800 rounded-lg p-1">
             <button onClick={() => setWeekOffset(prev => prev - 1)} className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors">
                <i className="fas fa-chevron-left text-xs"></i>
             </button>
             <span className="text-[10px] font-mono font-bold text-slate-300 w-16 text-center">
                Sem {weekOffset > 0 ? `+${weekOffset}` : weekOffset}
             </span>
             <button onClick={() => setWeekOffset(prev => prev + 1)} className="w-6 h-6 flex items-center justify-center text-slate-400 hover:text-white hover:bg-slate-700 rounded transition-colors">
                <i className="fas fa-chevron-right text-xs"></i>
             </button>
          </div>

          <div className="flex gap-2">
             <button 
                onClick={fetchEvents}
                disabled={isLoading || !selectedPoseur}
                className="w-8 h-8 flex items-center justify-center rounded hover:bg-slate-800 text-slate-400 hover:text-white transition-colors"
                title="Rafraîchir"
            >
                <i className={`fas fa-sync-alt ${isLoading ? 'fa-spin' : ''}`}></i>
            </button>

            {onClose && (
                <button 
                    onClick={onClose}
                    className="w-8 h-8 flex items-center justify-center rounded hover:bg-slate-800 text-slate-400 hover:text-red-400 transition-colors"
                    title="Masquer l'agenda"
                >
                    <i className="fas fa-compress-alt"></i>
                </button>
            )}
          </div>
       </div>

       {/* CALENDRIER */}
       <div className="flex-grow flex flex-col overflow-hidden bg-slate-950">
         {!selectedPoseur ? (
            <div className="flex-grow flex flex-col items-center justify-center text-center p-4">
               <p className="text-slate-500 text-xs italic">Sélectionnez un poseur.</p>
            </div>
         ) : (
           <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
              <div className="space-y-4">
                 {weekDays.map(day => {
                    const dayEvents = displayEvents.filter(e => {
                        const evtDate = new Date(e.start);
                        return evtDate.getDate() === day.getDate() && 
                               evtDate.getMonth() === day.getMonth() &&
                               evtDate.getFullYear() === day.getFullYear();
                    });

                    const isJobDay = day.getDate() === jobDate.getDate() && 
                                     day.getMonth() === jobDate.getMonth() &&
                                     weekOffset === 0;

                    const isToday = new Date().getDate() === day.getDate() && 
                                    new Date().getMonth() === day.getMonth();

                    return (
                        <div key={day.toISOString()} className={`rounded-lg border ${isJobDay ? 'border-sky-800 bg-sky-900/10' : 'border-slate-800 bg-slate-900/50'} overflow-hidden`}>
                            <div className={`px-3 py-2 text-xs font-bold uppercase flex justify-between ${isJobDay ? 'text-sky-400' : isToday ? 'text-white' : 'text-slate-500'}`}>
                                <span>{day.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'short' })}</span>
                                {dayEvents.length > 0 && <span className="text-[10px] bg-slate-800 px-2 rounded-full text-slate-300">{dayEvents.length}</span>}
                            </div>

                            <div className="p-2 space-y-2 min-h-[40px]">
                                {dayEvents.length === 0 ? (
                                    <div className="text-[10px] text-slate-800 italic pl-2">...</div>
                                ) : (
                                    dayEvents.map((evt, idx) => {
                                        const saved = isSavedEvent(evt);
                                        return (
                                        <div 
                                            key={idx}
                                            onDoubleClick={() => handleEventDoubleClick(evt)}
                                            className={`p-2 rounded text-[11px] border-l-2 flex flex-col gap-0.5 cursor-pointer hover:brightness-110 transition-all ${
                                                evt.isTentative 
                                                ? 'bg-orange-500/10 border-orange-500 text-orange-200 animate-pulse hover:animate-none' 
                                                : saved
                                                    ? 'bg-emerald-600 border-emerald-400 text-white animate-pulse' // STYLE VERT CLIGNOTANT ICI
                                                    : 'bg-slate-800 border-sky-600 text-slate-300'
                                            }`}
                                        >
                                            <div className="flex justify-between items-start font-bold">
                                                <span>{new Date(evt.start).toLocaleTimeString('fr-FR', {hour: '2-digit', minute:'2-digit'})}</span>
                                                {evt.isTentative && <span className="text-[8px] bg-orange-500 text-black px-1 rounded font-black uppercase">NEW</span>}
                                                {saved && <span className="text-[8px] bg-white text-emerald-700 px-1 rounded font-black uppercase"><i className="fas fa-check"></i> SAVED</span>}
                                            </div>
                                            <div className="truncate font-medium">{evt.title}</div>
                                        </div>
                                    )})
                                )}
                            </div>
                        </div>
                    );
                 })}
              </div>
           </div>
         )}
       </div>

       {/* MODALE D'EDITION */}
       {isModalOpen && editingEvent && (
          <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center p-4 animate-in fade-in duration-200">
             <div className="bg-slate-800 border border-slate-700 w-full max-w-sm rounded-xl shadow-2xl flex flex-col max-h-[90%] overflow-y-auto">
                <form onSubmit={handleSaveEvent} className="p-5 space-y-4">
                   <div className="flex items-center justify-between">
                        <h3 className="text-white font-bold text-lg">Édition Rendez-vous</h3>
                        {editingEvent.isTentative && <span className="text-[10px] bg-orange-500 text-black px-2 py-0.5 rounded font-bold uppercase">Nouveau</span>}
                   </div>

                   <div className="space-y-1">
                       <label className="text-[10px] uppercase font-bold text-slate-400">Titre</label>
                       <input 
                         type="text" required
                         className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-white text-sm focus:border-blue-500 outline-none"
                         value={editingEvent.title}
                         onChange={e => setEditingEvent({...editingEvent, title: e.target.value})}
                       />
                   </div>

                   <div className="grid grid-cols-2 gap-3">
                       <div className="space-y-1">
                           <label className="text-[10px] uppercase font-bold text-slate-400">Début</label>
                           <input 
                             type="datetime-local" required
                             className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-white text-xs focus:border-blue-500 outline-none"
                             value={toLocalISO(editingEvent.start)}
                             onChange={e => {
                                 const d = new Date(e.target.value);
                                 setEditingEvent({...editingEvent, start: d.toISOString()});
                             }}
                           />
                       </div>
                       <div className="space-y-1">
                           <label className="text-[10px] uppercase font-bold text-slate-400">Fin</label>
                           <input 
                             type="datetime-local" required
                             className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-white text-xs focus:border-blue-500 outline-none"
                             value={toLocalISO(editingEvent.end)}
                             onChange={e => {
                                 const d = new Date(e.target.value);
                                 setEditingEvent({...editingEvent, end: d.toISOString()});
                             }}
                           />
                       </div>
                   </div>

                   <div className="space-y-1">
                       <label className="text-[10px] uppercase font-bold text-slate-400">Description</label>
                       <textarea 
                         className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-white text-xs focus:border-blue-500 outline-none h-24"
                         value={editingEvent.description || ''}
                         onChange={e => setEditingEvent({...editingEvent, description: e.target.value})}
                       />
                   </div>

                   <div className="flex gap-2 pt-2 border-t border-slate-700 mt-2">
                       <button type="submit" disabled={isSaving} className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-white py-2 rounded-lg font-bold transition-colors flex items-center justify-center gap-2">
                          {isSaving && <i className="fas fa-spinner fa-spin"></i>}
                          Enregistrer
                       </button>
                       <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 bg-slate-700 hover:bg-slate-600 text-white py-2 rounded-lg font-bold transition-colors">
                          Annuler
                       </button>
                   </div>
                </form>
             </div>
          </div>
       )}
    </div>
  );
};

export default CalendarManager;

import React, { useState, useCallback, useEffect } from 'react';
import { AppStatus, ConstructionOrderData, AppView, Client, Poseur, LogEntry, CalendarEvent } from './types';
import { analyzeConstructionDocument } from './services/geminiService';
import { fetchStorageConfig } from './services/configService';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ResultCard from './components/ResultCard';
import SqlExporter from './components/SqlExporter';
import CalendarManager from './components/CalendarManager';
import AdminDashboard from './components/AdminDashboard';
import AdminAuth from './components/AdminAuth';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('analyzer');
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreviewUrl, setFilePreviewUrl] = useState<string | null>(null);
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Layout State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const [isCalendarVisible, setIsCalendarVisible] = useState(true);
  const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);

  // Terminal Logs State (Shared)
  const [logs, setLogs] = useState<LogEntry[]>([]);

  // Data enrichment states
  const [mappedClient, setMappedClient] = useState<Client | null>(null);
  const [potentialClients, setPotentialClients] = useState<Client[]>([]); // Liste des clients avec le même nom
  const [autoChantierNumber, setAutoChantierNumber] = useState<string | null>(null);
  const [isFetchingChantier, setIsFetchingChantier] = useState(false);

  // Trigger pour forcer le re-calcul du mapping (Client/Poseur) au changement de vue
  const [refreshDataTrigger, setRefreshDataTrigger] = useState(0);

  // Calendar & Poseur sync state
  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");
  const [allPoseurs, setAllPoseurs] = useState<Poseur[]>([]);
  const [tentativeEvent, setTentativeEvent] = useState<CalendarEvent | null>(null);
  const [isRdvSaved, setIsRdvSaved] = useState(false);
  const [calendarRefreshTrigger, setCalendarRefreshTrigger] = useState(0);

  // Transmission State
  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      console.log('🚀 Initialisation BuildScan AI...');
      const config = await fetchStorageConfig();
      if (config) {
        setAllPoseurs(config.poseurs);
      }
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => {
      if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    };
  }, [filePreviewUrl]);

  // --- SHARED LOGGING FUNCTION ---
  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  // --- AUTOMATISATION LOGIQUE METIER ---

  // 1. Détection automatique du Client (Gestion Multi-Affaires)
  useEffect(() => {
    if (!extractedData?.nom_client) {
      setMappedClient(null);
      setPotentialClients([]);
      return;
    }

    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;

    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = extractedData.nom_client.toLowerCase().trim();

      // On récupère TOUS les clients dont le nom matche
      const matches = clients.filter(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || 
               searchName.includes(clientRefNom) || 
               clientRefNom.includes(searchName);
      });

      setPotentialClients(matches);

      // Si on a des matches, on sélectionne le premier par défaut (ou on garde l'existant s'il est toujours valide)
      if (matches.length > 0) {
          // On ne change le mappedClient que s'il n'est pas déjà dans les matches 
          // (évite de réinitialiser si on revient de l'admin)
          const isCurrentStillValid = mappedClient && matches.some(m => m.id === mappedClient.id);
          if (!isCurrentStillValid) {
            setMappedClient(matches[0]);
          }
      } else {
        setMappedClient(null);
      }

    } catch (e) {
      console.error("Erreur parsing clients", e);
    }
  }, [extractedData?.nom_client, refreshDataTrigger]);

  // 2. Assignation automatique du Poseur selon le Client sélectionné
  useEffect(() => {
    if (!mappedClient) return;

    let assignedPoseur: Poseur | undefined;
    let method = '';

    // Priorité 1 : Poseur directement lié au client (nouveau champ)
    if (mappedClient.default_poseur && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.id === mappedClient.default_poseur);
        method = 'Lien Client';
    } 

    // Priorité 2 (Fallback) : Matching par type d'affaire
    if (!assignedPoseur && mappedClient.typeAffaire && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.type === mappedClient.typeAffaire);
        method = 'Type Affaire';
    }

    if (assignedPoseur) {
        setSelectedPoseurId(assignedPoseur.id);
        addLog('info', `Poseur assigné (${method}) : ${assignedPoseur.nom}`);
    }
  }, [mappedClient, allPoseurs, addLog]);

  // 3. Récupération automatique du numéro d'affaire via Webhook (Se déclenche au changement de mappedClient)
  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) {
        setAutoChantierNumber(null);
        return;
      }

      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;

      setIsFetchingChantier(true);
      setAutoChantierNumber(null); // Reset pendant le chargement

      try {
        console.log(`📡 Appel Webhook Auto pour ${mappedClient.nom} (${mappedClient.typeAffaire})...`);
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.nom
          })
        });

        if (response.ok) {
          const result = await response.json();
          let newNumber = "";

          if (result.numero_affaire) newNumber = result.numero_affaire;
          else if (result.next_id) newNumber = result.next_id;
          else if (result.value) newNumber = result.value;
          else if (typeof result === 'string') newNumber = result;
          else if (typeof result === 'number') newNumber = String(result);

          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            addLog('response', `Numéro d'affaire récupéré : ${formattedNumber}`);
          }
        }
      } catch (e) {
        console.error("Erreur Webhook Auto:", e);
        addLog('error', `Échec récupération numéro d'affaire.`);
      } finally {
        setIsFetchingChantier(false);
      }
    };

    fetchChantier();
  }, [mappedClient, addLog]);

  // --- HANDLERS ---
  const handleClientUpdate = (clientId: string) => {
      const selected = potentialClients.find(c => c.id === clientId);
      if (selected) {
          setMappedClient(selected);
          addLog('info', `Changement de Type Affaire : ${selected.typeAffaire}`);
      }
  };

  const handleSaveRdv = async () => {
      if (!tentativeEvent || !selectedPoseurId) return;

      addLog('request', `Validation RDV le ${new Date(tentativeEvent.start).toLocaleString()}...`);

      try {
          let fileData = null;
          let fileName = null;

          if (originalFile) {
              fileName = originalFile.name;
              fileData = await new Promise<string>((resolve, reject) => {
                  const reader = new FileReader();
                  reader.onload = () => resolve((reader.result as string).split(',')[1]); 
                  reader.onerror = reject;
                  reader.readAsDataURL(originalFile);
              });
          }

          const res = await fetch('/api/calendar/event/save', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  poseur_id: selectedPoseurId,
                  event: tentativeEvent,
                  file: fileData ? { name: fileName, data: fileData } : undefined
              })
          });

          const result = await res.json();

          if (res.ok && result.success) {
              addLog('success', `RDV validé et enregistré dans Nextcloud.`);
              setIsRdvSaved(true);
              setTentativeEvent(null);
              setCalendarRefreshTrigger(prev => prev + 1);
          } else {
              throw new Error(result.error || "Erreur enregistrement");
          }

      } catch (e: any) {
          addLog('error', `Echec validation RDV: ${e.message}`);
          alert("Erreur lors de la validation du RDV: " + e.message);
      }
  };


  const handleTransmit = async () => {
      if (!extractedData) return;

      setTransmitting(true);
      setTransmitStatus('idle');
      const webhookUrl = localStorage.getItem('buildscan_webhook_url') || "";

      const chantier = autoChantierNumber || (extractedData.num_bon_travaux ? extractedData.num_bon_travaux.replace(/\D/g, '').substring(0, 6) : "000000");
      const imputation = `80${chantier}0`;
      const fullAddress = [extractedData.adresse_1, extractedData.adresse_2, extractedData.adresse_3].filter(Boolean).join(' ');
      const contactFull = [extractedData.gardien_nom, extractedData.gardien_tel].filter(Boolean).join(' - ');
      const selectedPoseur = allPoseurs.find(p => p.id === selectedPoseurId);

      const formData = new FormData();
      if (originalFile) formData.append('file', originalFile, 'document.pdf');

      formData.append('codeClient', mappedClient?.codeClient || '');
      formData.append('code_trv', mappedClient?.typeAffaire || 'O3-0');
      formData.append('client_bpu', mappedClient?.bpu || '');
      formData.append('client_nom', mappedClient?.nom || '');
      formData.append('num_chantier', chantier);
      formData.append('imputation', imputation);
      formData.append('source', "BuildScan AI");
      formData.append('timestamp', new Date().toISOString());
      formData.append('num_bon_travaux', extractedData.num_bon_travaux || '');
      formData.append('nom_client', extractedData.nom_client || '');
      formData.append('adresse_intervention', fullAddress);
      formData.append('coord_gardien', contactFull);
      formData.append('gardien_email', extractedData.gardien_email || '');
      formData.append('delai_intervention', extractedData.delai_intervention || '');
      formData.append('date_intervention', extractedData.date_intervention || '');
      formData.append('descriptif_travaux', extractedData.descriptif_travaux || '');
      formData.append('libelle', extractedData.nom_client || '');

      if (selectedPoseur) {
        formData.append('poseur_id', selectedPoseur.id);
        formData.append('poseur_nom', selectedPoseur.nom);
        formData.append('poseur_code', selectedPoseur.codeSalarie || '');
        formData.append('poseur_type', selectedPoseur.type || '');
      }

      addLog('request', `Envoi vers n8n...`, { imputation, poseur: selectedPoseur?.nom });

      try {
        const response = await fetch(webhookUrl, {
          method: 'POST',
          body: formData
        });
        const result = await response.json().catch(() => ({}));

        if (response.ok && (result.success !== false)) {
          setTransmitStatus('success');
          addLog('response', `Réponse n8n : ${result.message || 'Succès'}`);
        } else {
          throw new Error(result.message || `Erreur n8n : ${response.status}`);
        }
      } catch (err: any) {
        setTransmitStatus('error');
        addLog('error', `Échec transmission: ${err.message}`);
      } finally {
        setTransmitting(false);
      }
  };

  const handlePdfDoubleClick = () => {
    setIsPdfModalOpen(true);
    setIsCalendarVisible(false);
  };

  const handleViewChange = async (view: AppView) => {
    if (view === 'analyzer') {
      const config = await fetchStorageConfig();
      if (config) setAllPoseurs(config.poseurs);
      setRefreshDataTrigger(prev => prev + 1);
      setCurrentView('analyzer');
      return;
    }

    if (view === 'admin') {
      if (isAuthenticated) setCurrentView('admin');
      else setShowAuthModal(true);
    }
  };

  const handleAuthSuccess = () => {
    setIsAuthenticated(true);
    setShowAuthModal(false);
    setCurrentView('admin');
  };

  const handleAuthCancel = () => {
    setShowAuthModal(false);
    if (currentView !== 'analyzer') setCurrentView('analyzer');
  };

  const handleDataUpdate = (updates: Partial<ConstructionOrderData>) => {
    if (extractedData) {
      setExtractedData(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') {
      setError("Format invalide. Veuillez uploader un PDF.");
      setStatus(AppStatus.ERROR);
      return;
    }

    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setMappedClient(null);
    setPotentialClients([]);
    setAutoChantierNumber(null);
    setOriginalFile(file);
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    setIsCalendarVisible(true);

    addLog('info', 'Analyse du document démarrée...');

    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);

      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      setIsSidebarOpen(false); 
      setIsHeaderVisible(false);
      addLog('success', 'Extraction IA terminée avec succès.', { client: data.nom_client });
    } catch (err: any) {
      console.error("Analyse échouée:", err);
      let msg = err.message || "Une erreur inconnue est survenue.";
      if (msg.includes("429") || msg.toLowerCase().includes("quota")) msg = "Quota dépassé. Veuillez patienter.";
      setError(msg);
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${msg}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setPotentialClients([]);
    setAutoChantierNumber(null);
    setError(null);
    setOriginalFile(null);
    setSelectedPoseurId("");
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    setIsSidebarOpen(true);
    setIsHeaderVisible(true);
    setIsCalendarVisible(true);
  };

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-slate-600 font-bold">Connexion à la Base de Données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans overflow-x-hidden relative">
      {isPdfModalOpen && filePreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white w-full h-full max-w-6xl rounded-2xl shadow-2xl overflow-hidden flex flex-col relative">
              <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between shrink-0">
                  <span className="font-bold text-sm uppercase tracking-wider"><i className="fas fa-file-pdf mr-2"></i> Aperçu Document (Mode Copie)</span>
                  <button onClick={() => setIsPdfModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-700 transition-colors"><i className="fas fa-times"></i></button>
              </div>
              <div className="flex-grow bg-slate-200">
                  <iframe src={`${filePreviewUrl}#toolbar=0&navpanes=0`} className="w-full h-full" title="PDF Fullscreen"></iframe>
              </div>
           </div>
        </div>
      )}

      {!isHeaderVisible && (
         <button onClick={() => setIsHeaderVisible(true)} className="absolute top-2 right-4 z-50 bg-slate-800 text-slate-400 hover:text-white p-2 rounded-b-lg shadow-md text-xs font-bold transition-all opacity-50 hover:opacity-100"><i className="fas fa-chevron-down"></i> Menu</button>
      )}

      {isHeaderVisible && <Header currentView={currentView} onViewChange={handleViewChange} />}
      {showAuthModal && <AdminAuth onAuthenticated={handleAuthSuccess} onCancel={handleAuthCancel} />}

      <main className={`flex-grow container mx-auto px-4 py-8 max-w-[98%] transition-all ${!isHeaderVisible ? 'pt-4' : ''}`}>
        <div className="mx-auto">
          {currentView === 'admin' && <AdminDashboard />}
          {currentView === 'analyzer' && (
            <div className="flex flex-col lg:flex-row gap-6 transition-all duration-300">
              <div className={`${isSidebarOpen ? 'lg:w-[350px] shrink-0' : 'w-0 overflow-hidden'} transition-all duration-300`}>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-24">
                   <div className="flex justify-between items-center mb-4">
                      <h2 className="text-xl font-black flex items-center gap-2 uppercase tracking-tight"><i className="fas fa-file-pdf text-blue-600"></i> Scan PDF</h2>
                      <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fas fa-times"></i></button>
                   </div>
                  <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />
                  {filePreviewUrl && (
                    <div className="mt-6 animate-in fade-in zoom-in-95 duration-300 group">
                      <div className="flex justify-between items-center mb-2">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Aperçu</p>
                      </div>
                      <div onDoubleClick={handlePdfDoubleClick} className="relative border border-slate-200 rounded-xl overflow-hidden bg-slate-100 min-h-[500px] flex items-center justify-center shadow-inner cursor-zoom-in hover:ring-2 hover:ring-blue-400 transition-all"><iframe src={`${filePreviewUrl}#toolbar=0`} title="PDF Preview" className="w-full h-[500px] border-none pointer-events-none" /></div>
                    </div>
                  )}
                </div>
              </div>

              {!isSidebarOpen && (
                 <div className="absolute left-4 top-24 z-40"><button onClick={() => setIsSidebarOpen(true)} className="bg-blue-600 text-white p-3 rounded-full shadow-lg hover:bg-blue-700 transition-colors"><i className="fas fa-file-pdf"></i></button></div>
              )}

              <div className="flex-grow flex flex-col gap-6 min-w-0">
                {status === AppStatus.IDLE && (
                  <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl shadow-blue-900/20 mx-auto max-w-2xl mt-10">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto mb-6 backdrop-blur-sm"><i className="fas fa-robot text-4xl"></i></div>
                    <h3 className="text-2xl font-black mb-2 uppercase tracking-tight">Analyseur BuildScan</h3>
                    <p className="text-blue-100 font-medium">Glissez un PDF pour extraire les données chantiers vers l'ERP et l'Agenda.</p>
                  </div>
                )}

                {status === AppStatus.ANALYZING && (
                  <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center shadow-sm mx-auto max-w-2xl mt-10">
                    <div className="relative animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4 shadow-lg"></div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Extraction en cours...</h3>
                  </div>
                )}

                {status === AppStatus.ERROR && (
                  <div className="bg-red-50 border-2 border-red-100 rounded-2xl p-8 animate-in shake duration-500 mx-auto max-w-2xl mt-10">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0"><i className="fas fa-exclamation-triangle text-xl"></i></div>
                      <div className="flex-grow">
                        <h3 className="text-lg font-black text-red-800 uppercase tracking-tight">Échec de l'IA</h3>
                        <p className="text-red-700 mt-1 font-medium italic">{error}</p>
                        <button onClick={reset} className="mt-4 bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg shadow-red-200">Réessayer</button>
                      </div>
                    </div>
                  </div>
                )}

                {extractedData && (
                  <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-6">
                    <div className="grid grid-cols-1 xl:grid-cols-2 gap-6 items-start">
                        <div className={`transition-all duration-300 ${isCalendarVisible ? '' : 'xl:col-span-2'}`}>
                          <ResultCard 
                              data={extractedData} 
                              onReset={reset} 
                              mappedClient={mappedClient}
                              potentialClients={potentialClients}
                              onClientMatchUpdate={handleClientUpdate}
                              chantierNumber={autoChantierNumber}
                              isFetchingChantier={isFetchingChantier}
                              onUpdate={handleDataUpdate}
                              poseurs={allPoseurs}
                              selectedPoseurId={selectedPoseurId}
                              onPoseurSelect={setSelectedPoseurId}
                              onTransmit={handleTransmit}
                              isTransmitting={transmitting}
                              transmitStatus={transmitStatus}
                              tentativeEvent={tentativeEvent}
                              isRdvSaved={isRdvSaved}
                              onValidateRdv={handleSaveRdv}
                              isCalendarVisible={isCalendarVisible}
                              onToggleCalendar={() => setIsCalendarVisible(!isCalendarVisible)}
                          />
                        </div>
                        {isCalendarVisible && (
                          <div className="h-full min-h-[600px] animate-in fade-in slide-in-from-right-4 duration-300">
                              <CalendarManager 
                                  poseurs={allPoseurs}
                                  selectedPoseurId={selectedPoseurId}
                                  data={extractedData}
                                  onAddLog={addLog}
                                  chantierNumber={autoChantierNumber}
                                  originalFile={originalFile}
                                  onUpdate={handleDataUpdate}
                                  onTentativeChange={setTentativeEvent}
                                  onRdvStatusChange={setIsRdvSaved}
                                  refreshTrigger={calendarRefreshTrigger}
                                  onClose={() => setIsCalendarVisible(false)}
                              />
                          </div>
                        )}
                    </div>
                    <SqlExporter data={extractedData} mappedClient={mappedClient} prefilledChantierNumber={autoChantierNumber} logs={logs} onAddLog={addLog} onClearLogs={clearLogs} />
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center"><span className="text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.7 • Nextcloud Ed.</span></div>
      </footer>
    </div>
  );
};

