                   <div className="px-4 py-2 rounded-xl bg-white border border-emerald-200 text-emerald-700 font-bold text-xs flex items-center gap-2 shadow-sm">
                      <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
                      RDV Enregistré
                   </div>
               )}

               <button 
                  disabled={isTransmitting || transmitStatus === 'success'}
                  onClick={onTransmit}
                  className={`px-6 py-3 rounded-xl font-bold text-sm transition-all flex items-center gap-2 shadow-lg hover:-translate-y-0.5 ${
                    transmitStatus === 'success' ? 'bg-green-600 text-white' : 
                    transmitStatus === 'error' ? 'bg-red-600 text-white' :
                    'bg-slate-800 text-white hover:bg-slate-700 shadow-slate-900/20'
                  }`}
                >
                  {isTransmitting ? (
                      <><i className="fas fa-spinner fa-spin"></i> Envoi...</>
                  ) : transmitStatus === 'success' ? (
                      <><i className="fas fa-check"></i> Envoyé</>
                  ) : (
                      <><i className="fas fa-paper-plane text-lg"></i> Transmettre</>
                  )}
                </button>
            </div>
          </div>

          <div className="grid grid-cols-2 lg:grid-cols-5 gap-4 border-t border-emerald-200 pt-3">
             <div>
                <p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Numéro Affaire</p>
                {isFetchingChantier ? (
                   <div className="flex items-center gap-2 text-emerald-600 text-xs font-bold animate-pulse">
                     <i className="fas fa-circle-notch fa-spin"></i> ...
                   </div>
                ) : chantierNumber ? (
                  <div className="flex items-center gap-2">
                     <span className="font-mono font-black text-slate-800 text-lg tracking-wide bg-white border border-emerald-300 px-2 rounded shadow-sm">
                       {chantierNumber}
                     </span>
                  </div>
                ) : (
                   <span className="text-[10px] text-emerald-500 italic">N/A</span>
                )}
             </div>

             <div>
                <p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Catégorie</p>
                <div className="relative">
                    <select
                        value={data.categorie || ""}
                        onChange={(e) => handleInputChange('categorie', e.target.value)}
                        className="w-full font-bold text-slate-800 text-sm tracking-wide bg-white border border-emerald-300 px-2 py-1.5 rounded shadow-sm outline-none focus:ring-2 focus:ring-emerald-500 appearance-none cursor-pointer"
                    >
                        <option value="">-- Sélection --</option>
                        {categories.map(cat => (
                            <option key={cat.code} value={cat.code}>
                                {cat.label}
                            </option>
                        ))}
                    </select>
                    <i className="fas fa-chevron-down absolute right-2 top-2.5 text-emerald-500 text-xs pointer-events-none"></i>
                </div>
             </div>

             <div>
                 <p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Assignation Poseur</p>
                 <div className="relative">
                    <select
                        value={selectedPoseurId}
                        onChange={(e) => onPoseurSelect(e.target.value)}
                        className="w-full font-bold text-slate-800 text-sm tracking-wide bg-white border border-emerald-300 px-2 py-1.5 rounded shadow-sm outline-none focus:ring-2 focus:ring-emerald-500 appearance-none cursor-pointer"
                    >
                        <option value="">-- Non assigné --</option>
                        {poseurs.map(p => (
                        <option key={p.id} value={p.id}>
                            {p.nom} {p.type ? `[${p.type}]` : ''}
                        </option>
                        ))}
                    </select>
                    <i className="fas fa-chevron-down absolute right-2 top-2.5 text-emerald-500 text-xs pointer-events-none"></i>
                 </div>
             </div>

             <div>
                <p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Code BPU</p>
                <div className="bg-white border border-emerald-300 rounded px-2 py-1.5 inline-block w-full">
                  <span className="font-mono font-black text-slate-700 text-sm">{mappedClient.bpu || '-'}</span>
                </div>
             </div>

             <div>
                <p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Compte Client</p>
                <div className="relative">
                    <select
                        value={mappedClient.id}
                        onChange={(e) => onClientMatchUpdate?.(e.target.value)}
                        className="w-full font-bold text-slate-800 text-sm tracking-wide bg-white border border-emerald-300 px-2 py-1.5 rounded shadow-sm outline-none focus:ring-2 focus:ring-emerald-500 appearance-none cursor-pointer"
                    >
                        {potentialClients.map(c => (
                            <option key={c.id} value={c.id}>
                                {c.typeAffaire || 'Std'} - {c.libelle_client || c.nom}
                            </option>
                        ))}
                    </select>
                    <i className="fas fa-chevron-down absolute right-2 top-2.5 text-emerald-500 text-xs pointer-events-none"></i>
                </div>
             </div>
          </div>
        </div>
      ) : (
        <div className="mx-6 mt-6 bg-slate-50 border border-slate-200 border-dashed rounded-lg p-4 flex items-center gap-3">
          <i className="fas fa-exclamation-circle text-slate-400"></i>
          <p className="text-xs text-slate-500 font-medium">
            Aucun mapping client trouvé pour "<span className="font-bold">{data.nom_client || 'Inconnu'}</span>". 
            Rendez-vous dans l'onglet <span className="font-bold underline">Clients</span> pour l'ajouter.
          </p>
        </div>
      )}

      <div className="mx-6 mt-6 p-4 bg-blue-50/50 border border-blue-100 rounded-xl focus-within:ring-2 focus-within:ring-blue-200 transition-all">
        <div className="flex items-center gap-2 mb-2">
          <i className="fas fa-tools text-blue-500 text-xs"></i>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Descriptif des Travaux</span>
        </div>
        <textarea
          value={data.descriptif_travaux || ""}
          onChange={(e) => handleInputChange('descriptif_travaux', e.target.value)}
          rows={4}
          className="w-full bg-white border border-blue-100 rounded-lg p-3 text-sm font-semibold text-slate-800 leading-relaxed focus:outline-none focus:border-blue-400 resize-y shadow-inner"
          placeholder="Saisissez le descriptif des travaux..."
        />
      </div>

      <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-1 md:col-span-2">
          <div className="flex items-center gap-2 mb-1">
            <i className="fas fa-map-marker-alt text-red-600 w-4"></i>
            <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Adresse d'intervention (3 Lignes)</span>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {[
              { key: 'adresse_1', label: 'Ligne 1' },
              { key: 'adresse_2', label: 'Ligne 2' },
              { key: 'adresse_3', label: 'Ligne 3' }
            ].map((addr) => (
              <div key={addr.key} className="p-3 rounded-lg border border-slate-100 bg-slate-50/50 flex flex-col focus-within:bg-white focus-within:border-blue-200 focus-within:ring-1 focus-within:ring-blue-200 transition-all">
                <span className="text-[9px] text-slate-400 font-bold uppercase mb-1">{addr.label}</span>
                <input
                  type="text"
                  value={(data as any)[addr.key] || ""}
                  onChange={(e) => handleInputChange(addr.key as keyof ConstructionOrderData, e.target.value)}
                  className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0 placeholder:text-slate-300 w-full"
                  placeholder="-"
                />
              </div>
            ))}
          </div>
        </div>

        <div className="space-y-1 md:col-span-2">
           <div className="flex items-center gap-2 mb-1">
              <i className="fas fa-user-tie text-emerald-600 w-4"></i>
              <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">Contact / Gardien / Locataire</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <div className="p-3 rounded-lg border border-slate-100 bg-slate-50/50 flex flex-col relative overflow-hidden focus-within:bg-white focus-within:border-emerald-200 focus-within:ring-1 focus-within:ring-emerald-200 transition-all">
                   <span className="text-[9px] text-slate-400 font-bold uppercase mb-1">Nom</span>
                   <input
                     type="text"
                     value={data.gardien_nom || ""}
                     onChange={(e) => handleInputChange('gardien_nom', e.target.value)}
                     className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0 placeholder:text-slate-300 w-full"
                     placeholder="-"
                   />
                </div>
                <div className="p-3 rounded-lg border border-slate-100 bg-slate-50/50 flex flex-col relative overflow-hidden focus-within:bg-white focus-within:border-emerald-200 focus-within:ring-1 focus-within:ring-emerald-200 transition-all">
                   <span className="text-[9px] text-slate-400 font-bold uppercase mb-1">Téléphone</span>
                   <input
                     type="text"
                     value={data.gardien_tel || ""}
                     onChange={(e) => handleInputChange('gardien_tel', e.target.value)}
                     className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0 placeholder:text-slate-300 w-full"
                     placeholder="-"
                   />
                   <i className="fas fa-phone absolute right-3 top-3 text-emerald-100 pointer-events-none"></i>
                </div>
                <div className="p-3 rounded-lg border border-slate-100 bg-slate-50/50 flex flex-col relative overflow-hidden focus-within:bg-white focus-within:border-emerald-200 focus-within:ring-1 focus-within:ring-emerald-200 transition-all">
                   <span className="text-[9px] text-slate-400 font-bold uppercase mb-1">Email</span>
                   <input
                     type="text"
                     value={data.gardien_email || ""}
                     onChange={(e) => handleInputChange('gardien_email', e.target.value)}
                     className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0 placeholder:text-slate-300 w-full"
                     placeholder="-"
                   />
                   <i className="fas fa-envelope absolute right-3 top-3 text-blue-100 pointer-events-none"></i>
                </div>
            </div>
        </div>

        {fields.map((field) => (
          <div key={field.key} className="space-y-1">
            <div className="flex items-center gap-2 mb-1">
              <i className={`fas ${field.icon} ${field.color} w-4`}></i>
              <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                 {field.label}
              </span>
            </div>
            <div className={`p-3 rounded-lg border border-slate-100 bg-slate-50/50 min-h-[44px] flex items-center transition-all focus-within:bg-white focus-within:border-blue-400 focus-within:ring-1 focus-within:ring-blue-100 border-l-4 ${mappedClient && field.key === 'nom_client' ? 'border-l-emerald-400' : 'border-l-slate-200'}`}>
              <div className="w-full">
                <input
                    type="text"
                    value={(data as any)[field.key] || ""}
                    onChange={(e) => handleInputChange(field.key as keyof ConstructionOrderData, e.target.value)}
                    className="bg-transparent border-none p-0 w-full font-bold text-slate-900 focus:ring-0 placeholder:text-slate-300 placeholder:italic"
                    placeholder="Non renseigné"
                />
                {field.key === 'nom_client' && rawPdfClientName && mappedClient && (
                    <div className="text-[9px] text-slate-400 mt-0.5 font-bold uppercase flex items-center gap-1">
                        <i className="fas fa-file-pdf"></i> PDF Original : {rawPdfClientName}
                    </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="bg-blue-50 px-6 py-3 flex items-start gap-3 border-t border-blue-100 mt-auto">
        <i className="fas fa-shield-alt text-blue-500 mt-1"></i>
        <p className="text-[10px] text-blue-700 leading-relaxed font-bold uppercase tracking-tight">
          Protection des données : Les informations financières (Prix, TVA) ont été exclues du scan conformément au protocole de sécurité.
        </p>
      </div>
    </div>
  );
};

export default ResultCard;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AppStatus, ConstructionOrderData, AppView, Client, Poseur, LogEntry, CalendarEvent } from './types';
import { analyzeConstructionDocument } from './services/geminiService';
import { fetchStorageConfig } from './services/configService';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ResultCard from './components/ResultCard';
import SqlExporter from './components/SqlExporter';
import CalendarManager from './components/CalendarManager';
import AdminDashboard from './components/AdminDashboard';
import AdminAuth from './components/AdminAuth';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('analyzer');
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreviewUrl, setFilePreviewUrl] = useState<string | null>(null);
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Layout State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const [isCalendarVisible, setIsCalendarVisible] = useState(true);
  const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);

  // Terminal Logs State (Shared)
  const [logs, setLogs] = useState<LogEntry[]>([]);

  // Data enrichment states
  const [mappedClient, setMappedClient] = useState<Client | null>(null);
  const [potentialClients, setPotentialClients] = useState<Client[]>([]); 
  const [autoChantierNumber, setAutoChantierNumber] = useState<string | null>(null);
  const [isFetchingChantier, setIsFetchingChantier] = useState(false);

  // On garde une référence du nom original extrait du PDF pour la recherche
  const rawExtractedNameRef = useRef<string | null>(null);

  // Trigger pour forcer le re-calcul du mapping (Client/Poseur) au changement de vue
  const [refreshDataTrigger, setRefreshDataTrigger] = useState(0);

  // Calendar & Poseur sync state
  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");
  const [allPoseurs, setAllPoseurs] = useState<Poseur[]>([]);
  const [tentativeEvent, setTentativeEvent] = useState<CalendarEvent | null>(null);
  const [isRdvSaved, setIsRdvSaved] = useState(false);
  const [calendarRefreshTrigger, setCalendarRefreshTrigger] = useState(0);

  // Transmission State
  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      console.log('🚀 Initialisation BuildScan AI...');
      const config = await fetchStorageConfig();
      if (config) {
        setAllPoseurs(config.poseurs);
      }
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => {
      if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    };
  }, [filePreviewUrl]);

  // --- SHARED LOGGING FUNCTION ---
  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  // --- AUTOMATISATION LOGIQUE METIER ---

  // 1. Détection automatique du Client (Gestion Multi-Affaires)
  useEffect(() => {
    const nameToSearch = rawExtractedNameRef.current || extractedData?.nom_client;

    if (!nameToSearch) {
      setMappedClient(null);
      setPotentialClients([]);
      return;
    }

    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;

    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = nameToSearch.toLowerCase().trim();

      const matches = clients.filter(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || 
               searchName.includes(clientRefNom) || 
               clientRefNom.includes(searchName);
      });

      setPotentialClients(matches);

      if (matches.length > 0) {
          const isCurrentStillValid = mappedClient && matches.some(m => m.id === mappedClient.id);
          if (!isCurrentStillValid) {
            setMappedClient(matches[0]);
          }
      } else {
        setMappedClient(null);
      }

    } catch (e) {
      console.error("Erreur parsing clients", e);
    }
  }, [extractedData?.nom_client, refreshDataTrigger]);

  useEffect(() => {
    if (mappedClient && extractedData) {
        const targetLibelle = mappedClient.libelle_client || mappedClient.nom;
        if (extractedData.nom_client !== targetLibelle) {
            setExtractedData(prev => prev ? ({ ...prev, nom_client: targetLibelle }) : null);
            addLog('info', `Client mappé : ${targetLibelle}`);
        }
    }
  }, [mappedClient, addLog]);

  // 2. Assignation automatique du Poseur selon le Client sélectionné
  useEffect(() => {
    if (!mappedClient) return;

    let assignedPoseur: Poseur | undefined;
    let method = '';

    if (mappedClient.default_poseur && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.id === mappedClient.default_poseur);
        method = 'Lien Client';
    } 

    if (!assignedPoseur && mappedClient.typeAffaire && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.type === mappedClient.typeAffaire);
        method = 'Type Affaire';
    }

    if (assignedPoseur) {
        setSelectedPoseurId(assignedPoseur.id);
        addLog('info', `Poseur assigné (${method}) : ${assignedPoseur.nom}`);
    }
  }, [mappedClient, allPoseurs, addLog]);

  // 3. Récupération automatique du numéro d'affaire via Webhook
  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) {
        setAutoChantierNumber(null);
        return;
      }

      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;

      setIsFetchingChantier(true);
      setAutoChantierNumber(null); 

      try {
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.libelle_client || mappedClient.nom
          })
        });

        if (response.ok) {
          const result = await response.json();
          let newNumber = "";

          if (result.numero_affaire) newNumber = result.numero_affaire;
          else if (result.next_id) newNumber = result.next_id;
          else if (result.value) newNumber = result.value;
          else if (typeof result === 'string') newNumber = result;
          else if (typeof result === 'number') newNumber = String(result);

          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            addLog('response', `Numéro d'affaire récupéré : ${formattedNumber}`);
          }
        }
      } catch (e) {
        console.error("Erreur Webhook Auto:", e);
        addLog('error', `Échec récupération numéro d'affaire.`);
      } finally {
        setIsFetchingChantier(false);
      }
    };

    fetchChantier();
  }, [mappedClient, addLog]);

  // --- HANDLERS ---
  const handleClientUpdate = (clientId: string) => {
      const selected = potentialClients.find(c => c.id === clientId);
      if (selected) {
          setMappedClient(selected);
          addLog('info', `Changement de compte : ${selected.libelle_client || selected.nom} (${selected.typeAffaire})`);
      }
  };

  const handleSaveRdv = async () => {
      if (!tentativeEvent || !selectedPoseurId) return;

      addLog('request', `Validation RDV le ${new Date(tentativeEvent.start).toLocaleString()}...`);

      try {
          let fileData = null;
          let fileName = null;

          if (originalFile) {
              fileName = originalFile.name;
              fileData = await new Promise<string>((resolve, reject) => {
                  const reader = new FileReader();
                  reader.onload = () => resolve((reader.result as string).split(',')[1]); 
                  reader.onerror = reject;
                  reader.readAsDataURL(originalFile);
              });
          }

          const res = await fetch('/api/calendar/event/save', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                  poseur_id: selectedPoseurId,
                  event: tentativeEvent,
                  file: fileData ? { name: fileName, data: fileData } : undefined
              })
          });

          const result = await res.json();

          if (res.ok && result.success) {
              addLog('success', `RDV validé et enregistré dans Nextcloud.`);
              setIsRdvSaved(true);
              setTentativeEvent(null);
              setCalendarRefreshTrigger(prev => prev + 1);
          } else {
              throw new Error(result.error || "Erreur enregistrement");
          }

      } catch (e: any) {
          addLog('error', `Echec validation RDV: ${e.message}`);
          alert("Erreur lors de la validation du RDV: " + e.message);
      }
  };


  const handleTransmit = async () => {
      if (!extractedData) return;

      setTransmitting(true);
      setTransmitStatus('idle');
      const webhookUrl = localStorage.getItem('buildscan_webhook_url') || "";

      if (!webhookUrl) {
          addLog('error', 'URL Webhook manquante. Vérifiez les paramètres Admin.');
          setTransmitStatus('error');
          setTransmitting(false);
          return;
      }

      const chantier = autoChantierNumber || (extractedData.num_bon_travaux ? extractedData.num_bon_travaux.replace(/\D/g, '').substring(0, 6) : "000000");
      const imputation = `80${chantier}0`;

      // Préparation des adresses et contacts concaténés
      const fullAddress = [extractedData.adresse_1, extractedData.adresse_2, extractedData.adresse_3].filter(Boolean).join(' ');
      const contactFull = [extractedData.gardien_nom, extractedData.gardien_tel].filter(Boolean).join(' - ');

      const selectedPoseur = allPoseurs.find(p => p.id === selectedPoseurId);
      const finalClientLabel = mappedClient?.libelle_client || mappedClient?.nom || extractedData.nom_client || '';

      const formData = new FormData();
      if (originalFile) formData.append('file', originalFile, originalFile.name || 'document.pdf');

      // INFOS CLIENT (MAPPING ERP)
      formData.append('codeClient', mappedClient?.codeClient || '');
      formData.append('code_trv', mappedClient?.typeAffaire || 'O3-0');

      // RÈGLE : BPU = véritable code BPU du client (Transmis à n8n)
      formData.append('client_bpu', mappedClient?.bpu || '');
      formData.append('bpu', mappedClient?.bpu || ''); // Double envoi pour sécurité clé n8n
      formData.append('client_nom', finalClientLabel);

      // INFOS CHANTIER
      formData.append('num_chantier', chantier);
      formData.append('imputation', imputation);
      formData.append('num_bon_travaux', extractedData.num_bon_travaux || '');
      formData.append('nom_client_pdf', rawExtractedNameRef.current || extractedData.nom_client || '');
      formData.append('categorie', extractedData.categorie || ''); 

      // --- AJOUT DES CHAMPS SÉPARÉS (REQUIS PAR N8N) ---
      formData.append('adresse_1', extractedData.adresse_1 || '');
      formData.append('adresse_2', extractedData.adresse_2 || '');
      formData.append('adresse_3', extractedData.adresse_3 || '');
      formData.append('adresse_intervention', fullAddress); // Version concaténée

      formData.append('gardien_nom', extractedData.gardien_nom || '');
      formData.append('gardien_tel', extractedData.gardien_tel || '');
      formData.append('gardien_email', extractedData.gardien_email || '');
      formData.append('coord_gardien', contactFull); // Version concaténée
      // ------------------------------------------------

      formData.append('delai_intervention', extractedData.delai_intervention || '');
      formData.append('date_intervention', extractedData.date_intervention || '');
      formData.append('descriptif_travaux', extractedData.descriptif_travaux || '');

      // METADATA
      formData.append('source', "BuildScan AI");
      formData.append('timestamp', new Date().toISOString());

      if (selectedPoseur) {
        formData.append('poseur_id', selectedPoseur.id);
        formData.append('poseur_nom', selectedPoseur.nom);
        formData.append('poseur_code', selectedPoseur.codeSalarie || '');
        formData.append('poseur_type', selectedPoseur.type || '');
      }

      addLog('request', `Envoi complet vers n8n...`, { 
        imputation, 
        client: finalClientLabel,
        bpu: mappedClient?.bpu,
        categorie: extractedData.categorie
      });

      try {
        const response = await fetch(webhookUrl, {
          method: 'POST',
          body: formData
        });
        const result = await response.json().catch(() => ({}));

        if (response.ok && (result.success !== false)) {
          setTransmitStatus('success');
          addLog('success', `Transmission réussie à n8n.`, result);
        } else {
          throw new Error(result.message || `Erreur n8n : ${response.status}`);
        }
      } catch (err: any) {
        setTransmitStatus('error');
        addLog('error', `Échec transmission: ${err.message}`);
      } finally {
        setTransmitting(false);
      }
  };

  const handlePdfDoubleClick = () => {
    setIsPdfModalOpen(true);
    setIsCalendarVisible(false);
  };

  const handleViewChange = async (view: AppView) => {
    if (view === 'analyzer') {
      const config = await fetchStorageConfig();
      if (config) setAllPoseurs(config.poseurs);
      setRefreshDataTrigger(prev => prev + 1);
      setCurrentView('analyzer');
      return;
    }

    if (view === 'admin') {
      if (isAuthenticated) setCurrentView('admin');
      else setShowAuthModal(true);
    }
  };

  const handleAuthSuccess = () => {
    setIsAuthenticated(true);
    setShowAuthModal(false);
    setCurrentView('admin');
  };

  const handleAuthCancel = () => {
    setShowAuthModal(false);
    if (currentView !== 'analyzer') setCurrentView('analyzer');
  };

  const handleDataUpdate = (updates: Partial<ConstructionOrderData>) => {
    if (extractedData) {
      setExtractedData(prev => prev ? ({ ...prev, ...updates }) : null);
    }
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') {
      setError("Format invalide. Veuillez uploader un PDF.");
      setStatus(AppStatus.ERROR);
      return;
    }

    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setMappedClient(null);
    setPotentialClients([]);
    setAutoChantierNumber(null);
    setOriginalFile(file);
    rawExtractedNameRef.current = null;
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);

    setIsCalendarVisible(false);
    setIsSidebarOpen(false); 

    setTransmitStatus('idle');
    setTransmitting(false);

    addLog('info', 'Analyse du document démarrée...');

    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);

      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = reject;
        reader.readAsDataURL(file);
      });

      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);

      rawExtractedNameRef.current = data.nom_client;

      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      setIsHeaderVisible(false);
      setIsCalendarVisible(false);
      addLog('success', 'Extraction IA terminée.', { pdf_client: data.nom_client });
    } catch (err: any) {
      console.error("Analyse échouée:", err);
      let msg = err.message || "Une erreur inconnue est survenue.";
      if (msg.includes("429") || msg.toLowerCase().includes("quota")) msg = "Quota dépassé. Veuillez patienter.";
      setError(msg);
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${msg}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setPotentialClients([]);
    setAutoChantierNumber(null);
    rawExtractedNameRef.current = null;
    setError(null);
    setOriginalFile(null);
    setSelectedPoseurId("");
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
    setTentativeEvent(null);
    setIsRdvSaved(false);
    setIsSidebarOpen(true);
    setIsHeaderVisible(true);
    setIsCalendarVisible(true);

    setTransmitStatus('idle');
    setTransmitting(false);
  };

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4"></div>
          <p className="text-slate-600 font-bold">Connexion à la Base de Données...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans overflow-x-hidden relative">
      {isPdfModalOpen && filePreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4 animate-in fade-in duration-200">
           <div className="bg-white w-full h-full max-w-6xl rounded-2xl shadow-2xl overflow-hidden flex flex-col relative">
              <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between shrink-0">
                  <span className="font-bold text-sm uppercase tracking-wider"><i className="fas fa-file-pdf mr-2"></i> Aperçu Document (Mode Copie)</span>
                  <button onClick={() => setIsPdfModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-700 transition-colors"><i className="fas fa-times"></i></button>
              </div>
              <div className="flex-grow bg-slate-200">
                  <iframe src={`${filePreviewUrl}#toolbar=0&navpanes=0`} className="w-full h-full" title="PDF Fullscreen"></iframe>
              </div>
           </div>
        </div>
      )}

      {!isHeaderVisible && (
         <button onClick={() => setIsHeaderVisible(true)} className="absolute top-2 right-4 z-50 bg-slate-800 text-slate-400 hover:text-white p-2 rounded-b-lg shadow-md text-xs font-bold transition-all opacity-50 hover:opacity-100"><i className="fas fa-chevron-down"></i> Menu</button>
      )}

      {isHeaderVisible && <Header currentView={currentView} onViewChange={handleViewChange} />}
      {showAuthModal && <AdminAuth onAuthenticated={handleAuthSuccess} onCancel={handleAuthCancel} />}

      <main className={`flex-grow container mx-auto px-4 py-8 max-w-[98%] transition-all ${!isHeaderVisible ? 'pt-4' : ''}`}>
        <div className="mx-auto">
          {currentView === 'admin' && <AdminDashboard />}
          {currentView === 'analyzer' && (
            <div className="flex flex-col lg:flex-row gap-6 transition-all duration-300">
              <div className={`${isSidebarOpen ? 'lg:w-[350px] shrink-0' : 'w-0 overflow-hidden'} transition-all duration-300`}>
                <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-24">
                   <div className="flex justify-between items-center mb-4">
                      <h2 className="text-xl font-black flex items-center gap-2 uppercase tracking-tight"><i className="fas fa-file-pdf text-blue-600"></i> Scan PDF</h2>
                      <button onClick={() => setIsSidebarOpen(false)} className="lg:hidden text-slate-400"><i className="fas fa-times"></i></button>
                   </div>
                  <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />
                  {filePreviewUrl && (
                    <div className="mt-6 animate-in fade-in zoom-in-95 duration-300 group">
                      <div className="flex justify-between items-center mb-2">
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Aperçu</p>
                      </div>
                      <div className="relative border border-slate-200 rounded-xl overflow-hidden bg-slate-100 min-h-[500px] flex items-center justify-center shadow-inner hover:ring-2 hover:ring-blue-400 transition-all">
                        <iframe src={`${filePreviewUrl}#toolbar=0`} title="PDF Preview" className="w-full h-[500px] border-none" />
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {!isSidebarOpen && status !== AppStatus.SUCCESS && (
                 <div className="absolute left-4 top-24 z-40"><button onClick={() => setIsSidebarOpen(true)} className="bg-blue-600 text-white p-3 rounded-full shadow-lg hover:bg-blue-700 transition-colors"><i className="fas fa-file-pdf"></i></button></div>
              )}

              <div className="flex-grow flex flex-col gap-6 min-w-0">
                {status === AppStatus.IDLE && (
                  <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl shadow-blue-900/20 mx-auto max-w-2xl mt-10">
                    <div className="w-20 h-20 bg-white/10 rounded-3xl flex items-center justify-center mx-auto mb-6 backdrop-blur-sm"><i className="fas fa-robot text-4xl"></i></div>
                    <h3 className="text-2xl font-black mb-2 uppercase tracking-tight">Analyseur BuildScan</h3>
                    <p className="text-blue-100 font-medium">Glissez un PDF pour extraire les données chantiers vers l'ERP et l'Agenda.</p>
                  </div>
                )}

                {status === AppStatus.ANALYZING && (
                  <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center shadow-sm mx-auto max-w-2xl mt-10">
                    <div className="relative animate-spin rounded-full h-16 w-16 border-4 border-blue-600 border-t-transparent mx-auto mb-4 shadow-lg"></div>
                    <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tighter">Extraction en cours...</h3>
                  </div>
                )}

                {status === AppStatus.ERROR && (
                  <div className="bg-red-50 border-2 border-red-100 rounded-2xl p-8 animate-in shake duration-500 mx-auto max-w-2xl mt-10">
                    <div className="flex items-start gap-4">
                      <div className="w-12 h-12 bg-red-100 text-red-600 rounded-xl flex items-center justify-center shrink-0"><i className="fas fa-exclamation-triangle text-xl"></i></div>
                      <div className="flex-grow">
                        <h3 className="text-lg font-black text-red-800 uppercase tracking-tight">Échec de l'IA</h3>
                        <p className="text-red-700 mt-1 font-medium italic">{error}</p>
                        <button onClick={reset} className="mt-4 bg-red-600 text-white px-6 py-2 rounded-lg font-bold text-xs uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg shadow-red-200">Réessayer</button>
                      </div>
                    </div>
                  </div>
                )}

                {extractedData && (
                  <div className="animate-in fade-in slide-in-from-bottom-6 duration-500 space-y-6">
                    <div className={`grid gap-6 items-start ${isCalendarVisible ? 'grid-cols-1 xl:grid-cols-3' : 'grid-cols-1 xl:grid-cols-2'}`}>
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[850px] animate-in slide-in-from-left-4 duration-500">
                          <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between shrink-0">
                            <span className="text-[10px] font-black uppercase tracking-widest"><i className="fas fa-file-pdf mr-2"></i> Document Source</span>
                            <div className="flex items-center gap-2">
                               <button onClick={handlePdfDoubleClick} className="text-[10px] bg-slate-700 hover:bg-slate-600 px-2 py-1 rounded font-bold uppercase transition-colors">Plein Écran</button>
                            </div>
                          </div>
                          <div className="flex-grow bg-slate-100 relative">
                             <iframe 
                               src={`${filePreviewUrl}#navpanes=0&scrollbar=1`} 
                               className="w-full h-full border-none" 
                               title="PDF View Interactive"
                             />
                          </div>
                        </div>

                        <div className="h-full">
                          <ResultCard 
                              data={extractedData} 
                              onReset={reset} 
                              mappedClient={mappedClient}
                              potentialClients={potentialClients}
                              onClientMatchUpdate={handleClientUpdate}
                              chantierNumber={autoChantierNumber}
                              isFetchingChantier={isFetchingChantier}
                              onUpdate={handleDataUpdate}
                              poseurs={allPoseurs}
                              selectedPoseurId={selectedPoseurId}
                              onPoseurSelect={setSelectedPoseurId}
                              onTransmit={handleTransmit}
                              isTransmitting={transmitting}
                              transmitStatus={transmitStatus}
                              tentativeEvent={tentativeEvent}
                              isRdvSaved={isRdvSaved}
                              onValidateRdv={handleSaveRdv}
                              isCalendarVisible={isCalendarVisible}
                              onToggleCalendar={() => setIsCalendarVisible(!isCalendarVisible)}
                              rawPdfClientName={rawExtractedNameRef.current}
                          />
                        </div>

                        {isCalendarVisible && (
                          <div className="h-[850px] animate-in fade-in slide-in-from-right-4 duration-300">
                              <CalendarManager 
                                  poseurs={allPoseurs}
                                  selectedPoseurId={selectedPoseurId}
                                  data={extractedData}
                                  onAddLog={addLog}
                                  chantierNumber={autoChantierNumber}
                                  originalFile={originalFile}
                                  onUpdate={handleDataUpdate}
                                  onTentativeChange={setTentativeEvent}
                                  onRdvStatusChange={setIsRdvSaved}
                                  refreshTrigger={calendarRefreshTrigger}
                                  onClose={() => setIsCalendarVisible(false)}
                              />
                          </div>
                        )}
                    </div>
                    <SqlExporter data={extractedData} mappedClient={mappedClient} prefilledChantierNumber={autoChantierNumber} logs={logs} onAddLog={addLog} onClearLogs={clearLogs} />
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </main>
      <footer className="bg-white border-t border-slate-200 py-6">
        <div className="container mx-auto px-4 text-center"><span className="text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.7 • Nextcloud Ed.</span></div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Poseur } from '../types';
import { fetchStorageConfig, addPoseur, updatePoseur, deletePoseur } from '../services/configService';

const AdminPoseurs: React.FC = () => {
  const [poseurs, setPoseurs] = useState<Poseur[]>([]);
  const [availableTypes, setAvailableTypes] = useState<string[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const initialForm = { nom: '', entreprise: '', telephone: '', specialite: '', codeSalarie: '', type: '', nextcloud_user: '' };
  const [newPoseur, setNewPoseur] = useState<Omit<Poseur, 'id'>>(initialForm);
  const [editForm, setEditForm] = useState<Omit<Poseur, 'id'>>(initialForm);

  const reloadData = async () => {
    const config = await fetchStorageConfig();
    if (config) {
      setPoseurs(config.poseurs);

      // Extraction des Types Affaire uniques depuis la liste des clients
      const types = Array.from(new Set(config.clients.map(c => c.typeAffaire).filter(Boolean)));
      setAvailableTypes(types.sort());
    }
  };

  useEffect(() => { reloadData(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const result = await addPoseur(newPoseur);
    if (result) {
      setNewPoseur(initialForm);
      setIsAdding(false);
      await reloadData();
    }
    setIsSaving(false);
  };

  const handleUpdate = async (id: string) => {
    setIsSaving(true);
    const success = await updatePoseur(id, editForm);
    if (success) {
      setEditingId(null);
      await reloadData();
    }
    setIsSaving(false);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Supprimer ce poseur ?")) return;
    setIsSaving(true);
    const success = await deletePoseur(id);
    if (success) await reloadData();
    setIsSaving(false);
  };

  const startEditing = (p: Poseur) => {
    setEditingId(p.id);
    setEditForm({ 
      nom: p.nom, 
      entreprise: p.entreprise, 
      telephone: p.telephone, 
      specialite: p.specialite, 
      codeSalarie: p.codeSalarie,
      type: p.type || '',
      nextcloud_user: p.nextcloud_user || ''
    });
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6">
      <div className="flex items-center justify-between bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Gestion Flotte</h2>
          <p className="text-slate-500 text-sm font-medium">Référentiel des salariés et sous-traitants connectés.</p>
        </div>
        <button 
          onClick={() => setIsAdding(!isAdding)} 
          className={`px-6 py-2.5 rounded-xl font-black uppercase tracking-widest text-xs transition-all flex items-center gap-2 shadow-lg ${
            isAdding ? 'bg-slate-200 text-slate-700' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-200'
          }`}
        >
          {isAdding ? 'Annuler' : <><i className="fas fa-plus-circle"></i> Ajouter Salarié</>}
        </button>
      </div>

      {isAdding && (
        <form onSubmit={handleAdd} className="bg-white p-8 rounded-2xl border-2 border-indigo-100 shadow-xl grid grid-cols-1 md:grid-cols-2 gap-5 animate-in slide-in-from-top-4">
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Nom Complet</label>
            <input placeholder="ex: Jean DUPONT" className="w-full p-3 border rounded-xl bg-slate-50 focus:bg-white transition-colors" value={newPoseur.nom} onChange={e => setNewPoseur({...newPoseur, nom: e.target.value})} required />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Entreprise</label>
            <input placeholder="ex: SAMDB" className="w-full p-3 border rounded-xl bg-slate-50 focus:bg-white transition-colors" value={newPoseur.entreprise} onChange={e => setNewPoseur({...newPoseur, entreprise: e.target.value})} />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Téléphone</label>
            <input placeholder="ex: 06 00 00 00 00" className="w-full p-3 border rounded-xl bg-slate-50 focus:bg-white transition-colors" value={newPoseur.telephone} onChange={e => setNewPoseur({...newPoseur, telephone: e.target.value})} />
          </div>
          <div className="space-y-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Code Salarié</label>
            <input placeholder="ex: SAL-123" className="w-full p-3 border rounded-xl bg-slate-50 focus:bg-white transition-colors font-mono" value={newPoseur.codeSalarie} onChange={e => setNewPoseur({...newPoseur, codeSalarie: e.target.value})} />
          </div>

          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Spécialité / Métier</label>
             <input placeholder="ex: Menuiserie / Serrurerie" className="w-full p-3 border rounded-xl bg-slate-50 focus:bg-white transition-colors" value={newPoseur.specialite} onChange={e => setNewPoseur({...newPoseur, specialite: e.target.value})} />
          </div>

          <div className="space-y-1">
             <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Type Affaire ERP (Auto-Mapping)</label>
             <select 
               className="w-full p-3 border rounded-xl bg-slate-50 border-slate-200 text-slate-700 font-bold"
               value={newPoseur.type} 
               onChange={e => setNewPoseur({...newPoseur, type: e.target.value})}
             >
               <option value="">-- Aucun mapping auto --</option>
               {availableTypes.map(type => (
                 <option key={type} value={type}>{type}</option>
               ))}
             </select>
          </div>

           <div className="col-span-2 space-y-1">
             <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest ml-1">Identifiant Nextcloud (Synchronisation Calendrier)</label>
             <div className="relative">
                <i className="fas fa-cloud absolute left-4 top-4 text-sky-400"></i>
                <input placeholder="ex: jean.dupont (doit correspondre au dossier Nextcloud)" className="w-full pl-11 p-3 border-2 border-sky-100 rounded-xl bg-sky-50 focus:bg-white transition-colors font-bold" value={newPoseur.nextcloud_user} onChange={e => setNewPoseur({...newPoseur, nextcloud_user: e.target.value})} />
             </div>
          </div>

          <button type="submit" disabled={isSaving} className="col-span-2 bg-emerald-600 text-white py-4 rounded-xl font-black uppercase tracking-widest hover:bg-emerald-700 shadow-lg shadow-emerald-200 transition-all mt-2">
            {isSaving ? <><i className="fas fa-spinner fa-spin mr-2"></i> Traitement...</> : 'Enregistrer le nouveau salarié'}
          </button>
        </form>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden divide-y-8 divide-slate-50">
        {poseurs.map((p, index) => (
          <div key={p.id} className="group">
            <div className={`p-6 flex flex-col md:flex-row md:items-center justify-between hover:bg-slate-50/80 transition-all gap-6 border-l-4 ${p.type ? 'border-l-indigo-500' : 'border-l-slate-200'}`}>
              {editingId === p.id ? (
                <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-4 bg-slate-50 p-6 rounded-2xl border border-indigo-100 animate-in zoom-in-95">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Nom</label>
                    <input className="w-full border p-2.5 rounded-lg text-sm font-bold" value={editForm.nom} onChange={e => setEditForm({...editForm, nom: e.target.value})} placeholder="Nom" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Entreprise</label>
                    <input className="w-full border p-2.5 rounded-lg text-sm" value={editForm.entreprise} onChange={e => setEditForm({...editForm, entreprise: e.target.value})} placeholder="Entreprise" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Téléphone</label>
                    <input className="w-full border p-2.5 rounded-lg text-sm" value={editForm.telephone} onChange={e => setEditForm({...editForm, telephone: e.target.value})} placeholder="Téléphone" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Spécialité</label>
                    <input className="w-full border p-2.5 rounded-lg text-sm" value={editForm.specialite} onChange={e => setEditForm({...editForm, specialite: e.target.value})} placeholder="Spécialité" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Code Salarié</label>
                    <input className="w-full border p-2.5 rounded-lg text-sm font-mono" value={editForm.codeSalarie} onChange={e => setEditForm({...editForm, codeSalarie: e.target.value})} placeholder="Code Salarié" />
                  </div>

                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Type Affaire</label>
                    <select 
                      className="w-full border p-2.5 rounded-lg text-sm font-bold bg-white"
                      value={editForm.type} 
                      onChange={e => setEditForm({...editForm, type: e.target.value})}
                    >
                      <option value="">-- Aucun --</option>
                      {availableTypes.map(type => (
                        <option key={type} value={type}>{type}</option>
                      ))}
                    </select>
                  </div>

                  <div className="md:col-span-3 space-y-1">
                    <label className="text-[9px] font-black text-indigo-500 uppercase tracking-widest ml-1">User Nextcloud</label>
                    <input className="w-full border-2 border-sky-100 p-2.5 rounded-lg text-sm font-bold bg-sky-50" value={editForm.nextcloud_user} onChange={e => setEditForm({...editForm, nextcloud_user: e.target.value})} placeholder="User Nextcloud" />
                  </div>

                  <div className="md:col-span-3 flex gap-3 justify-end mt-4 pt-4 border-t border-slate-200">
                      <button onClick={() => setEditingId(null)} className="px-5 py-2 rounded-lg text-xs font-bold text-slate-500 hover:bg-slate-200 transition-all uppercase tracking-widest">Annuler</button>
                      <button onClick={() => handleUpdate(p.id)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-lg text-xs font-black uppercase tracking-widest shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all">Enregistrer</button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex-1">
                    <div className="flex items-center gap-3">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-md ${p.type ? 'bg-indigo-600' : 'bg-slate-400'}`}>
                         <i className="fas fa-user-hard-hat"></i>
                      </div>
                      <div>
                        <div className="flex items-center gap-3">
                          <span className="font-black text-slate-800 text-lg uppercase tracking-tight">{p.nom}</span>
                          {p.type && (
                            <span className="px-2.5 py-1 rounded-full text-[9px] font-black bg-indigo-100 text-indigo-700 border border-indigo-200 uppercase tracking-widest">
                              <i className="fas fa-link mr-1"></i> {p.type}
                            </span>
                          )}
                        </div>
                        <div className="flex items-center gap-2 mt-0.5">
                           <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{p.entreprise || 'Entreprise N/A'}</span>
                           <span className="text-slate-200">•</span>
                           <span className="text-xs font-bold text-slate-600">{p.specialite || 'Pas de spécialité'}</span>
                        </div>
                      </div>
                    </div>

                    <div className="flex flex-wrap items-center gap-4 mt-4 text-[11px] font-bold text-slate-500">
                      <div className="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-lg border border-slate-200 group-hover:bg-white transition-colors">
                        <i className="fas fa-phone text-blue-500"></i>
                        <span>{p.telephone || 'Non renseigné'}</span>
                      </div>

                      {p.codeSalarie && (
                        <div className="flex items-center gap-2 bg-slate-100 px-3 py-1.5 rounded-lg border border-slate-200 group-hover:bg-white transition-colors">
                          <i className="fas fa-id-badge text-indigo-500"></i>
                          <span className="font-mono">{p.codeSalarie}</span>
                        </div>
                      )}

                      {p.nextcloud_user && (
                        <div className="flex items-center gap-2 bg-sky-50 px-3 py-1.5 rounded-lg border border-sky-100 text-sky-700 group-hover:bg-white transition-colors">
                          <i className="fas fa-cloud"></i>
                          <span className="font-black uppercase tracking-tighter">{p.nextcloud_user}</span>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-3 self-end md:self-center">
                    <button 
                      onClick={() => startEditing(p)} 
                      className="w-10 h-10 flex items-center justify-center rounded-xl text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 transition-all border border-transparent hover:border-indigo-100"
                      title="Modifier"
                    >
                      <i className="fas fa-edit"></i>
                    </button>
                    <button 
                      onClick={() => handleDelete(p.id)} 
                      className="w-10 h-10 flex items-center justify-center rounded-xl text-slate-400 hover:text-red-600 hover:bg-red-50 transition-all border border-transparent hover:border-red-100"
                      title="Supprimer"
                    >
                      <i className="fas fa-trash"></i>
                    </button>
                  </div>
                </>
              )}
            </div>
            {/* Barre de séparation visuelle subtile */}
            {index < poseurs.length - 1 && <div className="h-px bg-slate-100 mx-6 opacity-50"></div>}
          </div>
        ))}
        {poseurs.length === 0 && (
          <div className="p-20 text-center">
             <div className="w-20 h-20 bg-slate-100 rounded-3xl flex items-center justify-center mx-auto mb-4 text-slate-300">
                <i className="fas fa-users text-4xl"></i>
             </div>
             <p className="text-slate-400 font-bold uppercase text-xs tracking-widest">Aucun salarié enregistré</p>
          </div>
        )}
      </div>

      <div className="bg-amber-50 border-l-4 border-amber-400 p-4 rounded-r-xl">
        <div className="flex items-center gap-3">
          <i className="fas fa-info-circle text-amber-500"></i>
          <p className="text-xs text-amber-800 font-medium">
            <strong>Note technique :</strong> Le "Type Affaire" permet à l'IA d'attribuer automatiquement un salarié lors du scan si le client associé possède le même code (ex: O3-0).
          </p>
        </div>
      </div>
    </div>
  );
};

