  }, []);

  useEffect(() => {
    return () => { if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl); };
  }, [filePreviewUrl]);

  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  useEffect(() => {
    const nameToSearch = rawExtractedNameRef.current || extractedData?.nom_client;
    if (!nameToSearch) {
      setMappedClient(null);
      setPotentialClients([]);
      return;
    }
    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;
    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = nameToSearch.toLowerCase().trim();
      const matches = clients.filter(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || searchName.includes(clientRefNom) || clientRefNom.includes(searchName);
      });
      setPotentialClients(matches);
      if (matches.length > 0) {
          const isCurrentStillValid = mappedClient && matches.some(m => m.id === mappedClient.id);
          if (!isCurrentStillValid) setMappedClient(matches[0]);
      } else {
        setMappedClient(null);
      }
    } catch (e) { console.error("Erreur parsing clients", e); }
  }, [extractedData?.nom_client, refreshDataTrigger]);

  useEffect(() => {
    if (mappedClient && extractedData) {
        const targetLibelle = mappedClient.libelle_client || mappedClient.nom;
        if (extractedData.nom_client !== targetLibelle) {
            setExtractedData(prev => prev ? ({ ...prev, nom_client: targetLibelle }) : null);
            addLog('info', `Client mappé : ${targetLibelle}`);
        }
    }
  }, [mappedClient, addLog]);

  useEffect(() => {
    if (!mappedClient) return;
    let assignedPoseur: Poseur | undefined;
    if (mappedClient.default_poseur && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.id === mappedClient.default_poseur);
    } 
    if (!assignedPoseur && mappedClient.typeAffaire && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.type === mappedClient.typeAffaire);
    }
    if (assignedPoseur) {
        setSelectedPoseurId(assignedPoseur.id);
        addLog('info', `Poseur assigné : ${assignedPoseur.nom}`);
    }
  }, [mappedClient, allPoseurs, addLog]);

  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) { setAutoChantierNumber(null); return; }
      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;
      setIsFetchingChantier(true);
      setAutoChantierNumber(null); 
      try {
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.libelle_client || mappedClient.nom
          })
        });
        if (response.ok) {
          const result = await response.json();
          let newNumber = result.numero_affaire || result.next_id || result.value || result;
          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            addLog('response', `Numéro d'affaire récupéré : ${formattedNumber}`);
          }
        }
      } catch (e) { addLog('error', `Échec récupération numéro d'affaire.`); } finally { setIsFetchingChantier(false); }
    };
    fetchChantier();
  }, [mappedClient, addLog]);

  const handleTransmit = async () => {
      if (!extractedData) return;
      setTransmitting(true);
      setTransmitStatus('idle');
      const webhookUrl = localStorage.getItem('buildscan_webhook_url') || "";
      if (!webhookUrl) {
          addLog('error', 'URL Webhook manquante.');
          setTransmitStatus('error');
          setTransmitting(false);
          return;
      }

      const chantier = autoChantierNumber || (extractedData.num_bon_travaux ? extractedData.num_bon_travaux.replace(/\D/g, '').substring(0, 6) : "000000");
      const imputation = `80${chantier}0`;
      const fullAddress = [extractedData.adresse_1, extractedData.adresse_2, extractedData.adresse_3].filter(Boolean).join(' ');
      const contactFull = [extractedData.gardien_nom, extractedData.gardien_tel].filter(Boolean).join(' - ');
      const selectedPoseur = allPoseurs.find(p => p.id === selectedPoseurId);
      const finalClientLabel = mappedClient?.libelle_client || mappedClient?.nom || extractedData.nom_client || '';

      const formData = new FormData();
      if (originalFile) formData.append('file', originalFile, originalFile.name || 'document.pdf');

      const payload: any = {
        codeClient: mappedClient?.codeClient || '',
        code_trv: mappedClient?.typeAffaire || 'O3-0',
        client_bpu: mappedClient?.bpu || '',
        bpu: mappedClient?.bpu || '',
        client_nom: finalClientLabel,
        num_chantier: chantier,
        imputation: imputation,
        num_bon_travaux: extractedData.num_bon_travaux || '',
        nom_client_pdf: rawExtractedNameRef.current || extractedData.nom_client || '',
        categorie: extractedData.categorie || '',
        adresse_1: extractedData.adresse_1 || '',
        adresse_2: extractedData.adresse_2 || '',
        adresse_3: extractedData.adresse_3 || '',
        adresse_intervention: fullAddress,
        gardien_nom: extractedData.gardien_nom || '',
        gardien_tel: extractedData.gardien_tel || '',
        gardien_email: extractedData.gardien_email || '',
        coord_gardien: contactFull,
        delai_intervention: extractedData.delai_intervention || '',
        date_intervention: extractedData.date_intervention || '',
        descriptif_travaux: extractedData.descriptif_travaux || '',
        poseur_nom: selectedPoseur?.nom || '',
        poseur_code: selectedPoseur?.codeSalarie || ''
      };

      Object.entries(payload).forEach(([key, val]) => formData.append(key, val as string));

      // LOG DÉTAILLÉ DANS LE TERMINAL
      addLog('request', `Transmission vers n8n démarrée...`, { 
        target_url: webhookUrl,
        payload_summary: payload
      });

      try {
        const response = await fetch(webhookUrl, { method: 'POST', body: formData });
        const result = await response.json().catch(() => ({}));
        if (response.ok && (result.success !== false)) {
          setTransmitStatus('success');
          addLog('success', `Transmission réussie à n8n.`, result);
        } else {
          throw new Error(result.message || `Erreur n8n : ${response.status}`);
        }
      } catch (err: any) {
        setTransmitStatus('error');
        addLog('error', `Échec transmission: ${err.message}`);
      } finally { setTransmitting(false); }
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') { setError("Format invalide."); setStatus(AppStatus.ERROR); return; }
    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setOriginalFile(file);
    clearLogs();
    setIsSidebarOpen(false); 
    setTransmitStatus('idle');
    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);
      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(file);
      });
      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data, file.type);
      rawExtractedNameRef.current = data.nom_client;
      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      setIsHeaderVisible(false);
      addLog('success', 'Extraction IA terminée.', { pdf_client: data.nom_client });
    } catch (err: any) {
      setError(err.message || "Erreur analyse.");
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${err.message}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setOriginalFile(null);
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
    setIsSidebarOpen(true);
    setIsHeaderVisible(true);
    setTransmitStatus('idle');
  };

  if (!isInitialized) return <div className="min-h-screen bg-slate-50 flex items-center justify-center font-bold">Initialisation...</div>;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans overflow-x-hidden relative">
      {isPdfModalOpen && filePreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white w-full h-full max-w-6xl rounded-2xl shadow-2xl overflow-hidden flex flex-col relative">
              <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between">
                  <span className="font-bold text-sm uppercase">Aperçu Document</span>
                  <button onClick={() => setIsPdfModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-700 transition-colors"><i className="fas fa-times"></i></button>
              </div>
              <div className="flex-grow bg-slate-200">
                  <iframe src={`${filePreviewUrl}#toolbar=0&navpanes=0`} className="w-full h-full"></iframe>
              </div>
           </div>
        </div>
      )}
      {!isHeaderVisible && <button onClick={() => setIsHeaderVisible(true)} className="absolute top-2 right-4 z-50 bg-slate-800 text-slate-400 p-2 rounded-b-lg text-xs font-bold opacity-50 hover:opacity-100">Menu</button>}
      {isHeaderVisible && <Header currentView={currentView} onViewChange={setCurrentView} />}
      {showAuthModal && <AdminAuth onAuthenticated={() => { setIsAuthenticated(true); setShowAuthModal(false); setCurrentView('admin'); }} onCancel={() => setShowAuthModal(false)} />}
      <main className={`flex-grow container mx-auto px-4 py-8 max-w-[98%] ${!isHeaderVisible ? 'pt-4' : ''}`}>
        {currentView === 'admin' && <AdminDashboard />}
        {currentView === 'analyzer' && (
          <div className="flex flex-col lg:flex-row gap-6">
            <div className={`${isSidebarOpen ? 'lg:w-[350px]' : 'w-0 overflow-hidden'} transition-all`}>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-24">
                <h2 className="text-xl font-black mb-4 uppercase tracking-tight">Scan PDF</h2>
                <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />
                {filePreviewUrl && <iframe src={`${filePreviewUrl}#toolbar=0`} className="w-full h-[500px] border-none mt-6 rounded-xl bg-slate-100 shadow-inner" />}
              </div>
            </div>
            <div className="flex-grow flex flex-col gap-6 min-w-0">
              {status === AppStatus.IDLE && <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl mx-auto max-w-2xl mt-10">Analyseur BuildScan - Glissez un PDF</div>}
              {status === AppStatus.ANALYZING && <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center mx-auto max-w-2xl mt-10 font-bold uppercase">Extraction...</div>}
              {extractedData && (
                <div className="space-y-6">
                  <div className="grid gap-6 items-start grid-cols-1 xl:grid-cols-2">
                      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[850px]">
                        <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between"><span className="text-[10px] font-black uppercase tracking-widest">Document Source</span><button onClick={handlePdfDoubleClick} className="text-[10px] bg-slate-700 px-2 py-1 rounded font-bold uppercase transition-colors">Plein Écran</button></div>
                        <iframe src={`${filePreviewUrl}#navpanes=0&scrollbar=1`} className="w-full h-full border-none" />
                      </div>
                      <ResultCard 
                          data={extractedData} 
                          onReset={reset} 
                          mappedClient={mappedClient}
                          potentialClients={potentialClients}
                          onClientMatchUpdate={(id) => { const s = potentialClients.find(c => c.id === id); if(s) setMappedClient(s); }}
                          chantierNumber={autoChantierNumber}
                          isFetchingChantier={isFetchingChantier}
                          onUpdate={(upd) => setExtractedData(prev => prev ? ({...prev, ...upd}) : null)}
                          poseurs={allPoseurs}
                          selectedPoseurId={selectedPoseurId}
                          onPoseurSelect={setSelectedPoseurId}
                          onTransmit={handleTransmit}
                          isTransmitting={transmitting}
                          transmitStatus={transmitStatus}
                          rawPdfClientName={rawExtractedNameRef.current}
                      />
                  </div>
                  <SqlExporter data={extractedData} mappedClient={mappedClient} prefilledChantierNumber={autoChantierNumber} logs={logs} onAddLog={addLog} onClearLogs={clearLogs} />
                </div>
              )}
            </div>
          </div>
        )}
      </main>
      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.7 • ERP Connector</footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Poseur } from '../types';
import { fetchStorageConfig, addPoseur, updatePoseur, deletePoseur } from '../services/configService';

const AdminPoseurs: React.FC = () => {
  const [poseurs, setPoseurs] = useState<Poseur[]>([]);
  const [availableTypes, setAvailableTypes] = useState<string[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const initialForm = { nom: '', entreprise: '', telephone: '', specialite: '', codeSalarie: '', type: '' };
  const [newPoseur, setNewPoseur] = useState<Omit<Poseur, 'id'>>(initialForm);
  const [editForm, setEditForm] = useState<Omit<Poseur, 'id'>>(initialForm);

  const reloadData = async () => {
    const config = await fetchStorageConfig();
    if (config) {
      setPoseurs(config.poseurs);
      const types = Array.from(new Set(config.clients.map(c => c.typeAffaire).filter(Boolean)));
      setAvailableTypes(types.sort());
    }
  };

  useEffect(() => { reloadData(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    const result = await addPoseur(newPoseur);
    if (result) { setNewPoseur(initialForm); setIsAdding(false); await reloadData(); }
    setIsSaving(false);
  };

  const handleUpdate = async (id: string) => {
    setIsSaving(true);
    if (await updatePoseur(id, editForm)) { setEditingId(null); await reloadData(); }
    setIsSaving(false);
  };

  const startEditing = (p: Poseur) => {
    setEditingId(p.id);
    setEditForm({ nom: p.nom, entreprise: p.entreprise, telephone: p.telephone, specialite: p.specialite, codeSalarie: p.codeSalarie, type: p.type || '' });
  };

  return (
    <div className="animate-in fade-in duration-500 space-y-6">
      <div className="flex items-center justify-between bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Gestion Flotte</h2>
          <p className="text-slate-500 text-sm font-medium">Référentiel des salariés et sous-traitants.</p>
        </div>
        <button onClick={() => setIsAdding(!isAdding)} className={`px-6 py-2.5 rounded-xl font-black uppercase text-xs transition-all shadow-lg ${isAdding ? 'bg-slate-200 text-slate-700' : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-200'}`}>
          {isAdding ? 'Annuler' : '+ Ajouter Salarié'}
        </button>
      </div>

      {isAdding && (
        <form onSubmit={handleAdd} className="bg-white p-8 rounded-2xl border-2 border-indigo-100 shadow-xl grid grid-cols-1 md:grid-cols-2 gap-5 animate-in slide-in-from-top-4">
          <input placeholder="Nom Complet" className="w-full p-3 border rounded-xl" value={newPoseur.nom} onChange={e => setNewPoseur({...newPoseur, nom: e.target.value})} required />
          <input placeholder="Entreprise" className="w-full p-3 border rounded-xl" value={newPoseur.entreprise} onChange={e => setNewPoseur({...newPoseur, entreprise: e.target.value})} />
          <input placeholder="Téléphone" className="w-full p-3 border rounded-xl" value={newPoseur.telephone} onChange={e => setNewPoseur({...newPoseur, telephone: e.target.value})} />
          <input placeholder="Code Salarié" className="w-full p-3 border rounded-xl font-mono" value={newPoseur.codeSalarie} onChange={e => setNewPoseur({...newPoseur, codeSalarie: e.target.value})} />
          <input placeholder="Spécialité" className="w-full p-3 border rounded-xl" value={newPoseur.specialite} onChange={e => setNewPoseur({...newPoseur, specialite: e.target.value})} />
          <select className="w-full p-3 border rounded-xl bg-slate-50 font-bold" value={newPoseur.type} onChange={e => setNewPoseur({...newPoseur, type: e.target.value})}>
             <option value="">-- Aucun mapping auto --</option>
             {availableTypes.map(type => <option key={type} value={type}>{type}</option>)}
          </select>
          <button type="submit" disabled={isSaving} className="col-span-2 bg-emerald-600 text-white py-4 rounded-xl font-black uppercase tracking-widest hover:bg-emerald-700 shadow-lg">Enregistrer</button>
        </form>
      )}

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden divide-y divide-slate-100">
        {poseurs.map((p) => (
          <div key={p.id} className="p-6 flex flex-col md:flex-row md:items-center justify-between hover:bg-slate-50 transition-all gap-6 border-b-8 border-slate-50 last:border-b-0">
            {editingId === p.id ? (
              <div className="w-full grid grid-cols-1 md:grid-cols-3 gap-4 bg-slate-50 p-6 rounded-2xl border border-indigo-100">
                <input className="border p-2 rounded text-sm font-bold" value={editForm.nom} onChange={e => setEditForm({...editForm, nom: e.target.value})} />
                <input className="border p-2 rounded text-sm" value={editForm.entreprise} onChange={e => setEditForm({...editForm, entreprise: e.target.value})} />
                <input className="border p-2 rounded text-sm" value={editForm.telephone} onChange={e => setEditForm({...editForm, telephone: e.target.value})} />
                <input className="border p-2 rounded text-sm" value={editForm.specialite} onChange={e => setEditForm({...editForm, specialite: e.target.value})} />
                <input className="border p-2 rounded text-sm font-mono" value={editForm.codeSalarie} onChange={e => setEditForm({...editForm, codeSalarie: e.target.value})} />
                <select className="border p-2 rounded text-sm font-bold" value={editForm.type} onChange={e => setEditForm({...editForm, type: e.target.value})}>
                  <option value="">-- Aucun --</option>
                  {availableTypes.map(type => <option key={type} value={type}>{type}</option>)}
                </select>
                <div className="md:col-span-3 flex gap-3 justify-end mt-4 pt-4 border-t border-slate-200">
                    <button onClick={() => setEditingId(null)} className="px-5 py-2 rounded-lg text-xs font-bold uppercase">Annuler</button>
                    <button onClick={() => handleUpdate(p.id)} className="bg-emerald-600 text-white px-8 py-2.5 rounded-lg text-xs font-black uppercase shadow-lg">Enregistrer</button>
                </div>
              </div>
            ) : (
              <>
                <div className="flex-1 flex items-center gap-4">
                  <div className={`w-12 h-12 rounded-xl flex items-center justify-center text-white shadow-md ${p.type ? 'bg-indigo-600' : 'bg-slate-400'}`}><i className="fas fa-user-hard-hat"></i></div>
                  <div>
                    <div className="flex items-center gap-3"><span className="font-black text-slate-800 text-lg uppercase">{p.nom}</span>{p.type && <span className="px-2.5 py-1 rounded-full text-[9px] font-black bg-indigo-100 text-indigo-700 uppercase tracking-widest">{p.type}</span>}</div>
                    <div className="flex items-center gap-2 text-xs font-bold text-slate-500 mt-1"><span>{p.entreprise || 'SAMDB'}</span><span className="text-slate-200">•</span><span>{p.specialite || 'Poseur'}</span><span className="text-slate-200">•</span><span className="font-mono">{p.codeSalarie}</span></div>
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={() => startEditing(p)} className="w-10 h-10 flex items-center justify-center rounded-xl text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 border border-transparent transition-all"><i className="fas fa-edit"></i></button>
                  <button onClick={async () => { if(confirm("Supprimer?")) { await deletePoseur(p.id); reloadData(); } }} className="w-10 h-10 flex items-center justify-center rounded-xl text-slate-400 hover:text-red-600 hover:bg-red-50 border border-transparent transition-all"><i className="fas fa-trash"></i></button>
                </div>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdminPoseurs;

import React, { useEffect } from 'react';
import { ConstructionOrderData, Client, Poseur } from '../types';

interface ResultCardProps {
  data: ConstructionOrderData;
  onReset: () => void;
  mappedClient: Client | null;
  potentialClients?: Client[]; 
  onClientMatchUpdate?: (clientId: string) => void; 
  chantierNumber: string | null;
  isFetchingChantier: boolean;
  onUpdate: (updates: Partial<ConstructionOrderData>) => void;
  poseurs: Poseur[];
  selectedPoseurId: string;
  onPoseurSelect: (id: string) => void;
  onTransmit: () => void;
  isTransmitting: boolean;
  transmitStatus: 'idle' | 'success' | 'error';
  rawPdfClientName?: string | null; 
}

const ResultCard: React.FC<ResultCardProps> = ({ 
    data, onReset, mappedClient, potentialClients = [], onClientMatchUpdate,
    chantierNumber, isFetchingChantier, onUpdate, poseurs, selectedPoseurId,
    onPoseurSelect, onTransmit, isTransmitting, transmitStatus, rawPdfClientName
}) => {

  const handleInputChange = (field: keyof ConstructionOrderData, value: string) => {
    onUpdate({ [field]: value });
  };

  useEffect(() => {
    if (data.date_intervention) {
        let formattedDate = data.date_intervention;
        if (formattedDate.match(/^\d{4}-\d{2}-\d{2}$/)) {
            const [year, month, day] = formattedDate.split('-');
            formattedDate = `${day}/${month}/${year}`;
        }
        if (formattedDate !== data.date_intervention) onUpdate({ date_intervention: formattedDate });
    }
  }, [data.date_intervention]);

  const categories = [{ code: "01", label: "01 Locataire" }, { code: "02", label: "02 Parties communes" }, { code: "03", label: "03 Logement vacant" }, { code: "04", label: "04 Maintenance" }];
  const fields = [
    { key: "num_bon_travaux", label: "Numéro de Bon", icon: "fa-hashtag", color: "text-blue-600" },
    { key: "nom_client", label: mappedClient ? "Libellé Client (ERP)" : "Nom Client (PDF)", icon: "fa-building", color: mappedClient ? "text-emerald-600" : "text-indigo-600" },
    { key: "date_intervention", label: "Date du Document", icon: "fa-file-signature", color: "text-purple-600" },
    { key: "delai_intervention", label: "Délai / Échéance", icon: "fa-calendar-alt", color: "text-orange-600" },
  ];

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-full flex flex-col">
      <div className="bg-slate-50 border-b border-slate-200 px-6 py-4 flex items-center justify-between">
        <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2"><i className="fas fa-check-circle text-green-500"></i>Résultats de l'extraction</h2>
        <button onClick={onReset} className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-blue-700 transition-colors">Nouveau Scan</button>
      </div>

      {mappedClient ? (
        <div className="mx-6 mt-6 bg-emerald-50 border-2 border-emerald-100 rounded-xl p-5 shadow-sm animate-in zoom-in-95">
          <div className="flex items-start justify-between mb-4">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-emerald-600 text-white rounded-lg flex items-center justify-center shadow-lg"><i className="fas fa-link text-xl"></i></div>
              <div>
                <p className="text-[10px] font-black text-emerald-700 uppercase tracking-widest">Compte ERP SAMDB Actif</p>
                <p className="text-lg font-black text-slate-800 leading-tight">{mappedClient.libelle_client || mappedClient.nom}</p>
                <p className="text-xs text-emerald-700 font-bold uppercase mt-1">Code : <span className="font-mono">{mappedClient.codeClient}</span></p>
              </div>
            </div>
            <button disabled={isTransmitting || transmitStatus === 'success'} onClick={onTransmit} className={`px-6 py-3 rounded-xl font-bold text-sm transition-all flex items-center gap-2 shadow-lg ${transmitStatus === 'success' ? 'bg-green-600 text-white' : transmitStatus === 'error' ? 'bg-red-600 text-white' : 'bg-slate-800 text-white shadow-slate-900/20'}`}>
              {isTransmitting ? 'Envoi...' : transmitStatus === 'success' ? 'Envoyé' : 'Transmettre'}
            </button>
          </div>
          <div className="grid grid-cols-2 lg:grid-cols-5 gap-4 border-t border-emerald-200 pt-3">
             <div><p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Affaire</p><span className="font-mono font-black text-slate-800 text-lg">{chantierNumber || '-'}</span></div>
             <div><p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Catégorie</p><select value={data.categorie || ""} onChange={(e) => handleInputChange('categorie', e.target.value)} className="w-full font-bold text-slate-800 text-sm bg-white border border-emerald-300 px-2 py-1.5 rounded">{categories.map(cat => <option key={cat.code} value={cat.code}>{cat.label}</option>)}</select></div>
             <div><p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Assignation</p><select value={selectedPoseurId} onChange={(e) => onPoseurSelect(e.target.value)} className="w-full font-bold text-slate-800 text-sm bg-white border border-emerald-300 px-2 py-1.5 rounded"><option value="">-- Non assigné --</option>{poseurs.map(p => <option key={p.id} value={p.id}>{p.nom}</option>)}</select></div>
             <div><p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">BPU</p><span className="font-mono font-black text-slate-700 text-sm bg-white border border-emerald-300 px-2 py-1.5 rounded block">{mappedClient.bpu || '-'}</span></div>
             <div><p className="text-[10px] font-bold text-emerald-600 uppercase mb-1">Client</p><select value={mappedClient.id} onChange={(e) => onClientMatchUpdate?.(e.target.value)} className="w-full font-bold text-slate-800 text-sm bg-white border border-emerald-300 px-2 py-1.5 rounded">{potentialClients.map(c => <option key={c.id} value={c.id}>{c.nom}</option>)}</select></div>
          </div>
        </div>
      ) : (
        <div className="mx-6 mt-6 bg-slate-50 border border-dashed rounded-lg p-4 flex items-center gap-3"><i className="fas fa-exclamation-circle text-slate-400"></i><p className="text-xs text-slate-500 font-medium">Aucun mapping client trouvé pour "<span className="font-bold">{data.nom_client || 'Inconnu'}</span>".</p></div>
      )}

      <div className="mx-6 mt-6 p-4 bg-blue-50/50 border border-blue-100 rounded-xl">
        <div className="flex items-center gap-2 mb-2"><i className="fas fa-tools text-blue-500 text-xs"></i><span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Descriptif des Travaux</span></div>
        <textarea value={data.descriptif_travaux || ""} onChange={(e) => handleInputChange('descriptif_travaux', e.target.value)} rows={4} className="w-full bg-white border border-blue-100 rounded-lg p-3 text-sm font-semibold text-slate-800 focus:outline-none focus:border-blue-400 resize-none" />
      </div>

      <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-1 md:col-span-2">
          <div className="flex items-center gap-2 mb-1"><i className="fas fa-map-marker-alt text-red-600 w-4"></i><span className="text-xs font-bold text-slate-400 uppercase">Adresse d'intervention (3 Lignes)</span></div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {['adresse_1', 'adresse_2', 'adresse_3'].map((k) => (
              <div key={k} className="p-3 rounded-lg border bg-slate-50/50 flex flex-col focus-within:bg-white focus-within:border-blue-200 transition-all">
                <span className="text-[9px] text-slate-400 font-bold uppercase mb-1">{k.replace('_', ' ')}</span>
                <input type="text" value={(data as any)[k] || ""} onChange={(e) => handleInputChange(k as any, e.target.value)} className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0" placeholder="-" />
              </div>
            ))}
          </div>
        </div>
        <div className="space-y-1 md:col-span-2">
           <div className="flex items-center gap-2 mb-1"><i className="fas fa-user-tie text-emerald-600 w-4"></i><span className="text-xs font-bold text-slate-400 uppercase">Contact / Gardien / Locataire</span></div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <div className="p-3 rounded-lg border bg-slate-50/50 flex flex-col focus-within:bg-white focus-within:border-emerald-200 transition-all"><span className="text-[9px] text-slate-400 font-bold uppercase mb-1">Nom</span><input type="text" value={data.gardien_nom || ""} onChange={(e) => handleInputChange('gardien_nom', e.target.value)} className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0" /></div>
                <div className="p-3 rounded-lg border bg-slate-50/50 flex flex-col focus-within:bg-white focus-within:border-emerald-200 transition-all"><span className="text-[9px] text-slate-400 font-bold uppercase mb-1">Tel</span><input type="text" value={data.gardien_tel || ""} onChange={(e) => handleInputChange('gardien_tel', e.target.value)} className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0" /></div>
                <div className="p-3 rounded-lg border bg-slate-50/50 flex flex-col focus-within:bg-white focus-within:border-emerald-200 transition-all"><span className="text-[9px] text-slate-400 font-bold uppercase mb-1">Email</span><input type="text" value={data.gardien_email || ""} onChange={(e) => handleInputChange('gardien_email', e.target.value)} className="bg-transparent border-none p-0 text-sm font-bold text-slate-900 focus:ring-0" /></div>
            </div>
        </div>
        {fields.map((f) => (
          <div key={f.key} className="space-y-1">
            <div className="flex items-center gap-2 mb-1"><i className={`fas ${f.icon} ${f.color} w-4`}></i><span className="text-xs font-bold text-slate-400 uppercase">{f.label}</span></div>
            <div className="p-3 rounded-lg border bg-slate-50/50 min-h-[44px] flex items-center transition-all focus-within:bg-white focus-within:border-blue-400">
              <input type="text" value={(data as any)[f.key] || ""} onChange={(e) => handleInputChange(f.key as any, e.target.value)} className="bg-transparent border-none p-0 w-full font-bold text-slate-900 focus:ring-0" placeholder="N/A" />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ResultCard;

export interface ConstructionOrderData {
  num_bon_travaux: string | null;
  adresse_1: string | null;
  adresse_2: string | null;
  adresse_3: string | null;
  // Separation des données gardien
  gardien_nom: string | null;
  gardien_tel: string | null;
  gardien_email: string | null;

  nom_client: string | null;
  delai_intervention: string | null;
  date_intervention: string | null;
  descriptif_travaux: string | null;
  categorie: string | null;
}

export interface Poseur {
  id: string;
  nom: string;
  entreprise: string;
  telephone: string;
  specialite: string;
  codeSalarie: string;
  type?: string; // Lien avec le Type Affaire du client
  nextcloud_user?: string;
}

export interface Client {
  id: string;
  nom: string; // Nom tel qu'il apparaît sur les PDF
  libelle_client?: string; // Libellé propre pour l'ERP/n8n
  codeClient: string; // ex: 411DRA038
  typeAffaire: string; // ex: O3-0
  bpu?: string; // Code BPU
  default_poseur?: string; // ID du poseur par défaut (Relation PocketBase)
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'request' | 'response' | 'error';
  message: string;
  data?: any;
}

export interface ExtractionResult {
  data: ConstructionOrderData;
  rawJson: string;
}

export enum AppStatus {
  IDLE = 'IDLE',
  UPLOADING = 'UPLOADING',
  ANALYZING = 'ANALYZING',
  SUCCESS = 'SUCCESS',
  ERROR = 'ERROR'
}

export type AppView = 'analyzer' | 'admin';

// Ajout des interfaces manquantes pour le CalendarManager
export interface NextcloudConfig {
  url: string;
}

export interface CalendarEvent {
  uid: string;
  title: string;
  start: string;
  end: string;
  location?: string;
  description?: string;
  isTentative?: boolean;
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { AppStatus, ConstructionOrderData, AppView, Client, Poseur, LogEntry } from './types';
import { analyzeConstructionDocument } from './services/geminiService';
import { fetchStorageConfig } from './services/configService';
import Header from './components/Header';
import FileUploader from './components/FileUploader';
import ResultCard from './components/ResultCard';
import SqlExporter from './components/SqlExporter';
import AdminDashboard from './components/AdminDashboard';
import AdminAuth from './components/AdminAuth';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('analyzer');
  const [status, setStatus] = useState<AppStatus>(AppStatus.IDLE);
  const [error, setError] = useState<string | null>(null);
  const [filePreviewUrl, setFilePreviewUrl] = useState<string | null>(null);
  const [originalFile, setOriginalFile] = useState<File | null>(null);
  const [extractedData, setExtractedData] = useState<ConstructionOrderData | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);

  // Layout State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isHeaderVisible, setIsHeaderVisible] = useState(true);
  const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);

  // Terminal Logs State
  const [logs, setLogs] = useState<LogEntry[]>([]);

  // Data enrichment states
  const [mappedClient, setMappedClient] = useState<Client | null>(null);
  const [potentialClients, setPotentialClients] = useState<Client[]>([]); 
  const [autoChantierNumber, setAutoChantierNumber] = useState<string | null>(null);
  const [isFetchingChantier, setIsFetchingChantier] = useState(false);

  const rawExtractedNameRef = useRef<string | null>(null);
  const [refreshDataTrigger, setRefreshDataTrigger] = useState(0);

  const [selectedPoseurId, setSelectedPoseurId] = useState<string>("");
  const [allPoseurs, setAllPoseurs] = useState<Poseur[]>([]);

  const [transmitting, setTransmitting] = useState(false);
  const [transmitStatus, setTransmitStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [showAuthModal, setShowAuthModal] = useState(false);

  useEffect(() => {
    const initApp = async () => {
      const config = await fetchStorageConfig();
      if (config) setAllPoseurs(config.poseurs);
      setIsInitialized(true);
    };
    initApp();
  }, []);

  useEffect(() => {
    return () => { if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl); };
  }, [filePreviewUrl]);

  const addLog = useCallback((type: LogEntry['type'], message: string, data?: any) => {
    const newLog: LogEntry = {
      id: crypto.randomUUID(),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      data
    };
    setLogs(prev => [...prev, newLog]);
  }, []);

  const clearLogs = useCallback(() => setLogs([]), []);

  // Fix: handlePdfDoubleClick must be defined to be used in the JSX below
  const handlePdfDoubleClick = useCallback(() => setIsPdfModalOpen(true), []);

  useEffect(() => {
    const nameToSearch = rawExtractedNameRef.current || extractedData?.nom_client;
    if (!nameToSearch) {
      setMappedClient(null);
      setPotentialClients([]);
      return;
    }
    const saved = localStorage.getItem('buildscan_clients');
    if (!saved) return;
    try {
      const clients: Client[] = JSON.parse(saved);
      const searchName = nameToSearch.toLowerCase().trim();
      const matches = clients.filter(c => {
        const clientRefNom = c.nom.toLowerCase().trim();
        return searchName === clientRefNom || searchName.includes(clientRefNom) || clientRefNom.includes(searchName);
      });
      setPotentialClients(matches);
      if (matches.length > 0) {
          const isCurrentStillValid = mappedClient && matches.some(m => m.id === mappedClient.id);
          if (!isCurrentStillValid) setMappedClient(matches[0]);
      } else {
        setMappedClient(null);
      }
    } catch (e) { console.error("Erreur parsing clients", e); }
  }, [extractedData?.nom_client, refreshDataTrigger, mappedClient]);

  useEffect(() => {
    if (mappedClient && extractedData) {
        const targetLibelle = mappedClient.libelle_client || mappedClient.nom;
        if (extractedData.nom_client !== targetLibelle) {
            setExtractedData(prev => prev ? ({ ...prev, nom_client: targetLibelle }) : null);
            addLog('info', `Client mappé : ${targetLibelle}`);
        }
    }
  }, [mappedClient, addLog]);

  useEffect(() => {
    if (!mappedClient) return;
    let assignedPoseur: Poseur | undefined;
    if (mappedClient.default_poseur && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.id === mappedClient.default_poseur);
    } 
    if (!assignedPoseur && mappedClient.typeAffaire && allPoseurs.length > 0) {
        assignedPoseur = allPoseurs.find(p => p.type === mappedClient.typeAffaire);
    }
    if (assignedPoseur) {
        setSelectedPoseurId(assignedPoseur.id);
        addLog('info', `Poseur assigné : ${assignedPoseur.nom}`);
    }
  }, [mappedClient, allPoseurs, addLog]);

  useEffect(() => {
    const fetchChantier = async () => {
      if (!mappedClient) { setAutoChantierNumber(null); return; }
      const url = localStorage.getItem('buildscan_client_webhook_url');
      if (!url) return;
      setIsFetchingChantier(true);
      setAutoChantierNumber(null); 
      try {
        const response = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 
            typeAffaire: mappedClient.typeAffaire,
            codeClient: mappedClient.codeClient,
            nomClient: mappedClient.libelle_client || mappedClient.nom
          })
        });
        if (response.ok) {
          const result = await response.json();
          let newNumber = result.numero_affaire || result.next_id || result.value || result;
          if (newNumber) {
            const cleanNumber = String(newNumber).replace(/\D/g, '');
            const formattedNumber = cleanNumber.length > 6 ? cleanNumber.substring(cleanNumber.length - 6) : cleanNumber.padStart(6, '0');
            setAutoChantierNumber(formattedNumber);
            addLog('response', `Numéro d'affaire récupéré : ${formattedNumber}`);
          }
        }
      } catch (e) { addLog('error', `Échec récupération numéro d'affaire.`); } finally { setIsFetchingChantier(false); }
    };
    fetchChantier();
  }, [mappedClient, addLog]);

  const handleTransmit = async () => {
      if (!extractedData) return;
      setTransmitting(true);
      setTransmitStatus('idle');
      const webhookUrl = localStorage.getItem('buildscan_webhook_url') || "";
      if (!webhookUrl) {
          addLog('error', 'URL Webhook manquante.');
          setTransmitStatus('error');
          setTransmitting(false);
          return;
      }

      const chantier = autoChantierNumber || (extractedData.num_bon_travaux ? extractedData.num_bon_travaux.replace(/\D/g, '').substring(0, 6) : "000000");
      const imputation = `80${chantier}0`;
      const fullAddress = [extractedData.adresse_1, extractedData.adresse_2, extractedData.adresse_3].filter(Boolean).join(' ');
      const contactFull = [extractedData.gardien_nom, extractedData.gardien_tel].filter(Boolean).join(' - ');
      const selectedPoseur = allPoseurs.find(p => p.id === selectedPoseurId);
      const finalClientLabel = mappedClient?.libelle_client || mappedClient?.nom || extractedData.nom_client || '';

      const formData = new FormData();
      if (originalFile) formData.append('file', originalFile, originalFile.name || 'document.pdf');

      const payload: any = {
        codeClient: mappedClient?.codeClient || '',
        code_trv: mappedClient?.typeAffaire || 'O3-0',
        client_bpu: mappedClient?.bpu || '',
        bpu: mappedClient?.bpu || '',
        client_nom: finalClientLabel,
        num_chantier: chantier,
        imputation: imputation,
        num_bon_travaux: extractedData.num_bon_travaux || '',
        nom_client_pdf: rawExtractedNameRef.current || extractedData.nom_client || '',
        categorie: extractedData.categorie || '',
        adresse_1: extractedData.adresse_1 || '',
        adresse_2: extractedData.adresse_2 || '',
        adresse_3: extractedData.adresse_3 || '',
        adresse_intervention: fullAddress,
        gardien_nom: extractedData.gardien_nom || '',
        gardien_tel: extractedData.gardien_tel || '',
        gardien_email: extractedData.gardien_email || '',
        coord_gardien: contactFull,
        delai_intervention: extractedData.delai_intervention || '',
        date_intervention: extractedData.date_intervention || '',
        descriptif_travaux: extractedData.descriptif_travaux || '',
        poseur_nom: selectedPoseur?.nom || '',
        poseur_code: selectedPoseur?.codeSalarie || ''
      };

      Object.entries(payload).forEach(([key, val]) => formData.append(key, val as string));

      // LOG DÉTAILLÉ DANS LE TERMINAL
      addLog('request', `Transmission vers n8n démarrée...`, { 
        target_url: webhookUrl,
        payload_summary: payload
      });

      try {
        const response = await fetch(webhookUrl, { method: 'POST', body: formData });
        const result = await response.json().catch(() => ({}));
        if (response.ok && (result.success !== false)) {
          setTransmitStatus('success');
          addLog('success', `Transmission réussie à n8n.`, result);
        } else {
          throw new Error(result.message || `Erreur n8n : ${response.status}`);
        }
      } catch (err: any) {
        setTransmitStatus('error');
        addLog('error', `Échec transmission: ${err.message}`);
      } finally { setTransmitting(false); }
  };

  const handleFileSelect = useCallback(async (file: File) => {
    if (file.type !== 'application/pdf') { setError("Format invalide."); setStatus(AppStatus.ERROR); return; }
    setStatus(AppStatus.ANALYZING);
    setError(null);
    setExtractedData(null);
    setOriginalFile(file);
    clearLogs();
    setIsSidebarOpen(false); 
    setTransmitStatus('idle');
    try {
      const url = URL.createObjectURL(file);
      setFilePreviewUrl(url);
      const base64Promise = new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(file);
      });
      const base64Data = await base64Promise;
      const data = await analyzeConstructionDocument(base64Data as string, file.type);
      rawExtractedNameRef.current = data.nom_client;
      setExtractedData(data);
      setStatus(AppStatus.SUCCESS);
      setIsHeaderVisible(false);
      addLog('success', 'Extraction IA terminée.', { pdf_client: data.nom_client });
    } catch (err: any) {
      setError(err.message || "Erreur analyse.");
      setStatus(AppStatus.ERROR);
      addLog('error', `Échec de l'analyse: ${err.message}`);
    }
  }, [addLog, clearLogs]);

  const reset = () => {
    setStatus(AppStatus.IDLE);
    setExtractedData(null);
    setMappedClient(null);
    setOriginalFile(null);
    if (filePreviewUrl) URL.revokeObjectURL(filePreviewUrl);
    setFilePreviewUrl(null);
    clearLogs();
    setIsSidebarOpen(true);
    setIsHeaderVisible(true);
    setTransmitStatus('idle');
  };

  if (!isInitialized) return <div className="min-h-screen bg-slate-50 flex items-center justify-center font-bold">Initialisation...</div>;

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans overflow-x-hidden relative">
      {isPdfModalOpen && filePreviewUrl && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-4">
           <div className="bg-white w-full h-full max-w-6xl rounded-2xl shadow-2xl overflow-hidden flex flex-col relative">
              <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between">
                  <span className="font-bold text-sm uppercase">Aperçu Document</span>
                  <button onClick={() => setIsPdfModalOpen(false)} className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-slate-700 transition-colors"><i className="fas fa-times"></i></button>
              </div>
              <div className="flex-grow bg-slate-200">
                  <iframe src={`${filePreviewUrl}#toolbar=0&navpanes=0`} className="w-full h-full"></iframe>
              </div>
           </div>
        </div>
      )}
      {!isHeaderVisible && <button onClick={() => setIsHeaderVisible(true)} className="absolute top-2 right-4 z-50 bg-slate-800 text-slate-400 p-2 rounded-b-lg text-xs font-bold opacity-50 hover:opacity-100">Menu</button>}
      {isHeaderVisible && <Header currentView={currentView} onViewChange={setCurrentView} />}
      {showAuthModal && <AdminAuth onAuthenticated={() => { setIsAuthenticated(true); setShowAuthModal(false); setCurrentView('admin'); }} onCancel={() => setShowAuthModal(false)} />}
      <main className={`flex-grow container mx-auto px-4 py-8 max-w-[98%] ${!isHeaderVisible ? 'pt-4' : ''}`}>
        {currentView === 'admin' && <AdminDashboard />}
        {currentView === 'analyzer' && (
          <div className="flex flex-col lg:flex-row gap-6">
            <div className={`${isSidebarOpen ? 'lg:w-[350px]' : 'w-0 overflow-hidden'} transition-all`}>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200 sticky top-24">
                <h2 className="text-xl font-black mb-4 uppercase tracking-tight">Scan PDF</h2>
                <FileUploader onFileSelect={handleFileSelect} disabled={status === AppStatus.ANALYZING} />
                {filePreviewUrl && <iframe src={`${filePreviewUrl}#toolbar=0`} className="w-full h-[500px] border-none mt-6 rounded-xl bg-slate-100 shadow-inner" />}
              </div>
            </div>
            <div className="flex-grow flex flex-col gap-6 min-w-0">
              {status === AppStatus.IDLE && <div className="bg-blue-600 rounded-2xl p-10 text-center text-white shadow-xl mx-auto max-w-2xl mt-10">Analyseur BuildScan - Glissez un PDF</div>}
              {status === AppStatus.ANALYZING && <div className="bg-white border-2 border-blue-50 rounded-2xl p-16 text-center mx-auto max-w-2xl mt-10 font-bold uppercase">Extraction...</div>}
              {extractedData && (
                <div className="space-y-6">
                  <div className="grid gap-6 items-start grid-cols-1 xl:grid-cols-2">
                      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[850px]">
                        <div className="bg-slate-800 text-white px-4 py-2 flex items-center justify-between"><span className="text-[10px] font-black uppercase tracking-widest">Document Source</span><button onClick={handlePdfDoubleClick} className="text-[10px] bg-slate-700 px-2 py-1 rounded font-bold uppercase transition-colors">Plein Écran</button></div>
                        <iframe src={`${filePreviewUrl}#navpanes=0&scrollbar=1`} className="w-full h-full border-none" />
                      </div>
                      <ResultCard 
                          data={extractedData} 
                          onReset={reset} 
                          mappedClient={mappedClient}
                          potentialClients={potentialClients}
                          onClientMatchUpdate={(id) => { const s = potentialClients.find(c => c.id === id); if(s) setMappedClient(s); }}
                          chantierNumber={autoChantierNumber}
                          isFetchingChantier={isFetchingChantier}
                          onUpdate={(upd) => setExtractedData(prev => prev ? ({...prev, ...upd}) : null)}
                          poseurs={allPoseurs}
                          selectedPoseurId={selectedPoseurId}
                          onPoseurSelect={setSelectedPoseurId}
                          onTransmit={handleTransmit}
                          isTransmitting={transmitting}
                          transmitStatus={transmitStatus}
                          rawPdfClientName={rawExtractedNameRef.current}
                      />
                  </div>
                  <SqlExporter data={extractedData} mappedClient={mappedClient} prefilledChantierNumber={autoChantierNumber} logs={logs} onAddLog={addLog} onClearLogs={clearLogs} />
                </div>
              )}
            </div>
          </div>
        )}
      </main>
      <footer className="bg-white border-t border-slate-200 py-6 text-center text-slate-400 text-xs font-bold uppercase tracking-widest">BuildScan AI v2.7 • ERP Connector</footer>
    </div>
  );
};

export default App;

import React, { useEffect } from 'react';
import { ConstructionOrderData, Client, Poseur } from '../types';

interface ResultCardProps {
