import React, { useState } from 'react';

interface AdminAuthProps {
  onAuthenticated: () => void;
  onCancel: () => void;
}

const AdminAuth: React.FC<AdminAuthProps> = ({ onAuthenticated, onCancel }) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Utilise la variable d'env fournie par Coolify/Vite ou le fallback par défaut
    const requiredPassword = process.env.PANEL_ADMIN_PASSWORD || '123456789';

    if (password === requiredPassword) {
      onAuthenticated();
    } else {
      setError(true);
      setPassword('');
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-sm z-50 flex items-center justify-center p-4 animate-in fade-in duration-200">
